function initDatabase(dbPath: string): Database.Database {
  try {
    const parentDir = path.dirname(dbPath);
    if (parentDir && parentDir !== '.' && !fs.existsSync(parentDir)) {
      try {
        fs.mkdirSync(parentDir, { recursive: true });
      } catch (dirErr) {
        console.warn(`[SQLite Init] Could not create parent dir ${parentDir}:`, dirErr);
      }
    }
    const dbInstance = new Database(dbPath);
    // Verify database health
    const check = dbInstance.pragma('quick_check') as any[];
    if (!check || check.length === 0 || check[0]?.quick_check !== 'ok') {
      throw new Error(`Database quick_check failed: ${JSON.stringify(check)}`);
    }
    dbInstance.pragma('journal_mode = WAL');
    dbInstance.pragma('synchronous = NORMAL');
    dbInstance.pragma('foreign_keys = ON');
    dbInstance.pragma('wal_autocheckpoint = 500');
    return dbInstance;
  } catch (err: any) {
    console.error(`[SQLite Error] Corrupted or invalid database at ${dbPath}:`, err?.message);
    if (fs.existsSync(dbPath)) {
      const backupCorrupt = `${dbPath}.corrupt.${Date.now()}`;
      try {
        fs.copyFileSync(dbPath, backupCorrupt);
        fs.unlinkSync(dbPath);
        if (fs.existsSync(`${dbPath}-wal`)) fs.unlinkSync(`${dbPath}-wal`);
        if (fs.existsSync(`${dbPath}-shm`)) fs.unlinkSync(`${dbPath}-shm`);
        console.log(`[SQLite Recovery] Corrupted DB backed up to ${backupCorrupt} and fresh database initialized.`);
      } catch (backupErr) {
        console.error('[SQLite Recovery] Failed to backup corrupt file:', backupErr);
      }
    }
    const freshDb = new Database(dbPath);
    freshDb.pragma('journal_mode = WAL');
    freshDb.pragma('synchronous = NORMAL');
    freshDb.pragma('foreign_keys = ON');
    return freshDb;
  }
}

const db = initDatabase(DATABASE_PATH);

// Graceful cleanup to ensure WAL pages are flushed and checkpointed
const flushAndCloseDb = () => {
  try {
    if (db && db.open) {
      db.pragma('wal_checkpoint(TRUNCATE)');
      db.close();
      console.log('[SQLite] Checkpoint completed and database closed.');
    }
  } catch (err) {
    console.error('[SQLite] Error flushing WAL:', err);
  }
};

process.on('SIGINT', () => { flushAndCloseDb(); process.exit(0); });
process.on('SIGTERM', () => { flushAndCloseDb(); process.exit(0); });
process.on('beforeExit', () => { flushAndCloseDb(); });

