try {
  const existingMatieresToBackfill = db.prepare("SELECT id, nom, sigle, code, categorie FROM matieres WHERE code IS NULL OR code = '' OR sigle IS NULL OR sigle = ''").all() as any[];
  for (const item of existingMatieresToBackfill) {
    const sigle = item.sigle && item.sigle.trim() ? item.sigle.trim().toUpperCase() : extractOrGenerateSigle(item.nom || '');
    const code = item.code && item.code.trim() ? item.code.trim().toUpperCase() : `MAT-${sigle}-${item.id}`;
    db.prepare("UPDATE matieres SET code = COALESCE(NULLIF(code, ''), ?), sigle = COALESCE(NULLIF(sigle, ''), ?) WHERE id = ?")
      .run(code, sigle, item.id);
  }
} catch(e) {
  console.warn("Backfill matieres error:", e);
}

