// Seed current academic year if none
const yearExists = db.prepare("SELECT * FROM annees_scolaires").get();
if (!yearExists) {
  const libelle = getCurrentAcademicYearLibelle();
  const parts = libelle.split('-');
  const start = parts[0];
  const end = parts[1];
  const schools = db.prepare("SELECT id FROM school_info").all() as any[];
  schools.forEach(school => {
    db.prepare("INSERT INTO annees_scolaires (libelle, date_debut, date_fin, est_active, school_id) VALUES (?, ?, ?, ?, ?)")
      .run(libelle, `${start}-09-01`, `${end}-07-31`, 1, school.id);
  });
  console.log("Academic years seeded for all schools.");
}

// Auto-fix any academic years with identical start and end years (e.g. "2025-2025" -> "2025-2026")
try {
  const malformedYears = db.prepare("SELECT id, libelle, school_id FROM annees_scolaires").all() as any[];
  for (const y of malformedYears) {
    const fixed = formatAcademicYearLibelle(y.libelle);
    if (fixed && fixed !== y.libelle) {
      const existing = db.prepare("SELECT id FROM annees_scolaires WHERE libelle = ? AND school_id = ? AND id != ?").get(fixed, y.school_id, y.id) as any;
      if (existing) {
        const clsCount = db.prepare("SELECT COUNT(*) as c FROM classes WHERE annee_id = ?").get(existing.id) as any;
        if (!clsCount || clsCount.c === 0) {
          db.prepare("DELETE FROM annees_scolaires WHERE id = ?").run(existing.id);
        }
      }
      db.prepare("UPDATE annees_scolaires SET libelle = ? WHERE id = ?").run(fixed, y.id);
      console.log(`Auto-corrected academic year ${y.libelle} to ${fixed} (id: ${y.id})`);
    }
  }
} catch(err) {
  console.error("Error auto-fixing academic years:", err);
}

