  // Notifications Helpers
  function sendNotification(schoolId: number, title: string, message: string, type: string = 'info', roles: string[] = ['admin', 'direction', 'secretariat']) {
    try {
      const admins = db.prepare("SELECT id FROM utilisateurs WHERE school_id = ? AND role IN (" + roles.map(() => '?').join(',') + ")").all(schoolId, ...roles);
      const stmt = db.prepare("INSERT INTO notifications (utilisateur_id, titre, message, type, school_id) VALUES (?, ?, ?, ?, ?)");
      for (const admin of admins as any[]) {
        stmt.run(admin.id, title, message, type, schoolId);
      }
    } catch (e) {
      console.error("Error sending notification:", e);
    }
  }

