  // Admin: Integrer Candidat (Candidature -> Enseignant ou Personnel)
  app.post("/api/recrutement/candidatures/:id/integrer", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const schoolId = req.schoolId;
      const candidature = db.prepare(`
        SELECT c.*, camp.type as campagne_type 
        FROM recrutement_candidatures c
        JOIN recrutement_campagnes camp ON c.campagne_id = camp.id
        WHERE c.id = ? AND c.school_id = ?
      `).get(id, schoolId) as any;

      if (!candidature) return res.status(404).json({ error: "Candidature non trouvée." });
      if (candidature.est_integre) return res.status(400).json({ error: "Ce candidat est déjà intégré." });

      if (candidature.campagne_type === 'enseignant') {
        const result = db.prepare(`
          INSERT INTO enseignants (nom, prenom, telephone, email, school_id, niveau_etudes, diplome_pro, annees_experience, sexe, date_naissance)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).run(candidature.nom, candidature.prenom, candidature.telephone, candidature.email, schoolId, candidature.diplome_obtenu, candidature.diplome_obtenu, candidature.experience_annees, '?', '?');
        
        // If there are specific subjects, we could add them to enseignant_matieres here if we had their IDs
        // For now, we just create the teacher profile
      } else {
        db.prepare(`
          INSERT INTO personnel_administratif (nom, prenom, poste, telephone, email, school_id)
          VALUES (?, ?, ?, ?, ?, ?)
        `).run(candidature.nom, candidature.prenom, candidature.poste_vise, candidature.telephone, candidature.email, schoolId);
      }

      db.prepare("UPDATE recrutement_candidatures SET est_integre = 1, status = 'embauche' WHERE id = ?").run(id);
      
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

