  // =========================================================================
  // --- Collecte des Informations Enseignants (Secondaire) ---
  // =========================================================================

  // Staff: Get all collection campaigns/forms
  app.get("/api/collecte-enseignants/formulaires", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId;
      const { annee_id } = req.query;

      let query = "SELECT * FROM collecte_enseignants_formulaires WHERE school_id = ?";
      const params: any[] = [schoolId];

      if (annee_id && annee_id !== 'all') {
        query += " AND annee_id = ?";
        params.push(annee_id);
      }

      query += " ORDER BY created_at DESC";
      const forms = db.prepare(query).all(...params) as any[];

      // Compute statistics for each form
      const formsWithStats = forms.map((f: any) => {
        const stats = db.prepare(`
          SELECT 
            COUNT(*) as total,
            SUM(CASE WHEN statut = 'en_attente' THEN 1 ELSE 0 END) as en_attente,
            SUM(CASE WHEN statut = 'valide' THEN 1 ELSE 0 END) as valide,
            SUM(CASE WHEN statut = 'rejete' THEN 1 ELSE 0 END) as rejete,
            SUM(CASE WHEN statut = 'bloque' THEN 1 ELSE 0 END) as bloque
          FROM collecte_enseignants_reponses
          WHERE formulaire_id = ?
        `).get(f.id) as any;

        let classesList: any[] = [];
        try {
          const classIds = typeof f.classes_proposees === 'string' ? JSON.parse(f.classes_proposees) : (f.classes_proposees || []);
          if (Array.isArray(classIds) && classIds.length > 0) {
            const placeholders = classIds.map(() => '?').join(',');
            classesList = db.prepare(`SELECT id, nom, niveau FROM classes WHERE id IN (${placeholders})`).all(...classIds);
          }
        } catch (e) {}

        return {
          ...f,
          classes_details: classesList,
          stats: {
            total: stats?.total || 0,
            en_attente: stats?.en_attente || 0,
            valide: stats?.valide || 0,
            rejete: stats?.rejete || 0,
            bloque: stats?.bloque || 0
          }
        };
      });

      res.json(formsWithStats);
    } catch (error: any) {
      console.error("Error fetching collecte forms:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Staff: Create a collection form
  app.post("/api/collecte-enseignants/formulaires", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId;
      const { titre, description, classes_proposees, cycle = 'secondaire', date_expiration, annee_id } = req.body;

      if (!titre || !titre.trim()) {
        return res.status(400).json({ error: "Le titre du formulaire est requis." });
      }

      const token = 'ens-' + Math.random().toString(36).substring(2, 10) + Date.now().toString(36);
      const classesJson = typeof classes_proposees === 'string' 
        ? classes_proposees 
        : JSON.stringify(Array.isArray(classes_proposees) ? classes_proposees : []);

      const result = db.prepare(`
        INSERT INTO collecte_enseignants_formulaires (
          school_id, annee_id, titre, description, cycle, classes_proposees, statut, token, date_expiration, created_by
        ) VALUES (?, ?, ?, ?, ?, ?, 'actif', ?, ?, ?)
      `).run(
        schoolId, 
        annee_id || null, 
        titre.trim(), 
        description || '', 
        cycle || 'secondaire', 
        classesJson, 
        token, 
        date_expiration || null, 
        req.userId || null
      );

      const created = db.prepare("SELECT * FROM collecte_enseignants_formulaires WHERE id = ?").get(result.lastInsertRowid);
      res.status(201).json(created);
    } catch (error: any) {
      console.error("Error creating collecte form:", error);
      res.status(500).json({ error: error.message });
    }
  });

