  // Créer un événement / réservation de salle
  app.post("/api/evenements-salles", authenticateToken, (req: any, res) => {
    try {
      const { titre, type_evenement, salle_id, date_evenement, heure_debut, heure_fin, responsable, description, statut, force } = req.body;
      if (!titre || !titre.trim()) {
        return res.status(400).json({ error: "Le titre de l'événement est obligatoire." });
      }
      if (!salle_id) {
        return res.status(400).json({ error: "Veuillez sélectionner une salle." });
      }
      if (!date_evenement || !heure_debut || !heure_fin) {
        return res.status(400).json({ error: "La date et les créneaux horaires sont requis." });
      }

      // Check conflict if not forced
      if (!force) {
        const conflict = db.prepare(`
          SELECT es.*, s.nom as salle_nom
          FROM evenements_salles es
          JOIN salles s ON es.salle_id = s.id
          WHERE es.salle_id = ? AND es.date_evenement = ? AND es.school_id = ?
            AND es.statut != 'annule'
            AND ((es.heure_debut < ? AND es.heure_fin > ?) OR (es.heure_debut < ? AND es.heure_fin > ?) OR (? <= es.heure_debut AND ? >= es.heure_fin))
        `).get(salle_id, date_evenement, req.schoolId, heure_fin, heure_debut, heure_debut, heure_debut, heure_debut, heure_fin) as any;

        if (conflict) {
          return res.status(409).json({
            error: `Conflit d'horaire : La salle ${conflict.salle_nom || ''} est déjà réservée pour "${conflict.titre}" de ${conflict.heure_debut} à ${conflict.heure_fin}.`,
            conflict
          });
        }
      }

      const yearId = req.anneeId;

      const result = db.prepare(`
        INSERT INTO evenements_salles (
          titre, type_evenement, salle_id, date_evenement, heure_debut, heure_fin,
          responsable, description, statut, annee_id, school_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        titre.trim(),
        type_evenement || 'reunion',
        salle_id,
        date_evenement,
        heure_debut,
        heure_fin,
        responsable || '',
        description || '',
        statut || 'confirme',
        yearId || null,
        req.schoolId
      );

      logActivity(req.userId, 'CREATE', 'EVENEMENT_SALLE', result.lastInsertRowid as number, { titre, salle_id, date_evenement }, req.schoolId);
      res.json({ success: true, id: result.lastInsertRowid });
    } catch (error: any) {
      console.error("Error creating evenement-salle:", error);
      res.status(500).json({ error: error.message });
    }
  });

