      const sNomLibre = empType === 'salle' && salle_nom_libre !== undefined ? (salle_nom_libre ? salle_nom_libre.trim() : null) : (existing.salle_nom_libre || null);
      const magNom = empType === 'magasin' ? (magasin_nom?.trim() || 'Magasin Central') : null;
      const valUnitaire = parseFloat(valeur_unitaire) || 0;
