  // 1. Livres Physiques : Liste avec filtres et recherche
  app.get("/api/bibliotheque-physique/livres", authenticateToken, (req: any, res) => {
    try {
      ensureDefaultPhysicalLibrary(req.schoolId);

      const { search, categorie, etat, cycle, armoire, disponible_only } = req.query;
      let query = "SELECT * FROM livres_physiques WHERE school_id = ?";
      const params: any[] = [req.schoolId];

      if (search && search.trim()) {
        const term = `%${search.trim()}%`;
        query += " AND (titre LIKE ? OR auteur LIKE ? OR code_livre LIKE ? OR isbn LIKE ? OR editeur LIKE ? OR armoire_numero LIKE ? OR casier_numero LIKE ?)";
        params.push(term, term, term, term, term, term, term);
      }

      if (categorie && categorie !== 'toutes') {
        query += " AND categorie = ?";
        params.push(categorie);
      }

      if (etat && etat !== 'tous') {
        query += " AND etat_general = ?";
        params.push(etat);
      }

      if (cycle && cycle !== 'tous') {
        query += " AND (cycle = ? OR cycle = 'tous')";
        params.push(cycle);
      }

      if (armoire && armoire !== 'toutes') {
        query += " AND armoire_numero = ?";
        params.push(armoire);
      }

      if (disponible_only === 'true' || disponible_only === '1') {
        query += " AND quantite_disponible > 0";
      }

      query += " ORDER BY titre ASC";
      const books = db.prepare(query).all(...params);
      res.json(books);
    } catch (error: any) {
      console.error("Error fetching physical books:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Livres Physiques : Détails avec historique
  app.get("/api/bibliotheque-physique/livres/:id", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const book = db.prepare("SELECT * FROM livres_physiques WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!book) return res.status(404).json({ error: "Livre introuvable." });

      const activeLoans = db.prepare(`
        SELECT e.*, a.nom_complet as adherent_nom, a.numero_adherent, a.classe_nom, a.telephone
        FROM emprunts_bibliotheque e
        JOIN adherents_bibliotheque a ON e.adherent_id = a.id
        WHERE e.livre_id = ? AND e.statut IN ('en_cours', 'en_retard') AND e.school_id = ?
        ORDER BY e.date_emprunt DESC
      `).all(id, req.schoolId);

      const recentConsultations = db.prepare(`
        SELECT * FROM consultations_sur_place
        WHERE livre_id = ? AND school_id = ?
        ORDER BY date_consultation DESC, heure_debut DESC
        LIMIT 10
      `).all(id, req.schoolId);

      res.json({ ...book, activeLoans, recentConsultations });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Livres Physiques : Ajouter un nouveau livre
  app.post("/api/bibliotheque-physique/livres", authenticateToken, (req: any, res) => {
    try {
      const {
        code_livre, isbn, titre, auteur, editeur, annee_publication,
        categorie, cycle, niveau_recommande, quantite_totale,
        armoire_numero, casier_numero, table_numero, emplacement_detail,
        etat_general, nombre_pages, langue, resume, valeur_remplacement, couverture_url
      } = req.body;

      if (!titre || !titre.trim() || !auteur || !auteur.trim()) {
        return res.status(400).json({ error: "Le titre et l'auteur sont obligatoires." });
      }

      const totalQty = Math.max(1, parseInt(quantite_totale, 10) || 1);
      const etat = etat_general || 'bon';
      let lostDef = (etat === 'defectueux' || etat === 'vole_perdu') ? totalQty : 0;
      let dispo = Math.max(0, totalQty - lostDef);

      let code = code_livre?.trim();
      if (!code) {
        const lastId = ((db.prepare("SELECT MAX(id) as maxId FROM livres_physiques WHERE school_id = ?").get(req.schoolId) as any)?.maxId || 0) + 1;
        code = `LIV-${String(lastId).padStart(4, '0')}`;
      }

      const info = db.prepare(`
        INSERT INTO livres_physiques (
          code_livre, isbn, titre, auteur, editeur, annee_publication,
          categorie, cycle, niveau_recommande, quantite_totale, quantite_disponible,
          quantite_empruntee, quantite_sur_place, quantite_perdue_defectueuse,
          armoire_numero, casier_numero, table_numero, emplacement_detail,
          etat_general, nombre_pages, langue, resume, couverture_url,
          valeur_remplacement, school_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, 0, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        code,
        isbn?.trim() || null,
        titre.trim(),
        auteur.trim(),
        editeur?.trim() || null,
        annee_publication?.trim() || null,
        categorie || 'manuels_scolaires',
        cycle || 'tous',
        niveau_recommande?.trim() || 'Tous niveaux',
        totalQty,
        dispo,
        lostDef,
        armoire_numero?.trim() || 'Armoire Principale',
        casier_numero?.trim() || 'Casier 1',
        table_numero?.trim() || null,
        emplacement_detail?.trim() || null,
        etat,
        parseInt(nombre_pages, 10) || null,
        langue?.trim() || 'Français',
        resume?.trim() || null,
        couverture_url || null,
        parseFloat(valeur_remplacement) || 0,
        req.schoolId
      );

      const newId = info.lastInsertRowid;
      logActivity(req.userId, 'CREATE', 'LIVRE_PHYSIQUE', Number(newId), { titre, code, totalQty }, req.schoolId);
      res.json({ success: true, id: newId, message: "Livre enregistré avec succès." });
    } catch (error: any) {
      console.error("Error creating physical book:", error);
      res.status(500).json({ error: error.message });
    }
  });

