  // Livres Physiques : Déplacer
  app.patch("/api/bibliotheque-physique/livres/:id/deplacer", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { armoire, casier, position, table, force } = req.body;
      
      // Check if occupied
      if (!force && armoire && casier && position) {
        const conflict = db.prepare(`
          SELECT id, titre, code_livre 
          FROM livres_physiques 
          WHERE armoire_numero = ? AND casier_numero = ? AND position_casier = ? AND id != ? AND school_id = ?
        `).get(armoire, casier, position, id, req.schoolId) as any;
        
        if (conflict) {
          return res.status(409).json({ 
            error: "Emplacement déjà occupé", 
            conflict_book: conflict 
          });
        }
      }

      db.prepare(`
        UPDATE livres_physiques SET
          armoire_numero = ?,
          casier_numero = ?,
          position_casier = ?,
          table_numero = ?,
          updated_at = CURRENT_TIMESTAMP
        WHERE id = ? AND school_id = ?
      `).run(armoire, casier, position || 'gauche', table, id, req.schoolId);
      
      res.json({ success: true, message: "Emplacement mis à jour." });
    } catch (error: any) { res.status(500).json({ error: error.message }); }
  });

