  app.post("/api/bibliotheque-physique/livres/permuter", authenticateToken, (req: any, res) => {
    try {
      const { id1, id2 } = req.body;
      const b1 = db.prepare("SELECT * FROM livres_physiques WHERE id = ? AND school_id = ?").get(id1, req.schoolId) as any;
      const b2 = db.prepare("SELECT * FROM livres_physiques WHERE id = ? AND school_id = ?").get(id2, req.schoolId) as any;
      
      if (!b1 || !b2) return res.status(404).json({ error: "Livre(s) introuvable(s)." });
      
      const tx = db.transaction(() => {
        db.prepare("UPDATE livres_physiques SET armoire_numero = ?, casier_numero = ?, position_casier = ?, table_numero = ? WHERE id = ?")
          .run(b2.armoire_numero, b2.casier_numero, b2.position_casier, b2.table_numero, id1);
        db.prepare("UPDATE livres_physiques SET armoire_numero = ?, casier_numero = ?, position_casier = ?, table_numero = ? WHERE id = ?")
          .run(b1.armoire_numero, b1.casier_numero, b1.position_casier, b1.table_numero, id2);
      });
      tx();
      
      res.json({ success: true, message: "Emplacements permutés." });
    } catch (error: any) { res.status(500).json({ error: error.message }); }
  });

  // Livres Physiques : Supprimer
  app.delete("/api/bibliotheque-physique/livres/:id", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const existing = db.prepare("SELECT * FROM livres_physiques WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!existing) return res.status(404).json({ error: "Livre introuvable." });

      if (existing.quantite_empruntee > 0) {
        return res.status(400).json({ error: "Impossible de supprimer ce livre car des exemplaires sont actuellement en cours d'emprunt." });
      }

      db.prepare("DELETE FROM livres_physiques WHERE id = ? AND school_id = ?").run(id, req.schoolId);
      logActivity(req.userId, 'DELETE', 'LIVRE_PHYSIQUE', parseInt(id, 10), { titre: existing.titre }, req.schoolId);
      res.json({ success: true, message: "Livre supprimé du catalogue." });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // 2. Adhérents / Inscription des Élèves
  // Enregistrer un paiement d'adhésion
  app.post("/api/bibliotheque-physique/paiements-adhesion", authenticateToken, (req: any, res) => {
    try {
      const { nom_complet, telephone, email, montant, type_adherent, eleve_id } = req.body;
      const lastId = ((db.prepare("SELECT MAX(id) as maxId FROM bibliotheque_paiements_adhesion").get() as any)?.maxId || 0) + 1;
      const numRecu = `LIB-REC-${new Date().getFullYear()}-${String(lastId).padStart(4, '0')}`;
      
      db.prepare(`
        INSERT INTO bibliotheque_paiements_adhesion (
          num_recu, nom_complet, telephone, email, montant, date_paiement, type_adherent, eleve_id, school_id
        ) VALUES (?, ?, ?, ?, ?, date('now'), ?, ?, ?)
      `).run(numRecu, nom_complet, telephone, email, montant, type_adherent || 'externe', eleve_id || null, req.schoolId);
      
      res.json({ success: true, num_recu: numRecu, message: "Paiement enregistré." });
    } catch (error: any) { res.status(500).json({ error: error.message }); }
  });

  // Récupérer les infos d'un paiement par numéro de reçu
  app.get("/api/bibliotheque-physique/paiements-adhesion/:num_recu", authenticateToken, (req: any, res) => {
    try {
      const paiement = db.prepare("SELECT * FROM bibliotheque_paiements_adhesion WHERE num_recu = ? AND school_id = ?").get(req.params.num_recu, req.schoolId);
      if (!paiement) return res.status(404).json({ error: "Reçu introuvable." });
      res.json(paiement);
    } catch (error: any) { res.status(500).json({ error: error.message }); }
  });

  app.get("/api/bibliotheque-physique/adherents", authenticateToken, (req: any, res) => {
    try {
      ensureDefaultPhysicalLibrary(req.schoolId);
      const { search, statut } = req.query;
      let query = `
        SELECT a.*,
          (SELECT COUNT(*) FROM emprunts_bibliotheque WHERE adherent_id = a.id AND statut IN ('en_cours', 'en_retard')) as emprunts_actifs
        FROM adherents_bibliotheque a
        WHERE a.school_id = ?
      `;
      const params: any[] = [req.schoolId];

      if (search && search.trim()) {
        const term = `%${search.trim()}%`;
        query += " AND (a.nom_complet LIKE ? OR a.numero_adherent LIKE ? OR a.classe_nom LIKE ? OR a.telephone LIKE ?)";
        params.push(term, term, term, term);
      }

      if (statut && statut !== 'tous') {
        query += " AND a.statut = ?";
        params.push(statut);
      }

      query += " ORDER BY a.nom_complet ASC";
      const adherents = db.prepare(query).all(...params);
      res.json(adherents);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.get("/api/bibliotheque-physique/adherents/:id/historique", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const adherent = db.prepare("SELECT * FROM adherents_bibliotheque WHERE id = ? AND school_id = ?").get(id, req.schoolId);
      if (!adherent) return res.status(404).json({ error: "Adhérent introuvable." });

      const loans = db.prepare(`
        SELECT e.*, l.titre as titre_livre, l.code_livre, l.auteur as livre_auteur,
               l.armoire_numero, l.casier_numero, l.position_casier, l.table_numero as livre_table
        FROM emprunts_bibliotheque e
        JOIN livres_physiques l ON e.livre_id = l.id
        WHERE e.adherent_id = ? AND e.school_id = ?
        ORDER BY e.date_emprunt DESC
      `).all(id, req.schoolId);

      const consultations = db.prepare(`
        SELECT c.*, l.titre as titre_livre, l.code_livre, l.auteur as livre_auteur,
               c.numero_table as emplacement_lecture
        FROM consultations_sur_place c
        JOIN livres_physiques l ON c.livre_id = l.id
        WHERE (c.adherent_id = ? OR (c.eleve_id = ? AND c.eleve_id IS NOT NULL)) AND c.school_id = ?
        ORDER BY c.date_consultation DESC, c.heure_debut DESC
      `).all(id, (adherent as any).eleve_id, req.schoolId);

      res.json({ loans, consultations });
    } catch (error: any) { res.status(500).json({ error: error.message }); }
  });

  // Élèves candidats pour adhésion
  app.get("/api/bibliotheque-physique/eleves-candidats", authenticateToken, (req: any, res) => {
    try {
      const candidates = db.prepare(`
        SELECT e.id, e.nom, e.prenom, e.matricule, e.photo, e.tel_parent, e.classe_id, c.nom as classe_nom, c.niveau,
               a.id as adherent_id, a.numero_adherent, a.statut as adherent_statut
        FROM eleves e
        LEFT JOIN classes c ON e.classe_id = c.id
        LEFT JOIN adherents_bibliotheque a ON e.id = a.eleve_id AND a.school_id = ?
        WHERE e.school_id = ?
        ORDER BY c.nom, e.nom, e.prenom
      `).all(req.schoolId, req.schoolId);
      res.json(candidates);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Rechercher / Vérifier un adhérent par son numéro d'adhésion officiel délivré au paiement
  app.get("/api/bibliotheque-physique/adherents/rechercher-numero/:numero", authenticateToken, (req: any, res) => {
    try {
      const rawNum = (req.params.numero || '').trim();
      if (!rawNum) return res.status(400).json({ error: "Numéro d'adhésion requis." });

      // 1. Chercher dans adherents_bibliotheque
      let adherent = db.prepare(`
        SELECT a.*,
          (SELECT COUNT(*) FROM emprunts_bibliotheque WHERE adherent_id = a.id AND statut IN ('en_cours', 'en_retard')) as emprunts_actifs
        FROM adherents_bibliotheque a
        WHERE a.school_id = ? 
          AND (
            LOWER(TRIM(a.numero_adherent)) = LOWER(?) 
            OR LOWER(TRIM(COALESCE(a.num_recu_paiement, ''))) = LOWER(?)
          )
      `).get(req.schoolId, rawNum, rawNum) as any;

      // 2. Si non trouvé directement, chercher par reçu de paiement pour 'Adhésion Bibliothèque'
      if (!adherent) {
        const payment = db.prepare(`
          SELECT p.*, e.nom as eleve_nom, e.prenom as eleve_prenom, e.matricule, e.photo as eleve_photo, c.nom as classe_nom
          FROM paiements p
          LEFT JOIN eleves e ON p.eleve_id = e.id
          LEFT JOIN classes c ON e.classe_id = c.id
          WHERE p.school_id = ? AND p.type_paiement = 'Adhésion Bibliothèque'
            AND (
              LOWER(TRIM(COALESCE(p.reference_transaction, ''))) = LOWER(?)
              OR CAST(p.id AS TEXT) = ?
              OR ('REC-' || CAST(p.id AS TEXT)) = UPPER(?)
            )
          ORDER BY p.id DESC LIMIT 1
        `).get(req.schoolId, rawNum, rawNum, rawNum) as any;

        if (payment && payment.eleve_id) {
          adherent = db.prepare(`
            SELECT a.*,
              (SELECT COUNT(*) FROM emprunts_bibliotheque WHERE adherent_id = a.id AND statut IN ('en_cours', 'en_retard')) as emprunts_actifs
            FROM adherents_bibliotheque a
            WHERE a.school_id = ? AND a.eleve_id = ?
          `).get(req.schoolId, payment.eleve_id) as any;
        }
      }

      if (!adherent) {
        return res.status(404).json({ 
          error: `Aucun adhérent trouvé avec le numéro "${rawNum}". Veuillez enregistrer l'adhésion au guichet Paiement & Scolarité.` 
        });
      }

      res.json(adherent);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Inscrire un adhérent à la bibliothèque (interne ou externe)
  app.post("/api/bibliotheque-physique/adherents", authenticateToken, (req: any, res) => {
    try {
      const {
        eleve_id, nom_complet, classe_nom, telephone, email, photo,
        date_adhesion, date_expiration, statut, max_emprunts, cycle, notes,
        type, num_recu_paiement,
        contact_urgence_nom, contact_urgence_telephone, contact_urgence_adresse,
        date_naissance, lieu_naissance, adresse, ecole_provenance, parents_tuteurs,
        montant_cotisation_du, montant_cotisation_paye
      } = req.body;

      if (!nom_complet || !nom_complet.trim()) {
        return res.status(400).json({ error: "Le nom de l'adhérent est obligatoire." });
      }

      const todayStr = new Date().toISOString().split('T')[0];
      const memberType = type || (eleve_id ? 'eleve' : 'externe');

      // 1. Règle d'adhésion unique annuelle avec renouvellement après expiration
      if (eleve_id) {
        const existing = db.prepare("SELECT * FROM adherents_bibliotheque WHERE eleve_id = ? AND school_id = ?").get(eleve_id, req.schoolId) as any;
        if (existing) {
          const isExpired = existing.statut === 'expire' || (existing.date_expiration && existing.date_expiration < todayStr);
          if (!isExpired) {
            return res.status(400).json({ 
              error: `Cet élève dispose déjà d'une adhésion active (Code : ${existing.numero_adherent}, expire le ${existing.date_expiration || 'N/A'}). Un adhérent ne peut être inscrit qu'une seule fois par an.` 
            });
          }
        }
      } else {
        // Membre externe : vérifier l'unicité par nom complet et/ou téléphone
        const cleanName = nom_complet.trim().toLowerCase();
        const existingExternal = db.prepare(`
          SELECT * FROM adherents_bibliotheque 
          WHERE school_id = ? AND type = 'externe' 
            AND (LOWER(TRIM(nom_complet)) = ? OR (telephone IS NOT NULL AND telephone != '' AND telephone = ?))
        `).get(req.schoolId, cleanName, telephone?.trim() || '') as any;

        if (existingExternal) {
          const isExpired = existingExternal.statut === 'expire' || (existingExternal.date_expiration && existingExternal.date_expiration < todayStr);
          if (!isExpired) {
            return res.status(400).json({ 
              error: `Un adhérent externe avec ce nom ou numéro de téléphone dispose déjà d'une adhésion en cours (Code : ${existingExternal.numero_adherent}, expire le ${existingExternal.date_expiration || 'N/A'}). L'adhésion ne peut être renouvelée qu'après son expiration.` 
            });
          }
        }
      }

      const lastId = ((db.prepare("SELECT MAX(id) as maxId FROM adherents_bibliotheque WHERE school_id = ?").get(req.schoolId) as any)?.maxId || 0) + 1;
      const numAdh = `ADH-${new Date().getFullYear()}-${String(lastId).padStart(3, '0')}`;

      const dateAdh = date_adhesion || todayStr;
      const nextYear = new Date();
      nextYear.setFullYear(nextYear.getFullYear() + 1);
      const dateExp = date_expiration || nextYear.toISOString().split('T')[0];

      const cotisDue = montant_cotisation_du !== undefined ? Number(montant_cotisation_du) : 1000;
      const cotisPaye = montant_cotisation_paye !== undefined ? Number(montant_cotisation_paye) : (num_recu_paiement ? cotisDue : 0);
      const statutPaye = cotisPaye >= cotisDue ? 'paye' : (cotisPaye > 0 ? 'partiel' : 'non_paye');

      const info = db.prepare(`
        INSERT INTO adherents_bibliotheque (
          numero_adherent, eleve_id, nom_complet, classe_nom, telephone, email, photo,
          date_adhesion, date_expiration, statut, max_emprunts, cycle, notes,
          type, num_recu_paiement,
          contact_urgence_nom, contact_urgence_telephone, contact_urgence_adresse,
          date_naissance, lieu_naissance, adresse, ecole_provenance, parents_tuteurs,
          montant_cotisation_du, montant_cotisation_paye, statut_paiement,
          school_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        numAdh,
        eleve_id || null,
        nom_complet.trim(),
        classe_nom?.trim() || null,
        telephone?.trim() || null,
        email?.trim() || null,
        photo || null,
        dateAdh,
        dateExp,
        statut || 'actif',
        Math.max(1, parseInt(max_emprunts, 10) || 2),
        cycle || 'tous',
        notes?.trim() || null,
        memberType,
        num_recu_paiement || null,
        contact_urgence_nom?.trim() || null,
        contact_urgence_telephone?.trim() || null,
        contact_urgence_adresse?.trim() || null,
        date_naissance || null,
        lieu_naissance?.trim() || null,
        adresse?.trim() || null,
        ecole_provenance?.trim() || null,
        parents_tuteurs?.trim() || null,
        cotisDue,
        cotisPaye,
        statutPaye,
        req.schoolId
      );

      const newId = info.lastInsertRowid;
      logActivity(req.userId, 'CREATE', 'ADHERENT_BIBLIOTHEQUE', Number(newId), { nom_complet, numero_adherent: numAdh, type: memberType }, req.schoolId);
      res.json({ success: true, id: newId, numero_adherent: numAdh, message: "Adhérent enregistré avec succès (valable 1 an)." });
    } catch (error: any) {
      console.error("Error creating adherent:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Renouveler une adhésion après expiration
  app.post("/api/bibliotheque-physique/adherents/:id/renouveler", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { montant_paye, methode, num_recu_paiement, notes } = req.body;
      const existing = db.prepare("SELECT * FROM adherents_bibliotheque WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!existing) return res.status(404).json({ error: "Adhérent introuvable." });

      const todayStr = new Date().toISOString().split('T')[0];
      const nextYear = new Date();
      nextYear.setFullYear(nextYear.getFullYear() + 1);
      const newExp = nextYear.toISOString().split('T')[0];

      const cotisDue = existing.montant_cotisation_du || 1000;
      const amountPaid = montant_paye !== undefined ? Number(montant_paye) : cotisDue;
      const statutPaye = amountPaid >= cotisDue ? 'paye' : 'non_paye';

      db.prepare(`
        UPDATE adherents_bibliotheque SET
          date_adhesion = ?,
          date_expiration = ?,
          statut = 'actif',
          montant_cotisation_paye = ?,
          statut_paiement = ?,
          num_recu_paiement = COALESCE(?, num_recu_paiement),
          notes = CASE WHEN ? IS NOT NULL THEN ? ELSE notes END
        WHERE id = ? AND school_id = ?
      `).run(
        todayStr,
        newExp,
        amountPaid,
        statutPaye,
        num_recu_paiement || null,
        notes || null,
        notes || null,
        id,
        req.schoolId
      );

      // Si l'adhérent est un élève et a payé, enregistrer dans paiements
      if (existing.eleve_id && amountPaid > 0) {
        const yearId = req.anneeId;
        db.prepare(`
          INSERT INTO paiements (eleve_id, type_paiement, montant, date_paiement, annee_id, methode, status, school_id)
          VALUES (?, 'Adhésion Bibliothèque', ?, ?, ?, ?, 'Terminé', ?)
        `).run(existing.eleve_id, amountPaid, todayStr, yearId, methode || 'Espèces', req.schoolId);
      }

      logActivity(req.userId, 'RENEW', 'ADHERENT_BIBLIOTHEQUE', Number(id), { 
        numero_adherent: existing.numero_adherent, 
        nouvelle_expiration: newExp 
      }, req.schoolId);

      res.json({ 
        success: true, 
        message: `Adhésion renouvelée avec succès pour 1 an (jusqu'au ${newExp}).`,
        date_expiration: newExp,
        numero_adherent: existing.numero_adherent
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Mettre à jour un adhérent
  app.put("/api/bibliotheque-physique/adherents/:id", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const existing = db.prepare("SELECT * FROM adherents_bibliotheque WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!existing) return res.status(404).json({ error: "Adhérent introuvable." });

      const {
        nom_complet, classe_nom, telephone, email, photo,
        date_adhesion, date_expiration, statut, max_emprunts, cycle, notes,
        contact_urgence_nom, contact_urgence_telephone, contact_urgence_adresse,
        date_naissance, lieu_naissance, adresse, ecole_provenance, parents_tuteurs,
        montant_cotisation_du, montant_cotisation_paye, statut_paiement
      } = req.body;

      db.prepare(`
        UPDATE adherents_bibliotheque SET
          nom_complet = ?,
          classe_nom = ?,
          telephone = ?,
          email = ?,
          photo = ?,
          date_adhesion = ?,
          date_expiration = ?,
          statut = ?,
          max_emprunts = ?,
          cycle = ?,
          notes = ?,
          contact_urgence_nom = ?,
          contact_urgence_telephone = ?,
          contact_urgence_adresse = ?,
          date_naissance = ?,
          lieu_naissance = ?,
          adresse = ?,
          ecole_provenance = ?,
          parents_tuteurs = ?,
          montant_cotisation_du = COALESCE(?, montant_cotisation_du),
          montant_cotisation_paye = COALESCE(?, montant_cotisation_paye),
          statut_paiement = COALESCE(?, statut_paiement)
        WHERE id = ? AND school_id = ?
      `).run(
        nom_complet?.trim() || existing.nom_complet,
        classe_nom?.trim() !== undefined ? classe_nom?.trim() : existing.classe_nom,
        telephone?.trim() !== undefined ? telephone?.trim() : existing.telephone,
        email?.trim() !== undefined ? email?.trim() : existing.email,
        photo !== undefined ? photo : existing.photo,
        date_adhesion || existing.date_adhesion,
        date_expiration || existing.date_expiration,
        statut || existing.statut,
        max_emprunts !== undefined ? Math.max(1, parseInt(max_emprunts, 10)) : existing.max_emprunts,
        cycle || existing.cycle,
        notes !== undefined ? notes : existing.notes,
        contact_urgence_nom !== undefined ? contact_urgence_nom : existing.contact_urgence_nom,
        contact_urgence_telephone !== undefined ? contact_urgence_telephone : existing.contact_urgence_telephone,
        contact_urgence_adresse !== undefined ? contact_urgence_adresse : existing.contact_urgence_adresse,
        date_naissance !== undefined ? date_naissance : existing.date_naissance,
        lieu_naissance !== undefined ? lieu_naissance : existing.lieu_naissance,
        adresse !== undefined ? adresse : existing.adresse,
        ecole_provenance !== undefined ? ecole_provenance : existing.ecole_provenance,
        parents_tuteurs !== undefined ? parents_tuteurs : existing.parents_tuteurs,
        montant_cotisation_du !== undefined ? montant_cotisation_du : null,
        montant_cotisation_paye !== undefined ? montant_cotisation_paye : null,
        statut_paiement !== undefined ? statut_paiement : null,
        id,
        req.schoolId
      );

      res.json({ success: true, message: "Fiche adhérent mise à jour." });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Supprimer un adhérent
  app.delete("/api/bibliotheque-physique/adherents/:id", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const existing = db.prepare("SELECT * FROM adherents_bibliotheque WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!existing) return res.status(404).json({ error: "Adhérent introuvable." });

      const activeLoans = (db.prepare("SELECT COUNT(*) as count FROM emprunts_bibliotheque WHERE adherent_id = ? AND statut IN ('en_cours', 'en_retard') AND school_id = ?").get(id, req.schoolId) as any)?.count || 0;
      if (activeLoans > 0) {
        return res.status(400).json({ error: "Impossible de supprimer cet adhérent car il a des emprunts non restitués." });
      }

      db.prepare("DELETE FROM adherents_bibliotheque WHERE id = ? AND school_id = ?").run(id, req.schoolId);
      res.json({ success: true, message: "Adhérent supprimé." });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // 3. Suivi des Emprunts
  app.get("/api/bibliotheque-physique/emprunts", authenticateToken, (req: any, res) => {
    try {
      ensureDefaultPhysicalLibrary(req.schoolId);

      // Auto update status to 'en_retard' for overdue loans
      const todayStr = new Date().toISOString().split('T')[0];
      db.prepare(`
        UPDATE emprunts_bibliotheque
        SET statut = 'en_retard'
        WHERE statut = 'en_cours' AND date_retour_prevue < ? AND school_id = ?
      `).run(todayStr, req.schoolId);

      const { statut, search, annee_id } = req.query;
      let query = `
        SELECT e.*,
               l.titre as livre_titre, l.auteur as livre_auteur, l.code_livre,
               l.armoire_numero, l.casier_numero, l.position_casier, l.table_numero as livre_table, l.categorie as livre_categorie,
               a.nom_complet as adherent_nom, a.classe_nom as adherent_classe,
               a.numero_adherent, a.telephone as adherent_tel, a.photo as adherent_photo, a.type as adherent_type
        FROM emprunts_bibliotheque e
        JOIN livres_physiques l ON e.livre_id = l.id
        JOIN adherents_bibliotheque a ON e.adherent_id = a.id
        WHERE e.school_id = ?
      `;
      const params: any[] = [req.schoolId];

      if (annee_id && annee_id !== 'all') {
        query += " AND e.annee_id = ?";
        params.push(annee_id);
      }

      if (statut && statut !== 'tous') {
        query += " AND e.statut = ?";
        params.push(statut);
      }

      if (search && search.trim()) {
        const term = `%${search.trim()}%`;
        query += " AND (l.titre LIKE ? OR l.code_livre LIKE ? OR a.nom_complet LIKE ? OR a.numero_adherent LIKE ?)";
        params.push(term, term, term, term);
      }

      query += " ORDER BY CASE WHEN e.statut = 'en_retard' THEN 1 WHEN e.statut = 'en_cours' THEN 2 ELSE 3 END, e.date_emprunt DESC";
      const loans = db.prepare(query).all(...params);
      res.json(loans);
    } catch (error: any) {
      console.error("Error fetching loans:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Créer un emprunt (supporte livre_id unique ou livres_ids multiple)
  app.post("/api/bibliotheque-physique/emprunts", authenticateToken, (req: any, res) => {
    try {
      let { livre_id, livres_ids, adherent_id, eleve_id, eleve_or_adherent_id, date_emprunt, duree_jours, remarques } = req.body;

      // Normaliser livres_ids
      const bookIdsToBorrow: number[] = Array.isArray(livres_ids) && livres_ids.length > 0 
        ? livres_ids.map(Number).filter(Boolean)
        : (livre_id ? [Number(livre_id)] : []);

      if (bookIdsToBorrow.length === 0) {
        return res.status(400).json({ error: "Veuillez sélectionner au moins un livre." });
      }

      if (eleve_or_adherent_id) {
        const adh = db.prepare("SELECT id FROM adherents_bibliotheque WHERE eleve_id = ? AND school_id = ?").get(eleve_or_adherent_id, req.schoolId) as any;
        if (adh) {
          adherent_id = adh.id;
        } else {
          const student = db.prepare("SELECT id FROM eleves WHERE id = ? AND school_id = ?").get(eleve_or_adherent_id, req.schoolId) as any;
          if (student) {
            eleve_id = student.id;
          } else {
            adherent_id = eleve_or_adherent_id;
          }
        }
      }

      // Horaires de la bibliothèque : Permissif pour le personnel/gestionnaire
      const now = new Date();
      const isStudentRole = req.user?.role === 'eleve';
      if (isStudentRole) {
        const day = now.getDay();
        const hour = now.getHours();
        const min = now.getMinutes();
        const timeFloat = hour + min / 60;
        if ((day === 6 && timeFloat >= 12) || day === 0) {
          return res.status(400).json({ error: "Les emprunts sont interdits durant le week-end (Samedi à partir de 12h jusqu'à Dimanche)." });
        }
        if (day >= 1 && day <= 5 && (timeFloat < 8 || timeFloat > 18)) {
          return res.status(400).json({ error: "Les emprunts étudiants sont ouverts durant les heures scolaires." });
        }
      }
      
      // Auto-register student if adherent_id is missing but eleve_id is provided
      if (!adherent_id && eleve_id) {
        let existingAdherent = db.prepare("SELECT id, numero_adherent, statut, date_expiration FROM adherents_bibliotheque WHERE eleve_id = ? AND school_id = ?").get(eleve_id, req.schoolId) as any;
        if (!existingAdherent) {
          const student = db.prepare("SELECT e.*, c.nom as classe_nom FROM eleves e LEFT JOIN classes c ON e.classe_id = c.id WHERE e.id = ? AND e.school_id = ?").get(eleve_id, req.schoolId) as any;
          if (student) {
            const lastNum = ((db.prepare("SELECT MAX(id) as maxId FROM adherents_bibliotheque WHERE school_id = ?").get(req.schoolId) as any)?.maxId || 0) + 1;
            const numero = `ADH-${new Date().getFullYear()}-${String(lastNum).padStart(3, '0')}`;
            const feeRow = db.prepare("SELECT frais_adhesion_bibliotheque FROM school_info WHERE id = ?").get(req.schoolId) as any;
            const fee = feeRow?.frais_adhesion_bibliotheque || 1000;
            const nextYear = new Date();
            nextYear.setFullYear(nextYear.getFullYear() + 1);

            const info = db.prepare(`
              INSERT INTO adherents_bibliotheque (
                numero_adherent, eleve_id, nom_complet, classe_nom, telephone, photo,
                date_adhesion, date_expiration, statut, type, montant_cotisation_du, montant_cotisation_paye, statut_paiement, school_id
              ) VALUES (?, ?, ?, ?, ?, ?, date('now'), ?, 'actif', 'eleve', ?, 0, 'non_paye', ?)
            `).run(
              numero,
              eleve_id,
              `${student.nom} ${student.prenom}`,
              student.classe_nom,
              student.tel_parent,
              student.photo || null,
              nextYear.toISOString().split('T')[0],
              fee,
              req.schoolId
            );
            adherent_id = info.lastInsertRowid;
          } else {
            return res.status(400).json({ error: "Élève introuvable pour l'auto-inscription." });
          }
        } else {
          adherent_id = existingAdherent.id;
        }
      }

      if (!adherent_id) return res.status(400).json({ error: "L'adhérent est obligatoire." });

      const adherent = db.prepare("SELECT * FROM adherents_bibliotheque WHERE id = ? AND school_id = ?").get(adherent_id, req.schoolId) as any;
      if (!adherent) return res.status(404).json({ error: "Adhérent introuvable." });
      
      if (adherent.statut === 'suspect') {
        return res.status(400).json({ error: "Ce compte est marqué comme 'Suspect'. Seul l'usage sur place est autorisé." });
      }
      if (adherent.date_fin_exclusion && new Date(adherent.date_fin_exclusion) > now) {
        return res.status(400).json({ error: `Ce compte est exclu des emprunts jusqu'au ${adherent.date_fin_exclusion} (autorisé seulement sur place).` });
      }
      if (adherent.statut !== 'actif') {
        return res.status(400).json({ error: `Le compte de ${adherent.nom_complet} n'est pas actif.` });
      }

      // Max Emprunts Rule (2 livres max simultanés)
      const activeCount = (db.prepare("SELECT COUNT(*) as count FROM emprunts_bibliotheque WHERE adherent_id = ? AND statut IN ('en_cours', 'en_retard') AND school_id = ?").get(adherent_id, req.schoolId) as any)?.count || 0;
      if (activeCount + bookIdsToBorrow.length > 2) {
        return res.status(400).json({ error: `${adherent.nom_complet} a déjà ${activeCount} emprunt(s) en cours. La limite maximale autorisée est de 2 livres empruntés simultanément.` });
      }

      // Vérifier chaque livre
      const booksToLoan: any[] = [];
      for (const bId of bookIdsToBorrow) {
        const book = db.prepare("SELECT * FROM livres_physiques WHERE id = ? AND school_id = ?").get(bId, req.schoolId) as any;
        if (!book) return res.status(404).json({ error: `Livre ID ${bId} introuvable.` });
        if (book.quantite_disponible <= 0) {
          return res.status(400).json({ error: `Le livre « ${book.titre} » n'est plus disponible (stock épuisé).` });
        }
        booksToLoan.push(book);
      }

      const dateEmp = date_emprunt || now.toISOString().split('T')[0];
      const hourEmp = now.toTimeString().split(' ')[0];
      
      // Durée prévue (défaut 72h / 3 jours ou paramétrée)
      const durationHours = duree_jours ? parseInt(duree_jours, 10) * 24 : 72;
      const d = new Date(now);
      d.setHours(d.getHours() + durationHours);
      const dateRetPrev = d.toISOString().split('T')[0];
      const hourRetPrev = d.toTimeString().split(' ')[0];

      const anneeId = req.anneeId || getActiveYearId(req.schoolId);
      const tx = db.transaction(() => {
        for (const book of booksToLoan) {
          db.prepare(`
            INSERT INTO emprunts_bibliotheque (
              livre_id, adherent_id, date_emprunt, heure_emprunt, date_retour_prevue, date_retour_prevue_heure,
              statut, etat_depart, remarques, school_id, created_by, annee_id
            ) VALUES (?, ?, ?, ?, ?, ?, 'en_cours', ?, ?, ?, ?, ?)
          `).run(book.id, adherent_id, dateEmp, hourEmp, dateRetPrev, hourRetPrev, book.etat_general || 'bon', remarques?.trim() || null, req.schoolId, req.userId, anneeId);
          
          db.prepare("UPDATE livres_physiques SET quantite_disponible = quantite_disponible - 1, quantite_empruntee = quantite_empruntee + 1 WHERE id = ?").run(book.id);
          db.prepare("UPDATE adherents_bibliotheque SET emprunts_en_cours = emprunts_en_cours + 1, total_emprunts_historique = total_emprunts_historique + 1 WHERE id = ?").run(adherent_id);
        }
      });
      tx();

      res.json({ success: true, message: `${booksToLoan.length} emprunt(s) enregistré(s) avec succès pour ${adherent.nom_complet}.` });
    } catch (error: any) { res.status(500).json({ error: error.message }); }
  });

  // Retour d'un emprunt
  app.patch("/api/bibliotheque-physique/emprunts/:id/retour", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { etat_retour, remarques } = req.body;

      const loan = db.prepare("SELECT * FROM emprunts_bibliotheque WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!loan) return res.status(404).json({ error: "Emprunt introuvable." });
      if (loan.statut === 'rendu') return res.status(400).json({ error: "Déjà rendu." });

      const now = new Date();
      const returnDate = now.toISOString().split('T')[0];
      const returnHour = now.toTimeString().split(' ')[0];
      
      // Calculate Late
      const deadline = new Date(`${loan.date_retour_prevue}T${loan.date_retour_prevue_heure || '23:59:59'}`);
      const delayMs = now.getTime() - deadline.getTime();
      const delayMinutes = Math.max(0, Math.floor(delayMs / (1000 * 60)));
      
      const tx = db.transaction(() => {
        db.prepare(`
          UPDATE emprunts_bibliotheque SET
            statut = 'rendu',
            date_retour_effective = ?,
            heure_retour_effective = ?,
            retard_minutes = ?,
            etat_retour = ?,
            remarques = COALESCE(?, remarques)
          WHERE id = ?
        `).run(returnDate, returnHour, delayMinutes, etat_retour || 'bon', remarques || null, id);

        db.prepare("UPDATE livres_physiques SET quantite_disponible = quantite_disponible + 1, quantite_empruntee = quantite_empruntee - 1 WHERE id = ?").run(loan.livre_id);
        db.prepare("UPDATE adherents_bibliotheque SET emprunts_en_cours = MAX(0, emprunts_en_cours - 1) WHERE id = ?").run(loan.adherent_id);

        // Sanctions Logic
        if (delayMinutes >= 120) { // 2 hours or more
          db.prepare("UPDATE adherents_bibliotheque SET nombre_avertissements = nombre_avertissements + 1 WHERE id = ?").run(loan.adherent_id);
          const adh = db.prepare("SELECT * FROM adherents_bibliotheque WHERE id = ?").get(loan.adherent_id) as any;
          
          if (adh.nombre_avertissements >= 3) {
            // 2 weeks exclusion
            const banEnd = new Date();
            banEnd.setDate(banEnd.getDate() + 14);
            const banEndStr = banEnd.toISOString().split('T')[0];
            
            // Track sanctions
            let sanctions = [];
            try { sanctions = JSON.parse(adh.historique_sanctions || '[]'); } catch(e) {}
            sanctions.push({ type: 'exclusion', date: new Date().toISOString(), fin: banEndStr });
            
            let newStatut = adh.statut;
            // Check for Suspect (3 exclusions in 2 months)
            const recentBans = sanctions.filter((s: any) => s.type === 'exclusion' && (now.getTime() - new Date(s.date).getTime()) < (60 * 24 * 60 * 60 * 1000));
            if (recentBans.length >= 3) {
              newStatut = 'suspect';
            }

            db.prepare(`
              UPDATE adherents_bibliotheque SET 
                nombre_avertissements = 0,
                date_fin_exclusion = ?,
                statut = ?,
                historique_sanctions = ?
              WHERE id = ?
            `).run(banEndStr, newStatut, JSON.stringify(sanctions), loan.adherent_id);
          }
        }
      });
      tx();

      res.json({ success: true, message: "Restitution enregistrée." });
    } catch (error: any) { res.status(500).json({ error: error.message }); }
  });

  // Prolonger ou reconduire un emprunt
  app.patch("/api/bibliotheque-physique/emprunts/:id/prolonger", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { heures = 72, jours } = req.body; 

      const loan = db.prepare("SELECT * FROM emprunts_bibliotheque WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!loan) return res.status(404).json({ error: "Emprunt introuvable." });
      if (loan.statut === 'rendu') return res.status(400).json({ error: "Déjà rendu." });

      const currentDue = new Date(`${loan.date_retour_prevue}T${loan.date_retour_prevue_heure || '23:59:59'}`);
      const hoursToAdd = jours ? parseInt(jours, 10) * 24 : parseInt(heures, 10);
      currentDue.setHours(currentDue.getHours() + hoursToAdd);
      
      db.prepare(`
        UPDATE emprunts_bibliotheque SET
          date_retour_prevue = ?,
          date_retour_prevue_heure = ?,
          statut = 'en_cours',
          nb_prolongations = COALESCE(nb_prolongations, 0) + 1
        WHERE id = ?
      `).run(currentDue.toISOString().split('T')[0], currentDue.toTimeString().split(' ')[0], id);

      res.json({ success: true, message: "Emprunt prolongé avec succès." });
    } catch (error: any) { res.status(500).json({ error: error.message }); }
  });

  // Reconduire un emprunt (Action explicite demandée)
  app.patch("/api/bibliotheque-physique/emprunts/:id/reconduire", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { jours = 3, heures, nouvelle_date_retour, remarques } = req.body || {};

      const loan = db.prepare("SELECT * FROM emprunts_bibliotheque WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!loan) return res.status(404).json({ error: "Emprunt introuvable." });
      if (loan.statut === 'rendu') return res.status(400).json({ error: "Cet emprunt est déjà marqué comme rendu." });

      let newDateStr: string;
      let newHourStr: string;

      if (nouvelle_date_retour) {
        newDateStr = nouvelle_date_retour;
        newHourStr = '17:00:00';
      } else {
        const currentDue = new Date(`${loan.date_retour_prevue}T${loan.date_retour_prevue_heure || '23:59:59'}`);
        const hoursToAdd = heures ? parseInt(heures, 10) : (parseInt(jours, 10) || 3) * 24;
        currentDue.setHours(currentDue.getHours() + hoursToAdd);
        newDateStr = currentDue.toISOString().split('T')[0];
        newHourStr = currentDue.toTimeString().split(' ')[0];
      }

      const todayStr = new Date().toISOString().split('T')[0];
      const note = remarques?.trim() 
        ? `${loan.remarques ? loan.remarques + ' | ' : ''}Reconduit le ${todayStr}: ${remarques.trim()}`
        : (loan.remarques || `Reconduit le ${todayStr}`);

      db.prepare(`
        UPDATE emprunts_bibliotheque SET
          date_retour_prevue = ?,
          date_retour_prevue_heure = ?,
          statut = 'en_cours',
          nb_prolongations = COALESCE(nb_prolongations, 0) + 1,
          remarques = ?
        WHERE id = ? AND school_id = ?
      `).run(newDateStr, newHourStr, note, id, req.schoolId);

      res.json({ success: true, message: `Emprunt reconduit avec succès jusqu'au ${newDateStr}.` });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Déclarer un livre emprunté comme perdu / non restitué
  app.patch("/api/bibliotheque-physique/emprunts/:id/perdu", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { penalite_montant, remarques } = req.body;

      const loan = db.prepare("SELECT * FROM emprunts_bibliotheque WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!loan) return res.status(404).json({ error: "Emprunt introuvable." });

      const updateLoan = db.prepare(`
        UPDATE emprunts_bibliotheque SET
          statut = 'perdu',
          etat_retour = 'vole_perdu',
          remarques = COALESCE(?, remarques),
          penalite_montant = ?
        WHERE id = ? AND school_id = ?
      `);

      const updateBook = db.prepare(`
        UPDATE livres_physiques SET
          quantite_empruntee = MAX(0, quantite_empruntee - 1),
          quantite_perdue_defectueuse = quantite_perdue_defectueuse + 1,
          etat_general = 'vole_perdu',
          updated_at = CURRENT_TIMESTAMP
        WHERE id = ? AND school_id = ?
      `);

      const updateAdh = db.prepare(`
        UPDATE adherents_bibliotheque SET
          emprunts_en_cours = MAX(0, emprunts_en_cours - 1)
        WHERE id = ? AND school_id = ?
      `);

      const tx = db.transaction(() => {
        updateLoan.run(remarques || "Livre déclaré égaré ou non retourné par l'adhérent", parseFloat(penalite_montant) || 0, id, req.schoolId);
        updateBook.run(loan.livre_id, req.schoolId);
        updateAdh.run(loan.adherent_id, req.schoolId);
      });

      tx();

      res.json({ success: true, message: "Livre déclaré comme perdu/volé et mis à jour dans l'inventaire." });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // 4. Usage sur Place (Consultations en salle de lecture)
  app.get("/api/bibliotheque-physique/consultations", authenticateToken, (req: any, res) => {
    try {
      ensureDefaultPhysicalLibrary(req.schoolId);
      const { date, statut, search } = req.query;

      let query = `
        SELECT c.*,
               l.titre as livre_titre, l.auteur as livre_auteur, l.code_livre,
               l.armoire_numero, l.casier_numero, l.position_casier, l.table_numero as livre_table, l.categorie as livre_categorie,
               a.numero_adherent, a.photo as adherent_photo, a.type as adherent_type
        FROM consultations_sur_place c
        JOIN livres_physiques l ON c.livre_id = l.id
        LEFT JOIN adherents_bibliotheque a ON c.adherent_id = a.id
        WHERE c.school_id = ?
      `;
      const params: any[] = [req.schoolId];

      if (date) {
        query += " AND c.date_consultation = ?";
        params.push(date);
      }

      if (statut && statut !== 'tous') {
        query += " AND c.statut = ?";
        params.push(statut);
      }

      if (search && search.trim()) {
        const term = `%${search.trim()}%`;
        query += " AND (l.titre LIKE ? OR l.code_livre LIKE ? OR c.nom_lecteur LIKE ? OR c.numero_table LIKE ? OR a.numero_adherent LIKE ?)";
        params.push(term, term, term, term, term);
      }

      query += " ORDER BY CASE WHEN c.statut = 'en_cours' THEN 1 ELSE 2 END, c.date_consultation DESC, c.heure_debut DESC";
      const list = db.prepare(query).all(...params);
      res.json(list);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Enregistrer le début d'une consultation sur place (supporte multi-livres)
  app.post("/api/bibliotheque-physique/consultations", authenticateToken, (req: any, res) => {
    try {
      let { livre_id, livres_ids, adherent_id, eleve_id, eleve_or_adherent_id, nom_lecteur, classe_lecteur, numero_table, remarques } = req.body;

      const bookIdsToConsult: number[] = Array.isArray(livres_ids) && livres_ids.length > 0
        ? livres_ids.map(Number).filter(Boolean)
        : (livre_id ? [Number(livre_id)] : []);

      if (bookIdsToConsult.length === 0) {
        return res.status(400).json({ error: "Veuillez sélectionner au moins un livre à consulter." });
      }

      if (!numero_table || !numero_table.trim()) {
        return res.status(400).json({ error: "L'emplacement / N° de table de lecture est obligatoire." });
      }

      if (eleve_or_adherent_id) {
        const adh = db.prepare("SELECT id, nom_complet, classe_nom FROM adherents_bibliotheque WHERE eleve_id = ? AND school_id = ?").get(eleve_or_adherent_id, req.schoolId) as any;
        if (adh) {
          adherent_id = adh.id;
          nom_lecteur = adh.nom_complet;
          classe_lecteur = adh.classe_nom;
        } else {
          const student = db.prepare("SELECT id FROM eleves WHERE id = ? AND school_id = ?").get(eleve_or_adherent_id, req.schoolId) as any;
          if (student) {
            eleve_id = student.id;
          } else {
            adherent_id = eleve_or_adherent_id;
          }
        }
      }

      // Auto-register student if adherent_id is missing but eleve_id is provided
      if (!adherent_id && eleve_id) {
        let existingAdherent = db.prepare("SELECT id, numero_adherent, nom_complet, classe_nom FROM adherents_bibliotheque WHERE eleve_id = ? AND school_id = ?").get(eleve_id, req.schoolId) as any;
        if (!existingAdherent) {
          const student = db.prepare("SELECT e.*, c.nom as classe_nom FROM eleves e LEFT JOIN classes c ON e.classe_id = c.id WHERE e.id = ? AND e.school_id = ?").get(eleve_id, req.schoolId) as any;
          if (student) {
            const lastNum = ((db.prepare("SELECT MAX(id) as maxId FROM adherents_bibliotheque WHERE school_id = ?").get(req.schoolId) as any)?.maxId || 0) + 1;
            const numero = `ADH-${new Date().getFullYear()}-${String(lastNum).padStart(3, '0')}`;
            const feeRow = db.prepare("SELECT frais_adhesion_bibliotheque FROM school_info WHERE id = ?").get(req.schoolId) as any;
            const fee = feeRow?.frais_adhesion_bibliotheque || 1000;
            const nextYear = new Date();
            nextYear.setFullYear(nextYear.getFullYear() + 1);

            const info = db.prepare(`
              INSERT INTO adherents_bibliotheque (
                numero_adherent, eleve_id, nom_complet, classe_nom, telephone, photo,
                date_adhesion, date_expiration, statut, type, montant_cotisation_du, montant_cotisation_paye, statut_paiement, school_id
              ) VALUES (?, ?, ?, ?, ?, ?, date('now'), ?, 'actif', 'eleve', ?, 0, 'non_paye', ?)
            `).run(
              numero,
              eleve_id,
              `${student.nom} ${student.prenom}`,
              student.classe_nom,
              student.tel_parent,
              student.photo || null,
              nextYear.toISOString().split('T')[0],
              fee,
              req.schoolId
            );
            adherent_id = info.lastInsertRowid;
            nom_lecteur = `${student.nom} ${student.prenom}`;
            classe_lecteur = student.classe_nom;
          }
        } else {
          adherent_id = existingAdherent.id;
          nom_lecteur = existingAdherent.nom_complet;
          classe_lecteur = existingAdherent.classe_nom;
        }
      }

      if (!nom_lecteur && adherent_id) {
        const adh = db.prepare("SELECT nom_complet, classe_nom FROM adherents_bibliotheque WHERE id = ?").get(adherent_id) as any;
        if (adh) {
          nom_lecteur = adh.nom_complet;
          classe_lecteur = adh.classe_nom;
        }
      }

      if (!nom_lecteur) {
        return res.status(400).json({ error: "Le nom du lecteur est obligatoire." });
      }

      // Vérifier les livres
      const booksToConsult: any[] = [];
      for (const bId of bookIdsToConsult) {
        const book = db.prepare("SELECT * FROM livres_physiques WHERE id = ? AND school_id = ?").get(bId, req.schoolId) as any;
        if (!book) return res.status(404).json({ error: `Livre ID ${bId} introuvable.` });
        if (book.quantite_disponible <= 0) {
          return res.status(400).json({ error: `Le livre « ${book.titre} » n'est pas disponible pour consultation.` });
        }
        booksToConsult.push(book);
      }

      const now = new Date();
      const dateStr = now.toISOString().split('T')[0];
      const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

      const insertStmt = db.prepare(`
        INSERT INTO consultations_sur_place (
          livre_id, adherent_id, eleve_id, nom_lecteur, classe_lecteur,
          numero_table, date_consultation, heure_debut, statut, remarques, school_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'en_cours', ?, ?)
      `);

      const updateBook = db.prepare(`
        UPDATE livres_physiques SET
          quantite_disponible = quantite_disponible - 1,
          quantite_sur_place = quantite_sur_place + 1,
          updated_at = CURRENT_TIMESTAMP
        WHERE id = ? AND school_id = ?
      `);

      const tx = db.transaction(() => {
        for (const book of booksToConsult) {
          insertStmt.run(
            book.id,
            adherent_id || null,
            eleve_id || null,
            nom_lecteur.trim(),
            classe_lecteur?.trim() || null,
            numero_table.trim(),
            dateStr,
            timeStr,
            remarques?.trim() || null,
            req.schoolId
          );
          updateBook.run(book.id, req.schoolId);
        }
      });

      tx();

      res.json({ success: true, message: `${booksToConsult.length} livre(s) assigné(s) pour lecture à la ${numero_table}.` });
    } catch (error: any) {
      console.error("Error creating consultation:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Clôturer une consultation sur place (Terminé - remis en rayon)
  app.post("/api/bibliotheque-physique/consultations/:id/fin", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { etat_retour = 'bon', remarques } = req.body || {};

      const consult = db.prepare("SELECT * FROM consultations_sur_place WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!consult) return res.status(404).json({ error: "Session de lecture introuvable." });
      if (consult.statut === 'termine') {
        return res.status(400).json({ error: "Cette consultation a déjà été clôturée." });
      }

      const now = new Date();
      const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;

      const updateConsult = db.prepare(`
        UPDATE consultations_sur_place SET
          statut = 'termine',
          heure_fin = ?,
          etat_retour = ?,
          remarques = COALESCE(?, remarques)
        WHERE id = ? AND school_id = ?
      `);

      const updateBook = db.prepare(`
        UPDATE livres_physiques SET
          quantite_disponible = quantite_disponible + 1,
          quantite_sur_place = MAX(0, quantite_sur_place - 1),
          updated_at = CURRENT_TIMESTAMP
        WHERE id = ? AND school_id = ?
      `);

      const tx = db.transaction(() => {
        updateConsult.run(timeStr, etat_retour, remarques?.trim() || 'Session de lecture terminée', id, req.schoolId);
        updateBook.run(consult.livre_id, req.schoolId);
      });

      tx();

      res.json({ success: true, message: "Livre remis en rayon et lecture clôturée avec succès." });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Continuer la lecture sur place avec un autre livre (Action requise)
  app.post("/api/bibliotheque-physique/consultations/:id/continuer", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { nouveau_livre_id, nouvelle_table, remarques } = req.body;

      if (!nouveau_livre_id) {
        return res.status(400).json({ error: "Veuillez sélectionner le nouveau livre." });
      }

      const prevConsult = db.prepare("SELECT * FROM consultations_sur_place WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      if (!prevConsult) return res.status(404).json({ error: "Session de lecture introuvable." });

      const newBook = db.prepare("SELECT * FROM livres_physiques WHERE id = ? AND school_id = ?").get(nouveau_livre_id, req.schoolId) as any;
      if (!newBook) return res.status(404).json({ error: "Nouveau livre introuvable." });
      if (newBook.quantite_disponible <= 0) {
        return res.status(400).json({ error: `Le livre « ${newBook.titre} » n'est plus disponible.` });
      }

      const now = new Date();
      const timeStr = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`;
      const dateStr = now.toISOString().split('T')[0];
      const tableNum = (nouvelle_table && nouvelle_table.trim()) || prevConsult.numero_table;

      let newConsultId = 0;
      const tx = db.transaction(() => {
        // 1. Clôturer l'ancienne session si elle est en cours
        if (prevConsult.statut === 'en_cours') {
          db.prepare(`
            UPDATE consultations_sur_place SET
              statut = 'termine',
              heure_fin = ?,
              remarques = COALESCE(?, 'Livre remis en rayon - Changement pour un autre livre')
            WHERE id = ? AND school_id = ?
          `).run(timeStr, remarques?.trim() || null, id, req.schoolId);

          db.prepare(`
            UPDATE livres_physiques SET
              quantite_disponible = quantite_disponible + 1,
              quantite_sur_place = MAX(0, quantite_sur_place - 1),
              updated_at = CURRENT_TIMESTAMP
            WHERE id = ? AND school_id = ?
          `).run(prevConsult.livre_id, req.schoolId);
        }

        // 2. Créer la nouvelle session de lecture
        const info = db.prepare(`
          INSERT INTO consultations_sur_place (
            livre_id, adherent_id, eleve_id, nom_lecteur, classe_lecteur,
            numero_table, date_consultation, heure_debut, statut, remarques, school_id
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'en_cours', ?, ?)
        `).run(
          nouveau_livre_id,
          prevConsult.adherent_id || null,
          prevConsult.eleve_id || null,
          prevConsult.nom_lecteur,
          prevConsult.classe_lecteur,
          tableNum,
          dateStr,
          timeStr,
          "Suite de lecture (changement d'ouvrage)",
          req.schoolId
        );
        newConsultId = Number(info.lastInsertRowid);

        db.prepare(`
          UPDATE livres_physiques SET
            quantite_disponible = quantite_disponible - 1,
            quantite_sur_place = quantite_sur_place + 1,
            updated_at = CURRENT_TIMESTAMP
          WHERE id = ? AND school_id = ?
        `).run(nouveau_livre_id, req.schoolId);
      });

      tx();

      res.json({ success: true, id: newConsultId, message: `Livre précédent rangé. Nouveau livre « ${newBook.titre} » assigné.` });
    } catch (error: any) {
      console.error("Error continuing consultation with another book:", error);
      res.status(500).json({ error: error.message });
    }
  });

