  // 5. Statistiques & Tableau de bord Bibliothèque Physique
  app.get("/api/bibliotheque-physique/stats", authenticateToken, (req: any, res) => {
    try {
      ensureDefaultPhysicalLibrary(req.schoolId);

      // Auto check overdue
      const todayStr = new Date().toISOString().split('T')[0];
      db.prepare(`
        UPDATE emprunts_bibliotheque
        SET statut = 'en_retard'
        WHERE statut = 'en_cours' AND date_retour_prevue < ? AND school_id = ?
      `).run(todayStr, req.schoolId);

      const totals = db.prepare(`
        SELECT 
          COUNT(*) as total_titres,
          IFNULL(SUM(quantite_totale), 0) as total_exemplaires,
          IFNULL(SUM(quantite_disponible), 0) as exemplaires_disponibles,
          IFNULL(SUM(quantite_empruntee), 0) as exemplaires_empruntes,
          IFNULL(SUM(quantite_sur_place), 0) as exemplaires_sur_place,
          IFNULL(SUM(quantite_perdue_defectueuse), 0) as exemplaires_defectueux_perdus
        FROM livres_physiques
        WHERE school_id = ?
      `).get(req.schoolId) as any;

      const adherentsCount = (db.prepare("SELECT COUNT(*) as count FROM adherents_bibliotheque WHERE school_id = ? AND statut = 'actif'").get(req.schoolId) as any)?.count || 0;
      const activeLoans = (db.prepare("SELECT COUNT(*) as count FROM emprunts_bibliotheque WHERE school_id = ? AND statut = 'en_cours'").get(req.schoolId) as any)?.count || 0;
      const overdueLoans = (db.prepare("SELECT COUNT(*) as count FROM emprunts_bibliotheque WHERE school_id = ? AND statut = 'en_retard'").get(req.schoolId) as any)?.count || 0;
      const consultationsToday = (db.prepare("SELECT COUNT(*) as count FROM consultations_sur_place WHERE school_id = ? AND date_consultation = ?").get(req.schoolId, todayStr) as any)?.count || 0;
      const activeConsultations = (db.prepare("SELECT COUNT(*) as count FROM consultations_sur_place WHERE school_id = ? AND statut = 'en_cours'").get(req.schoolId) as any)?.count || 0;

      // Group by category
      const categoriesStats = db.prepare(`
        SELECT categorie, COUNT(*) as titres_count, SUM(quantite_totale) as exemplaires_count
        FROM livres_physiques
        WHERE school_id = ?
        GROUP BY categorie
      `).all(req.schoolId);

      // Group by condition
      const etatsStats = db.prepare(`
        SELECT etat_general, COUNT(*) as titres_count, SUM(quantite_totale) as exemplaires_count
        FROM livres_physiques
        WHERE school_id = ?
        GROUP BY etat_general
      `).all(req.schoolId);

      // Group by armoire
      const armoiresStats = db.prepare(`
        SELECT armoire_numero, COUNT(*) as titres_count, SUM(quantite_totale) as exemplaires_count
        FROM livres_physiques
        WHERE school_id = ? AND armoire_numero IS NOT NULL
        GROUP BY armoire_numero
      `).all(req.schoolId);

      res.json({
        total_titres: totals.total_titres,
        total_exemplaires: totals.total_exemplaires,
        exemplaires_disponibles: totals.exemplaires_disponibles,
        exemplaires_empruntes: totals.exemplaires_empruntes,
        exemplaires_sur_place: totals.exemplaires_sur_place,
        exemplaires_defectueux_perdus: totals.exemplaires_defectueux_perdus,
        adherents_actifs: adherentsCount,
        emprunts_en_cours: activeLoans,
        emprunts_en_retard: overdueLoans,
        consultations_aujourdhui: consultationsToday,
        consultations_en_cours: activeConsultations,
        categories: categoriesStats,
        etats: etatsStats,
        armoires: armoiresStats,
        // Frontend compatibility
        totalBooks: totals.total_exemplaires,
        activeLoans: activeLoans,
        overdueLoans: overdueLoans,
        todayConsultations: consultationsToday
      });
    } catch (error: any) {
      console.error("Error fetching library stats:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // =========================================================================
  // GESTION DE LA BIBLIOTHÈQUE NUMÉRIQUE (RESSOURCES NUMÉRIQUES PDF / FICHIERS)
  // =========================================================================
  app.get("/api/bibliotheque", authenticateToken, (req: any, res) => {
    try {
      const { cycle, categorie, format, search, annee_id } = req.query;
      let query = "SELECT * FROM ressources_bibliotheque WHERE (school_id = ? OR school_id IS NULL)";
      const params: any[] = [req.schoolId];

      if (annee_id && annee_id !== 'all') {
        query += " AND annee_id = ?";
        params.push(annee_id);
      }

      if (cycle && cycle !== 'tous') {
        query += " AND (cycle = ? OR cycle = 'tous')";
        params.push(cycle);
      }
      if (categorie && categorie !== 'toutes') {
        query += " AND categorie = ?";
        params.push(categorie);
      }
      if (format && format !== 'tous') {
        query += " AND format_fichier = ?";
        params.push(format);
      }
      if (search && search.trim()) {
        const term = `%${search.trim()}%`;
        query += " AND (titre LIKE ? OR auteur LIKE ? OR editeur LIKE ? OR matiere_nom LIKE ?)";
        params.push(term, term, term, term);
      }

      query += " ORDER BY id DESC";
      const items = db.prepare(query).all(...params);
      res.json(items);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

