  app.post("/api/bulletin-mentions", authenticateToken, (req: any, res) => {
    try {
      const { eleve_id, classe_id, trimestre, type, active } = req.body;
      let yearId = req.anneeId;

      if (classe_id) {
        const classe = db.prepare("SELECT annee_id FROM classes WHERE id = ?").get(classe_id) as any;
        if (classe) {
          yearId = classe.annee_id;
        }
      }
      
      if (!yearId) return res.status(400).json({error: "No active year"});
      
      const columnMap: Record<string, string> = {
        'assiduite': 'assiduite',
        'discipline': 'discipline',
        'tableau_honneur': 'tableau_honneur',
        'felicitations': 'felicitations',
        'encouragements': 'encouragements'
      };
      
      const column = columnMap[type];
      if (!column) return res.status(400).json({error: "Invalid mention type"});

      const existing = db.prepare("SELECT id FROM bulletin_mentions WHERE eleve_id = ? AND trimestre = ? AND annee_id = ? AND school_id = ?").get(eleve_id, trimestre, yearId, req.schoolId) as any;
      
      if (existing) {
        db.prepare(`UPDATE bulletin_mentions SET ${column} = ? WHERE id = ?`).run(active ? 1 : 0, existing.id);
      } else {
        db.prepare(`INSERT INTO bulletin_mentions (eleve_id, trimestre, annee_id, school_id, ${column}) VALUES (?, ?, ?, ?, ?)`).run(eleve_id, trimestre, yearId, req.schoolId, active ? 1 : 0);
      }
      res.json({success: true});
    } catch(error: any) {
      res.status(500).json({error: error.message});
    }
  });

  app.post("/api/bulletin-mentions/bulk", authenticateToken, (req: any, res) => {
    try {
      const { classe_id, trimestre, type, active } = req.body;
      
      const columnMap: Record<string, string> = {
        'assiduite': 'assiduite',
        'discipline': 'discipline',
        'tableau_honneur': 'tableau_honneur',
        'felicitations': 'felicitations',
        'encouragements': 'encouragements'
      };
      
      const column = columnMap[type];
      if (!column) return res.status(400).json({error: "Invalid mention type"});

      // Use the class's actual year to avoid mismatch with session year
      const classeInfo = db.prepare("SELECT annee_id FROM classes WHERE id = ? AND school_id = ?").get(classe_id, req.schoolId) as any;
      if (!classeInfo) return res.status(404).json({error: "Classe non trouvée"});
      const yearId = classeInfo.annee_id;

      // Get all students in this class for this year
      const students = db.prepare(`
        SELECT e.id 
        FROM eleves e 
        JOIN eleve_annees ea ON e.id = ea.eleve_id 
        WHERE ea.classe_id = ? AND ea.annee_id = ? AND (e.school_id = ? OR e.school_id IS NULL)
      `).all(classe_id, yearId, req.schoolId) as any[];

      console.log(`[Bulk Mentions] Updating ${students.length} students in class ${classe_id} for year ${yearId}, type=${type}, active=${active}`);

      const val = (active === true || active === 1 || active === 'true') ? 1 : 0;
      
      const insertOrUpdate = db.transaction((studentList) => {
        for (const student of studentList) {
          const existing = db.prepare("SELECT id FROM bulletin_mentions WHERE eleve_id = ? AND trimestre = ? AND annee_id = ? AND school_id = ?").get(student.id, trimestre, yearId, req.schoolId) as any;
          if (existing) {
            db.prepare(`UPDATE bulletin_mentions SET ${column} = ? WHERE id = ?`).run(val, existing.id);
          } else {
            db.prepare(`INSERT INTO bulletin_mentions (eleve_id, trimestre, annee_id, school_id, ${column}) VALUES (?, ?, ?, ?, ?)`).run(student.id, trimestre, yearId, req.schoolId, val);
          }
        }
      });

      insertOrUpdate(students);
      res.json({success: true, count: students.length});
    } catch(error: any) {
      console.error("[Bulk Mentions Error]", error);
      res.status(500).json({error: error.message});
    }
  });

  app.get("/api/eleves", authenticateToken, (req: any, res) => {
    try {
      res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
      const schoolId = req.schoolId || 1;
      let yearId = req.anneeId;
      if (!yearId) {
        yearId = getActiveYearId(schoolId) || 1;
      } else {
        const yearCheck = db.prepare("SELECT id FROM annees_scolaires WHERE id = ?").get(yearId);
        if (!yearCheck) {
          yearId = getActiveYearId(schoolId) || 1;
        }
      }
      const { cycle, classeId } = req.query;
      const cycleFilter = getCycleClassSqlFilter(cycle, 'c');
      let query = `
        SELECT 
          e.*, 
          COALESCE(NULLIF(ea.classe_id, 0), NULLIF(e.classe_id, 0)) as classe_id,
          c.nom as classe_nom, 
          c.niveau as classe_niveau,
          c.cycle as classe_cycle,
          c.frais_scolarite,
          c.frais_inscription,
          c.tranche1_montant,
          c.tranche1_date_limite,
          c.tranche2_montant,
          c.tranche2_date_limite,
          c.tranche3_montant,
          c.tranche3_date_limite,
          c.devise,
          COALESCE(ea.arrieres_scolarite, e.arrieres_scolarite, 0) as arrieres_scolarite,
          IFNULL((SELECT SUM(montant) FROM paiements p WHERE p.eleve_id = e.id AND p.annee_id = ? AND (p.type_paiement = 'Arriérés de scolarité' OR p.tranche = 'Arriérés') AND (p.school_id = ? OR p.school_id IS NULL) AND (p.status = 'Terminé' OR p.status = 'completed')), 0) as total_paye_arrieres,
          IFNULL((SELECT SUM(montant) FROM paiements p WHERE p.eleve_id = e.id AND p.annee_id = ? AND p.type_paiement = 'Frais de scolarité' AND (p.school_id = ? OR p.school_id IS NULL) AND (p.status = 'Terminé' OR p.status = 'completed')), 0) as total_paye_scolarite,
          IFNULL((SELECT SUM(montant) FROM paiements p WHERE p.eleve_id = e.id AND p.annee_id = ? AND p.type_paiement = 'Frais d''inscription' AND (p.school_id = ? OR p.school_id IS NULL) AND (p.status = 'Terminé' OR p.status = 'completed')), 0) as total_paye_inscription,
          IFNULL((SELECT SUM(montant) FROM paiements p WHERE p.eleve_id = e.id AND p.annee_id = ? AND p.type_paiement = 'Adhésion Bibliothèque' AND (p.school_id = ? OR p.school_id IS NULL) AND (p.status = 'Terminé' OR p.status = 'completed')), 0) as total_paye_bibliotheque,
          IFNULL((SELECT SUM(montant) FROM paiements p WHERE p.eleve_id = e.id AND p.annee_id = ? AND (p.school_id = ? OR p.school_id IS NULL) AND (p.status = 'Terminé' OR p.status = 'completed')), 0) as total_paye,
          (SELECT adh.id FROM adherents_bibliotheque adh WHERE adh.eleve_id = e.id AND (adh.school_id = ? OR adh.school_id IS NULL) LIMIT 1) as adherent_biblio_id,
          (SELECT adh.numero_adherent FROM adherents_bibliotheque adh WHERE adh.eleve_id = e.id AND (adh.school_id = ? OR adh.school_id IS NULL) LIMIT 1) as adherent_biblio_code,
          (SELECT adh.statut FROM adherents_bibliotheque adh WHERE adh.eleve_id = e.id AND (adh.school_id = ? OR adh.school_id IS NULL) LIMIT 1) as adherent_biblio_statut,
          (SELECT adh.date_expiration FROM adherents_bibliotheque adh WHERE adh.eleve_id = e.id AND (adh.school_id = ? OR adh.school_id IS NULL) LIMIT 1) as adherent_biblio_expiration,
          (SELECT adh.montant_cotisation_du FROM adherents_bibliotheque adh WHERE adh.eleve_id = e.id AND (adh.school_id = ? OR adh.school_id IS NULL) LIMIT 1) as adherent_biblio_cotisation_due
        FROM eleves e 
        LEFT JOIN eleve_annees ea ON (e.id = ea.eleve_id AND ea.annee_id = ?)
        LEFT JOIN classes c ON COALESCE(NULLIF(ea.classe_id, 0), NULLIF(e.classe_id, 0)) = c.id 
        WHERE (? IS NULL OR ? = 0 OR e.school_id = ? OR e.school_id IS NULL) ${cycleFilter}
      `;
      const params = [
        yearId, schoolId,
        yearId, schoolId, 
        yearId, schoolId, 
        yearId, schoolId, 
        yearId, schoolId,
        schoolId,
        schoolId,
        schoolId,
        schoolId,
        schoolId,
        yearId,
        schoolId, schoolId, schoolId
      ];
      
      if (classeId) {
        query += " AND COALESCE(NULLIF(ea.classe_id, 0), NULLIF(e.classe_id, 0)) = ?";
        params.push(classeId);
      }
      
      query += " ORDER BY e.nom, e.prenom";
      const rawEleves = db.prepare(query).all(...params) as any[];
      const todayStr = new Date().toISOString().split('T')[0];
      const enrichedEleves = rawEleves.map(e => {
        const s = evaluateEleveSeniority(e, yearId, schoolId);
        const biblioDue = e.adherent_biblio_id ? (e.adherent_biblio_cotisation_due ?? 1000) : 0;
        const biblioPaye = e.total_paye_bibliotheque || 0;
        const biblioDette = e.adherent_biblio_id ? Math.max(0, biblioDue - biblioPaye) : 0;
        const biblioExpire = Boolean(e.adherent_biblio_id && (e.adherent_biblio_statut === 'expire' || (e.adherent_biblio_expiration && e.adherent_biblio_expiration < todayStr)));

        const arrieresInitial = Number(e.arrieres_scolarite || 0);
        const arrieresPaye = Number(e.total_paye_arrieres || 0);
        const arrieresRestant = Math.max(0, arrieresInitial - arrieresPaye);
        const scolariteDue = Number(e.frais_scolarite || 0);
        const scolaritePayee = Number(e.total_paye_scolarite || 0);
        const resteScolarite = Math.max(0, scolariteDue - scolaritePayee);

        return {
          ...e,
          arrieres_scolarite: arrieresRestant,
          arrieres_initial: arrieresInitial,
          arrieres_paye: arrieresPaye,
          reste_scolarite: resteScolarite,
          reste_total_scolarite: resteScolarite + arrieresRestant,
          regime_inscription: s.regime,
          anciennete: s.regime,
          anciennete_libelle: s.libelle,
          anciennete_motif: s.motif,
          frais_adhesion_bibliotheque: biblioDue,
          dette_adhesion_bibliotheque: biblioDette,
          est_adherent_bibliotheque: Boolean(e.adherent_biblio_id),
          adherent_biblio_expire: biblioExpire
        };
      });
      res.json(enrichedEleves);
    } catch (error: any) {
      console.error("Eleves get error:", error);
      res.status(500).json({ error: error.message || "Erreur lors de la récupération des élèves" });
    }
  });

    // Specialized Teacher Dashboard Data
  app.get("/api/teacher/dashboard-data", authenticateToken, (req: any, res) => {
    try {
      let teacherId = req.user?.enseignant_id;
      if (!teacherId) {
        const userWithEns = db.prepare("SELECT enseignant_id FROM utilisateurs WHERE id = ?").get(req.userId) as any;
        if (userWithEns?.enseignant_id) teacherId = userWithEns.enseignant_id;
      }

      const schoolId = req.schoolId || 1;
      const yearId = getActiveYearId(schoolId);

      let teacher: any = null;
      if (teacherId) {
        teacher = db.prepare("SELECT * FROM enseignants WHERE id = ?").get(teacherId) as any;
      }

      // If still not found, try by email or user name
      if (!teacher && req.user?.email) {
        teacher = db.prepare("SELECT * FROM enseignants WHERE LOWER(email) = LOWER(?) AND (school_id = ? OR school_id IS NULL)").get(req.user.email, schoolId) as any;
        if (teacher) teacherId = teacher.id;
      }

      // Classes assigned to teacher
      let assignedClasses: any[] = [];
      if (teacherId) {
        assignedClasses = db.prepare(`
          SELECT DISTINCT c.id, c.nom, c.niveau,
            (SELECT COUNT(*) FROM eleve_annees ea WHERE ea.classe_id = c.id AND (ea.school_id = ? OR ea.school_id IS NULL)) as student_count
          FROM classes c
          LEFT JOIN classe_matieres cm ON c.id = cm.classe_id
          WHERE (c.enseignant_id = ? OR c.professeur_principal_id = ? OR cm.enseignant_id = ?)
            AND (c.school_id = ? OR c.school_id IS NULL)
            ${yearId ? `AND (c.annee_id = ${yearId} OR c.annee_id IS NULL)` : ''}
          ORDER BY c.nom
        `).all(schoolId, teacherId, teacherId, teacherId, schoolId);
      }

      // Subjects assigned to teacher
      let assignedSubjects: any[] = [];
      if (teacherId) {
        assignedSubjects = db.prepare(`
          SELECT DISTINCT m.id, m.nom, m.code, m.cycle
          FROM matieres m
          LEFT JOIN classe_matieres cm ON m.id = cm.matiere_id
          LEFT JOIN enseignant_matieres em ON m.id = em.matiere_id
          WHERE (cm.enseignant_id = ? OR em.enseignant_id = ?)
            AND (m.school_id = ? OR m.school_id IS NULL)
          ORDER BY m.nom
        `).all(teacherId, teacherId, schoolId);
      }

      // Exams submitted by teacher
      let teacherExams: any[] = [];
      let examStats = { total: 0, validees: 0, en_attente: 0, rejetees: 0 };
      if (teacherId || req.user?.nom) {
        const teacherName = teacher ? `${teacher.nom} ${teacher.prenom || ''}`.trim() : req.user?.nom;
        teacherExams = db.prepare(`
          SELECT * FROM epreuves 
          WHERE (school_id = ? OR school_id IS NULL)
            AND (enseignant_id = ? OR LOWER(enseignant_nom) LIKE LOWER(?))
          ORDER BY COALESCE(date_soumission, id) DESC
          LIMIT 10
        `).all(schoolId, teacherId || -1, `%${teacherName}%`);

        const allTeacherExams = db.prepare(`
          SELECT statut, COUNT(*) as count FROM epreuves 
          WHERE (school_id = ? OR school_id IS NULL)
            AND (enseignant_id = ? OR LOWER(enseignant_nom) LIKE LOWER(?))
          GROUP BY statut
        `).all(schoolId, teacherId || -1, `%${teacherName}%`);

        allTeacherExams.forEach((row: any) => {
          if (row.statut === 'validee') examStats.validees += row.count;
          else if (row.statut === 'rejetee') examStats.rejetees += row.count;
          else examStats.en_attente += row.count;
          examStats.total += row.count;
        });
      }

      // Timetable slots
      let scheduleList: any[] = [];
      if (teacherId) {
        scheduleList = db.prepare(`
          SELECT ed.*, c.nom as classe_nom, m.nom as matiere_nom, s.nom as salle_nom
          FROM emplois_du_temps ed
          LEFT JOIN classes c ON ed.classe_id = c.id
          LEFT JOIN matieres m ON ed.matiere_id = m.id
          LEFT JOIN salles s ON ed.salle_id = s.id
          WHERE ed.enseignant_id = ? AND (ed.school_id = ? OR ed.school_id IS NULL)
          ORDER BY 
            CASE ed.jour
              WHEN 'Lundi' THEN 1
              WHEN 'Mardi' THEN 2
              WHEN 'Mercredi' THEN 3
              WHEN 'Jeudi' THEN 4
              WHEN 'Vendredi' THEN 5
              WHEN 'Samedi' THEN 6
              ELSE 7
            END,
            ed.heure_debut ASC
        `).all(teacherId, schoolId);
      }

      // Determine today's French day name
      const daysFr = ['Dimanche', 'Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi'];
      const todayDayFr = daysFr[new Date().getDay()];
      const todaySchedule = scheduleList.filter(s => s.jour === todayDayFr);

      const schoolInfo = db.prepare("SELECT nom, logo, devise, telephone, email, adresse, notes_verrouillees, notes_verrouillees_primaire, notes_verrouillees_secondaire FROM school_info WHERE id = ?").get(schoolId) as any;
      const activeYear = yearId ? db.prepare("SELECT id, libelle FROM annees_scolaires WHERE id = ?").get(yearId) as any : null;

      res.json({
        teacher: teacher || {
          nom: req.user?.nom,
          prenom: '',
          email: req.user?.email,
          cycle: 'secondaire'
        },
        classes: assignedClasses,
        matieres: assignedSubjects,
        exams: teacherExams,
        examStats,
        schedule: scheduleList,
        todaySchedule,
        todayDay: todayDayFr,
        schoolInfo: schoolInfo || { nom: 'MégafixaEduc' },
        activeYear
      });
    } catch (error: any) {
      console.error("Teacher dashboard data error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Timezone & Country Detection Helpers
  function detectTimezoneFromCountry(countryName: string): string {
    if (!countryName) return 'Africa/Abidjan';
    const c = countryName.toLowerCase();
    if (['bénin', 'benin', 'togo', 'côte d\'ivoire', 'cote d\'ivoire', 'burkina', 'mali', 'sénégal', 'senegal', 'guinée', 'guinee', 'ghana', 'mauritanie', 'liberia', 'sierra leone', 'gambie', 'gambia'].some(k => c.includes(k))) {
      return 'Africa/Abidjan';
    }
    if (['cameroun', 'cameroon', 'gabon', 'congo', 'tchad', 'chad', 'centrafrique', 'niger', 'nigéria', 'nigeria', 'kinshasa', 'guinée équatoriale', 'angola'].some(k => c.includes(k))) {
      return 'Africa/Lagos';
    }
    if (['rwanda', 'burundi', 'zambie', 'zimbabwe', 'afrique du sud', 'south africa', 'lubumbashi', 'mozambique', 'malawi', 'botswana', 'namibie'].some(k => c.includes(k))) {
      return 'Africa/Johannesburg';
    }
    if (['kenya', 'madagascar', 'ethiopie', 'éthiopie', 'tanzanie', 'ouganda', 'djibouti', 'comores', 'somalie'].some(k => c.includes(k))) {
      return 'Africa/Nairobi';
    }
    if (['france', 'belgique', 'suisse', 'monaco'].some(k => c.includes(k))) {
      return 'Europe/Paris';
    }
    if (['canada', 'québec', 'quebec'].some(k => c.includes(k))) {
      return 'America/Toronto';
    }
    if (['haïti', 'haiti'].some(k => c.includes(k))) {
      return 'America/Port-au-Prince';
    }
    return 'Africa/Abidjan';
  }

  function getSchoolTimezone(schoolId: number): { timezone: string; pays: string } {
    const school = (db.prepare("SELECT pays, timezone FROM school_info WHERE id = ?").get(schoolId) as any)
      || (db.prepare("SELECT pays, timezone FROM school_info ORDER BY id ASC LIMIT 1").get() as any);
    const pays = school?.pays || 'Bénin';
    let timezone = school?.timezone;
    if (!timezone || !timezone.trim() || (timezone === 'Africa/Abidjan' && school?.pays && !['bénin', 'benin', 'togo', 'côte d\'ivoire', 'cote d\'ivoire', 'burkina', 'mali', 'sénégal', 'senegal'].some(k => pays.toLowerCase().includes(k)))) {
      timezone = detectTimezoneFromCountry(pays);
      try {
        db.prepare("UPDATE school_info SET timezone = ? WHERE id = ?").run(timezone, school?.id || schoolId);
      } catch (e) {}
    }
    return { timezone: timezone || 'Africa/Abidjan', pays };
  }

  function getSchoolNow(schoolId: number) {
    const { timezone, pays } = getSchoolTimezone(schoolId);
    const now = new Date();
    
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false
    }).formatToParts(now);

    const map: Record<string, string> = {};
    parts.forEach(p => { map[p.type] = p.value; });

    const y = parseInt(map.year, 10);
    const m = parseInt(map.month, 10);
    const d = parseInt(map.day, 10);
    const hour = parseInt(map.hour, 10);
    const minute = parseInt(map.minute, 10);
    const second = parseInt(map.second, 10);

    const weekdayFormatter = new Intl.DateTimeFormat('fr-FR', {
      timeZone: timezone,
      weekday: 'long'
    });
    const rawDay = weekdayFormatter.format(now);
    const dayFr = rawDay.charAt(0).toUpperCase() + rawDay.slice(1);

    const dateStr = `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const timeStr = `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;

    return {
      timezone,
      pays,
      dateStr,
      timeStr,
      dayFr,
      y, m, d, hour, minute, second,
      serverTimestamp: now.getTime()
    };
  }

  function getDayFrForDate(dateStr: string, timezone: string): string {
    const [y, m, d] = dateStr.split('-').map(Number);
    const dt = new Date(Date.UTC(y, m - 1, d, 12, 0, 0));
    const formatter = new Intl.DateTimeFormat('fr-FR', {
      timeZone: timezone,
      weekday: 'long'
    });
    const raw = formatter.format(dt);
    return raw.charAt(0).toUpperCase() + raw.slice(1);
  }

  function notifyTeacherAboutSession(sessionId: number | string, newStatut: string, detail: string, schoolId: number) {
    try {
      const session = db.prepare(`
        SELECT sc.*, ed.heure_debut, ed.heure_fin, ed.enseignant_id, m.nom as matiere_nom, c.nom as classe_nom
        FROM sessions_cours sc
        JOIN emplois_du_temps ed ON sc.emploi_du_temps_id = ed.id
        LEFT JOIN matieres m ON ed.matiere_id = m.id
        LEFT JOIN classes c ON ed.classe_id = c.id
        WHERE sc.id = ?
      `).get(sessionId) as any;

      if (session?.enseignant_id) {
        const teacherUser = db.prepare("SELECT id FROM utilisateurs WHERE enseignant_id = ? AND school_id = ?").get(session.enseignant_id, schoolId) as any;
        if (teacherUser) {
          db.prepare("INSERT INTO notifications (utilisateur_id, titre, message, type, school_id) VALUES (?, ?, ?, ?, ?)").run(
            teacherUser.id,
            `Séance ${newStatut.toUpperCase()} : ${session.matiere_nom || 'Cours'} (${session.classe_nom || ''})`,
            detail || `Votre séance (${session.heure_debut} - ${session.heure_fin}) a été mise à jour : statut "${newStatut}".`,
            'info',
            schoolId
          );
        }
      }
    } catch (err) {
      console.error("Error notifying teacher:", err);
    }
  }

