  // Course Session Management
  app.get("/api/teacher/today-sessions", authenticateToken, (req: any, res) => {
    try {
      const teacherId = req.user?.enseignant_id;
      if (!teacherId) return res.status(403).json({ error: "Enseignant non identifié" });
      const schoolId = req.schoolId || 1;
      const yearId = getActiveYearId(schoolId);
      
      const schoolNow = getSchoolNow(schoolId);
      const targetDate = req.query.date ? String(req.query.date) : schoolNow.dateStr;
      
      const targetDayFr = req.query.day !== undefined 
        ? ['Dimanche', 'Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi'][Number(req.query.day)]
        : (req.query.date ? getDayFrForDate(targetDate, schoolNow.timezone) : schoolNow.dayFr);

      const slots = db.prepare(`
        SELECT ed.*, c.nom as classe_nom, m.nom as matiere_nom, s.nom as salle_nom,
               ens.nom as enseignant_nom, ens.prenom as enseignant_prenom
        FROM emplois_du_temps ed
        LEFT JOIN classes c ON ed.classe_id = c.id
        LEFT JOIN matieres m ON ed.matiere_id = m.id
        LEFT JOIN salles s ON ed.salle_id = s.id
        LEFT JOIN enseignants ens ON ed.enseignant_id = ens.id
        WHERE ed.jour = ? AND ed.enseignant_id = ? AND (ed.school_id = ? OR ed.school_id IS NULL)
        ORDER BY ed.heure_debut ASC
      `).all(targetDayFr, teacherId, schoolId) as any[];

      const isFutureDay = targetDate > schoolNow.dateStr;
      const isPastDay = targetDate < schoolNow.dateStr;
      const isToday = targetDate === schoolNow.dateStr;

      const sessions = slots.map(slot => {
        let session = db.prepare("SELECT * FROM sessions_cours WHERE emploi_du_temps_id = ? AND date = ?").get(slot.id, targetDate) as any;
        if (!session) {
          const id = db.prepare(`
            INSERT INTO sessions_cours (emploi_du_temps_id, date, statut, annee_id, school_id)
            VALUES (?, ?, 'programmé', ?, ?)
          `).run(slot.id, targetDate, yearId, schoolId).lastInsertRowid;
          session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(id);
        }

        if (isFutureDay) {
          // ANY course for tomorrow or a future day CANNOT START. It remains strictly locked until that day and time!
          session.is_upcoming = true;
          session.is_future_day = true;
          session.lock_reason = `Verrouillé jusqu'au ${targetDayFr} (${targetDate}) à ${slot.heure_debut}`;
        } else if (isPastDay) {
          if (session.statut === 'programmé' || session.statut === 'en_cours') {
            const finalStatut = session.statut === 'en_cours' ? 'terminé' : 'absent';
            db.prepare("UPDATE sessions_cours SET statut = ?, heure_fin_reelle = ? WHERE id = ?").run(finalStatut, slot.heure_fin, session.id);
            session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(session.id);
          }
        } else if (isToday) {
          const [startH, startM] = slot.heure_debut.split(':').map(Number);
          const [endH, endM] = slot.heure_fin.split(':').map(Number);
          const slotStartMinutes = startH * 60 + startM;
          const slotEndMinutes = endH * 60 + endM;
          const currentMinutes = schoolNow.hour * 60 + schoolNow.minute;

          if (session.statut === 'programmé' || session.statut === 'en_cours') {
            if (currentMinutes >= slotEndMinutes) {
              const finalStatut = session.statut === 'en_cours' ? 'terminé' : 'absent';
              const heureFinReelle = session.statut === 'en_cours' ? slot.heure_fin : null;
              db.prepare("UPDATE sessions_cours SET statut = ?, heure_fin_reelle = ? WHERE id = ?").run(finalStatut, heureFinReelle, session.id);
              session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(session.id);
            } else if (session.statut === 'programmé') {
              if (currentMinutes < slotStartMinutes) {
                session.is_upcoming = true;
                session.lock_reason = `Verrouillé jusqu'à ${slot.heure_debut}`;
              } else if (currentMinutes > slotStartMinutes + 30) {
                const retard = currentMinutes - slotStartMinutes;
                db.prepare("UPDATE sessions_cours SET statut = 'verrouillé', retard_minutes = ? WHERE id = ?").run(retard, session.id);
                session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(session.id);
              }
            }
          }
        }
        
        return { ...slot, session };
      });

      res.json(sessions);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/teacher/sessions/start/:sessionId", authenticateToken, (req: any, res) => {
    try {
      const { sessionId } = req.params;
      const teacherId = req.user?.enseignant_id;
      if (!teacherId) return res.status(403).json({ error: "Enseignant non identifié" });

      const session = db.prepare(`
        SELECT sc.*, ed.heure_debut, ed.heure_fin, ed.enseignant_id, ed.jour 
        FROM sessions_cours sc
        JOIN emplois_du_temps ed ON sc.emploi_du_temps_id = ed.id
        WHERE sc.id = ? AND sc.school_id = ?
      `).get(sessionId, req.schoolId) as any;

      if (!session) return res.status(404).json({ error: "Session non trouvée" });
      if (session.enseignant_id !== teacherId) return res.status(403).json({ error: "Vous n'êtes pas l'enseignant de ce cours" });
      if (session.statut !== 'programmé') return res.status(400).json({ error: "La session est déjà " + session.statut });

      const schoolNow = getSchoolNow(req.schoolId || 1);

      // 1. Strict check: cannot start future courses (e.g. tomorrow)
      if (session.date > schoolNow.dateStr) {
        return res.status(400).json({ 
          error: `Impossible de démarrer ce cours : il est programmé pour le ${session.jour} (${session.date}). Il reste verrouillé jusqu'au jour normal à ${session.heure_debut}.` 
        });
      }

      // 2. Strict check: cannot start past courses
      if (session.date < schoolNow.dateStr) {
        return res.status(400).json({ error: "La date de ce cours est déjà passée et ne peut plus être démarré." });
      }

      // 3. Strict check: course scheduled for today, but start time not reached yet
      const [startH, startM] = session.heure_debut.split(':').map(Number);
      const slotStartMinutes = startH * 60 + startM;
      const currentMinutes = schoolNow.hour * 60 + schoolNow.minute;

      if (currentMinutes < slotStartMinutes) {
        return res.status(400).json({ 
          error: `L'heure du cours n'est pas encore arrivée. Il démarre à ${session.heure_debut} et reste verrouillé d'ici là selon l'emploi du temps.` 
        });
      }

      const diffMins = Math.max(0, currentMinutes - slotStartMinutes);

      if (diffMins > 30) {
        db.prepare("UPDATE sessions_cours SET statut = 'verrouillé', retard_minutes = ? WHERE id = ?").run(diffMins, sessionId);
        return res.status(403).json({ error: "Session verrouillée (retard > 30 min). Contactez l'administration pour déverrouiller." });
      }

      db.prepare("UPDATE sessions_cours SET statut = 'en_cours', heure_debut_reelle = ?, retard_minutes = ? WHERE id = ?")
        .run(schoolNow.timeStr, diffMins, sessionId);

      broadcastNotification(
        ['admin', 'direction', 'surveillant'], 
        "Cours démarré", 
        `L'enseignant ${req.user.nom || ''} ${req.user.prenom || ''} a démarré son cours à ${schoolNow.timeStr} ${diffMins > 0 ? `(avec ${diffMins} min de retard)` : ''}.`, 
        'info', 
        '/admin/sessions-actives', 
        req.schoolId
      );

      res.json({ message: "Cours démarré avec succès", retard: diffMins, heure_debut: schoolNow.timeStr });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/teacher/sessions/cancel/:sessionId", authenticateToken, (req: any, res) => {
    try {
      const { sessionId } = req.params;
      const teacherId = req.user?.enseignant_id;
      const isAdmin = ['admin', 'direction', 'censeur', 'surveillant'].includes(req.user?.role);
      if (!teacherId && !isAdmin) return res.status(403).json({ error: "Enseignant non identifié" });

      const schoolId = req.schoolId || 1;
      const session = db.prepare(`
        SELECT sc.*, ed.heure_debut, ed.heure_fin, ed.enseignant_id 
        FROM sessions_cours sc
        JOIN emplois_du_temps ed ON sc.emploi_du_temps_id = ed.id
        WHERE sc.id = ? AND (sc.school_id = ? OR sc.school_id IS NULL)
      `).get(sessionId, schoolId) as any;

      if (!session) return res.status(404).json({ error: "Session non trouvée" });
      if (!isAdmin && session.enseignant_id !== teacherId) {
        return res.status(403).json({ error: "Vous n'êtes pas l'enseignant de ce cours" });
      }

      if (session.statut !== 'en_cours') {
        return res.status(400).json({ error: "Seul un cours actuellement en cours peut être annulé" });
      }

      db.prepare(`
        UPDATE sessions_cours 
        SET statut = 'programmé', heure_debut_reelle = NULL, heure_fin_reelle = NULL, retard_minutes = 0, heures_validees = 0 
        WHERE id = ?
      `).run(sessionId);

      try {
        broadcastNotification(
          ['admin', 'direction', 'surveillant'],
          "Démarrage de cours annulé",
          `L'enseignant ${req.user.nom || 'Enseignant'} a annulé le démarrage de son cours (${session.heure_debut} - ${session.heure_fin}).`,
          'info',
          '/admin/sessions-actives',
          schoolId
        );
      } catch (err) {
        console.error("Error broadcasting cancel notification:", err);
      }

      res.json({ message: "Démarrage du cours annulé avec succès" });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.get("/api/admin/sessions-actives", authenticateToken, (req: any, res) => {
    try {
      if (!['admin', 'direction', 'censeur', 'surveillant', 'secretariat'].includes(req.user.role)) return res.status(403).json({ error: "Accès refusé" });
      const schoolId = req.schoolId || 1;
      const yearId = getActiveYearId(schoolId);
      const schoolNow = getSchoolNow(schoolId);

      const targetDate = req.query.date ? String(req.query.date) : schoolNow.dateStr;
      const dayFr = req.query.date ? getDayFrForDate(targetDate, schoolNow.timezone) : schoolNow.dayFr;

      // Query all timetable slots for this day so every class and scheduled course appears
      const slots = db.prepare(`
        SELECT ed.*, c.nom as classe_nom, m.nom as matiere_nom, s.nom as salle_nom,
               ens.nom as enseignant_nom, ens.prenom as enseignant_prenom
        FROM emplois_du_temps ed
        LEFT JOIN classes c ON ed.classe_id = c.id
        LEFT JOIN matieres m ON ed.matiere_id = m.id
        LEFT JOIN salles s ON ed.salle_id = s.id
        LEFT JOIN enseignants ens ON ed.enseignant_id = ens.id
        WHERE ed.jour = ? AND (ed.school_id = ? OR ed.school_id IS NULL)
        ORDER BY c.nom ASC, ed.heure_debut ASC
      `).all(dayFr, schoolId) as any[];

      const isFutureDay = targetDate > schoolNow.dateStr;
      const isPastDay = targetDate < schoolNow.dateStr;
      const isToday = targetDate === schoolNow.dateStr;

      const results = slots.map(slot => {
        let session = db.prepare("SELECT * FROM sessions_cours WHERE emploi_du_temps_id = ? AND date = ?").get(slot.id, targetDate) as any;
        if (!session) {
          const newId = db.prepare(`
            INSERT INTO sessions_cours (emploi_du_temps_id, date, statut, annee_id, school_id)
            VALUES (?, ?, 'programmé', ?, ?)
          `).run(slot.id, targetDate, yearId, schoolId).lastInsertRowid;
          session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(newId);
        }

        const [startH, startM] = slot.heure_debut.split(':').map(Number);
        const [endH, endM] = slot.heure_fin.split(':').map(Number);
        const slotStartMinutes = startH * 60 + startM;
        const slotEndMinutes = endH * 60 + endM;
        const currentMinutes = schoolNow.hour * 60 + schoolNow.minute;

        let isUpcoming = false;
        if (isFutureDay) {
          isUpcoming = true;
        } else if (isToday) {
          if (session.statut === 'programmé' || session.statut === 'en_cours') {
            if (currentMinutes >= slotEndMinutes) {
              const finalStatut = session.statut === 'en_cours' ? 'terminé' : 'absent';
              const heureFinReelle = session.statut === 'en_cours' ? slot.heure_fin : null;
              db.prepare("UPDATE sessions_cours SET statut = ?, heure_fin_reelle = ? WHERE id = ?").run(finalStatut, heureFinReelle, session.id);
              session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(session.id);
            } else if (session.statut === 'programmé') {
              if (currentMinutes < slotStartMinutes) {
                isUpcoming = true;
              } else if (currentMinutes > slotStartMinutes + 30) {
                const retard = currentMinutes - slotStartMinutes;
                db.prepare("UPDATE sessions_cours SET statut = 'verrouillé', retard_minutes = ? WHERE id = ?").run(retard, session.id);
                session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(session.id);
              }
            }
          }
        } else if (isPastDay) {
          if (session.statut === 'programmé' || session.statut === 'en_cours') {
            const finalStatut = session.statut === 'en_cours' ? 'terminé' : 'absent';
            db.prepare("UPDATE sessions_cours SET statut = ?, heure_fin_reelle = ? WHERE id = ?").run(finalStatut, slot.heure_fin, session.id);
            session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(session.id);
          }
        }

        return {
          id: session.id,
          emploi_du_temps_id: slot.id,
          date: targetDate,
          heure_debut: slot.heure_debut,
          heure_fin: slot.heure_fin,
          jour: slot.jour,
          classe_id: slot.classe_id,
          classe_nom: slot.classe_nom || 'Classe non assignée',
          matiere_nom: slot.matiere_nom || 'Matière non assignée',
          salle_nom: slot.salle_nom || '',
          enseignant_id: slot.enseignant_id,
          enseignant_nom: slot.enseignant_nom || 'Non',
          enseignant_prenom: slot.enseignant_prenom || 'assigné',
          statut: session.statut,
          is_upcoming: isUpcoming,
          is_future_day: isFutureDay,
          heure_debut_reelle: session.heure_debut_reelle,
          heure_fin_reelle: session.heure_fin_reelle,
          retard_minutes: session.retard_minutes || 0,
          heures_validees: session.heures_validees || 0,
          commentaires: session.commentaires
        };
      });
      
      res.json(results);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

