  app.post("/api/admin/sessions/complete/:sessionId", authenticateToken, (req: any, res) => {
    try {
      if (!['admin', 'direction', 'censeur', 'surveillant'].includes(req.user.role)) return res.status(403).json({ error: "Accès refusé" });
      const schoolId = req.schoolId || 1;
      const schoolNow = getSchoolNow(schoolId);
      
      const session = db.prepare("SELECT * FROM sessions_cours WHERE id = ?").get(req.params.sessionId) as any;
      if (!session) return res.status(404).json({ error: "Session non trouvée" });

      let hours = 0;
      if (session.heure_debut_reelle) {
        const [h1, m1] = session.heure_debut_reelle.split(':').map(Number);
        const [h2, m2] = schoolNow.timeStr.split(':').map(Number);
        hours = Math.max(0, (h2 - h1) + (m2 - m1) / 60);
      }

      db.prepare("UPDATE sessions_cours SET statut = 'terminé', heure_fin_reelle = ?, heures_validees = ? WHERE id = ? AND school_id = ?")
        .run(schoolNow.timeStr, hours.toFixed(2), req.params.sessionId, schoolId);
      notifyTeacherAboutSession(req.params.sessionId, 'terminé', `Votre cours a été clôturé par l'administration à ${schoolNow.timeStr}.`, schoolId);
      res.json({ message: "Session terminée" });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

