  app.post("/api/suivi-eleves/batch", authenticateToken, (req: any, res) => {
    try {
      const { classe_id, date_suivi, records } = req.body;
      if (!classe_id || !date_suivi || !Array.isArray(records)) {
        return res.status(400).json({ error: "Données de suivi invalides." });
      }

      const upsertStmt = db.prepare(`
        INSERT INTO suivi_eleves (eleve_id, classe_id, date_suivi, statut, justifie, motif, remarque, school_id, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
        ON CONFLICT(eleve_id, date_suivi, school_id) DO UPDATE SET
          statut = excluded.statut,
          justifie = excluded.justifie,
          motif = excluded.motif,
          remarque = excluded.remarque,
          classe_id = excluded.classe_id,
          updated_at = CURRENT_TIMESTAMP
      `);

      const saveTransaction = db.transaction((list: any[]) => {
        let saved = 0;
        for (const item of list) {
          if (item && item.eleve_id) {
            upsertStmt.run(
              item.eleve_id,
              classe_id,
              date_suivi,
              item.statut || 'present',
              item.justifie ? 1 : 0,
              item.motif || '',
              item.remarque || '',
              req.schoolId
            );
            saved++;
          }
        }
        return saved;
      });

      const count = saveTransaction(records);
      logActivity(req.userId, 'UPDATE_SUIVI', 'CLASSE', parseInt(classe_id), { date_suivi, count }, req.schoolId);
      res.json({ success: true, count, message: "Suivi des présences enregistré avec succès." });
    } catch (error: any) {
      console.error("Error saving suivi_eleves:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.get("/api/suivi-eleves/bilan-mensuel", authenticateToken, (req: any, res) => {
    try {
      const { classe_id, mois } = req.query; // mois format: 'YYYY-MM'
      if (!classe_id || !mois) {
        return res.status(400).json({ error: "classe_id et mois (format YYYY-MM) sont requis" });
      }

      const classe = db.prepare("SELECT * FROM classes WHERE id = ? AND school_id = ?").get(classe_id, req.schoolId) as any;
      if (!classe) return res.status(404).json({ error: "Classe non trouvée" });

      const school = db.prepare("SELECT * FROM school_info WHERE id = ?").get(req.schoolId) as any;
      const eleves = db.prepare(`
        SELECT e.* 
        FROM eleves e 
        JOIN eleve_annees ea ON e.id = ea.eleve_id 
        WHERE ea.classe_id = ? AND e.school_id = ? 
        ORDER BY e.nom, e.prenom
      `).all(classe_id, req.schoolId) as any[];

      // Fetch all records for this class in this month
      const records = db.prepare(`
        SELECT s.* 
        FROM suivi_eleves s
        WHERE s.classe_id = ? AND s.date_suivi LIKE ? AND s.school_id = ?
        ORDER BY s.date_suivi ASC
      `).all(classe_id, `${mois}%`, req.schoolId) as any[];

      // Distinct dates recorded in this month
      const datesRecorded = Array.from(new Set(records.map(r => r.date_suivi))).sort();

      // Per student stats
      const elevesStats = eleves.map((e: any) => {
        const studentRecords = records.filter(r => r.eleve_id === e.id);
        let presences = 0;
        let absencesJustifiees = 0;
        let absencesInjustifiees = 0;
        let retards = 0;
        const dailyDetails: Record<string, any> = {};

        for (const rec of studentRecords) {
          dailyDetails[rec.date_suivi] = {
            statut: rec.statut,
            justifie: Boolean(rec.justifie),
            motif: rec.motif,
            remarque: rec.remarque
          };

          if (rec.statut === 'present') presences++;
          else if (rec.statut === 'retard') retards++;
          else if (rec.statut === 'absent') {
            if (rec.justifie) absencesJustifiees++;
            else absencesInjustifiees++;
          }
        }

        const totalDaysRecorded = datesRecorded.length;
        const totalAbsences = absencesJustifiees + absencesInjustifiees;
        const attendanceRate = totalDaysRecorded > 0 
          ? Math.round(((presences + retards) / totalDaysRecorded) * 100) 
          : 100;

        return {
          id: e.id,
          nom: e.nom,
          prenom: e.prenom,
          matricule: e.matricule,
          sexe: e.sexe,
          statut_scolaire: e.statut_scolaire || 'Actif',
          presences,
          absencesJustifiees,
          absencesInjustifiees,
          totalAbsences,
          retards,
          attendanceRate,
          dailyDetails
        };
      });

      res.json({
        classe,
        school,
        mois,
        datesRecorded,
        totalDaysCount: datesRecorded.length,
        totalStudentsCount: eleves.length,
        elevesStats
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Promotions
  app.get("/api/eleves/by-year/:yearId", authenticateToken, (req: any, res) => {
    const { yearId } = req.params;
    const { classe_id } = req.query;
    
    const currentYearRecord = db.prepare("SELECT date_debut FROM annees_scolaires WHERE id = ?").get(yearId) as any;
    const currentDateDebut = currentYearRecord ? currentYearRecord.date_debut : '1970-01-01';

    let query = `
      SELECT 
        e.*, 
        c.nom as classe_nom, 
        ea.classe_id as classe_id,
        ea.statut as statut_annee,
        (
          SELECT c2.nom 
          FROM eleve_annees ea2 
          JOIN classes c2 ON ea2.classe_id = c2.id
          JOIN annees_scolaires a2 ON c2.annee_id = a2.id
          WHERE ea2.eleve_id = e.id 
            AND a2.date_debut > ?
          ORDER BY a2.date_debut ASC LIMIT 1
        ) as destination_classe_nom,
        (
          SELECT c2.id 
          FROM eleve_annees ea2 
          JOIN classes c2 ON ea2.classe_id = c2.id
          JOIN annees_scolaires a2 ON c2.annee_id = a2.id
          WHERE ea2.eleve_id = e.id 
            AND a2.date_debut > ?
          ORDER BY a2.date_debut ASC LIMIT 1
        ) as destination_classe_id,
        (
          SELECT ea2.annee_id 
          FROM eleve_annees ea2 
          JOIN classes c2 ON ea2.classe_id = c2.id
          JOIN annees_scolaires a2 ON c2.annee_id = a2.id
          WHERE ea2.eleve_id = e.id 
            AND a2.date_debut > ?
          ORDER BY a2.date_debut ASC LIMIT 1
        ) as destination_annee_id,
        (
          SELECT a2.libelle 
          FROM eleve_annees ea2 
          JOIN classes c2 ON ea2.classe_id = c2.id
          JOIN annees_scolaires a2 ON c2.annee_id = a2.id
          WHERE ea2.eleve_id = e.id 
            AND a2.date_debut > ?
          ORDER BY a2.date_debut ASC LIMIT 1
        ) as destination_annee_libelle,
        (
          SELECT ea2.statut 
          FROM eleve_annees ea2 
          JOIN classes c2 ON ea2.classe_id = c2.id
          JOIN annees_scolaires a2 ON c2.annee_id = a2.id
          WHERE ea2.eleve_id = e.id 
            AND a2.date_debut > ?
          ORDER BY a2.date_debut ASC LIMIT 1
        ) as destination_statut
      FROM eleves e 
      JOIN eleve_annees ea ON e.id = ea.eleve_id
      JOIN classes c ON ea.classe_id = c.id 
      WHERE ea.annee_id = ? AND e.school_id = ?
    `;
    
    const params: any[] = [currentDateDebut, currentDateDebut, currentDateDebut, currentDateDebut, currentDateDebut, yearId, req.schoolId];
    
    if (classe_id) {
      query += ` AND ea.classe_id = ?`;
      params.push(classe_id);
    }
    
    query += ` ORDER BY e.nom, e.prenom`;
    
    const eleves = db.prepare(query).all(...params) as any[];

    const result = eleves.map(e => ({
      ...e,
      passage_effectue: !!e.destination_classe_nom,
      arrieres_calcules: calculateStudentPreviousArrears(e.id, parseInt(yearId), req.schoolId),
      moyenne: calculateAnnualAverage(e.id, parseInt(yearId), e.classe_id, req.schoolId)
    }));

    res.json(result);
  });

  app.post("/api/promotions", authenticateToken, (req: any, res) => {
    const { eleve_ids, target_classe_id, target_year_id, source_year_id, statut } = req.body;
    if (!eleve_ids || !target_classe_id) {
      return res.status(400).json({ error: "Données manquantes" });
    }

    const schoolId = req.schoolId || 1;
    const targetClass = db.prepare("SELECT annee_id, nom FROM classes WHERE id = ?").get(target_classe_id) as any;
    const yearId = target_year_id || (targetClass ? targetClass.annee_id : req.anneeId);
    
    // BLOQUER LES TENTATIVES DE PASSAGE VERS LA MÊME ANNÉE
    if (source_year_id && yearId && parseInt(source_year_id) === parseInt(yearId)) {
      return res.status(400).json({ error: "Passage bloqué : L'année source et l'année de destination ne peuvent pas être identiques." });
    }
    if (targetClass && source_year_id && parseInt(targetClass.annee_id) === parseInt(source_year_id)) {
      return res.status(400).json({ error: "Passage bloqué : La classe de destination appartient à la même année scolaire que l'année source." });
    }

    const stmt = db.prepare("UPDATE eleves SET classe_id = ?, statut = ?, arrieres_scolarite = ?, regime_inscription = 'Ancien' WHERE id = ? AND school_id = ?");
    const historyStmt = db.prepare("INSERT OR REPLACE INTO eleve_annees (eleve_id, annee_id, classe_id, statut, school_id, arrieres_scolarite) VALUES (?, ?, ?, ?, ?, ?)");

    const updateMany = db.transaction((ids, classeId, sId, yId) => {
      for (const id of ids) {
        // Trouver l'année précédente de l'élève pour calculer le reliquat d'arriéré
        const prevYearRecord = db.prepare(`
          SELECT annee_id FROM eleve_annees WHERE eleve_id = ? AND annee_id != ? ORDER BY id DESC LIMIT 1
        `).get(id, yId) as any;
        const sourceYear = prevYearRecord ? prevYearRecord.annee_id : (yId - 1);
        const arrieres = sourceYear ? calculateStudentPreviousArrears(id, sourceYear, sId) : 0;

        // Try to determine if it's a redoublement by comparing source class name and target class name
        let status = statut || 'Passant';
        const eleve = db.prepare("SELECT classe_id FROM eleves WHERE id = ?").get(id) as any;
        if (!statut && eleve && eleve.classe_id) {
          const sourceClass = db.prepare("SELECT nom FROM classes WHERE id = ?").get(eleve.classe_id) as any;
          const targetClassObj = db.prepare("SELECT nom FROM classes WHERE id = ?").get(classeId) as any;
          if (sourceClass && targetClassObj && sourceClass.nom === targetClassObj.nom) {
            status = 'Redoublant(e)';
          }
        }

        stmt.run(classeId, status, arrieres, id, sId);
        historyStmt.run(id, yId, classeId, status, sId, arrieres);
      }
      return ids.length;
    });

    try {
      const count = updateMany(eleve_ids, target_classe_id, schoolId, yearId);
      res.json({ success: true, count });
    } catch (err: any) {
      console.error("Promotions error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Endpoint dédié à la gestion des redoublements (< 10)
  app.post("/api/promotions/redoublements", authenticateToken, (req: any, res) => {
    const { source_classe_id, source_year_id, target_year_id, eleve_ids } = req.body;
    if (!source_classe_id || !source_year_id || !target_year_id) {
      return res.status(400).json({ error: "Paramètres manquants : source_classe_id, source_year_id et target_year_id sont requis." });
    }

    if (parseInt(source_year_id) === parseInt(target_year_id)) {
      return res.status(400).json({ error: "Action bloquée : L'année source et l'année de destination ne peuvent pas être identiques." });
    }

    const schoolId = req.schoolId || 1;
    const sClasseId = parseInt(source_classe_id);
    const sYearId = parseInt(source_year_id);
    const tYearId = parseInt(target_year_id);

    try {
      const sourceClasse = db.prepare("SELECT * FROM classes WHERE id = ? AND school_id = ?").get(sClasseId, schoolId) as any;
      if (!sourceClasse) {
        return res.status(404).json({ error: "Classe source non trouvée" });
      }

      // Trouver ou créer la même classe dans l'année de destination
      let targetClasse = db.prepare("SELECT * FROM classes WHERE nom = ? AND annee_id = ? AND (school_id = ? OR school_id IS NULL)").get(sourceClasse.nom, tYearId, schoolId) as any;
      if (!targetClasse) {
        const createResult = db.prepare(
          "INSERT INTO classes (nom, niveau, frais_scolarite, frais_inscription, tranche1_montant, tranche1_date_limite, tranche2_montant, tranche2_date_limite, tranche3_montant, tranche3_date_limite, devise, annee_id, cycle, school_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
        ).run(sourceClasse.nom, sourceClasse.niveau, sourceClasse.frais_scolarite, sourceClasse.frais_inscription, sourceClasse.tranche1_montant, sourceClasse.tranche1_date_limite, sourceClasse.tranche2_montant, sourceClasse.tranche2_date_limite, sourceClasse.tranche3_montant, sourceClasse.tranche3_date_limite, sourceClasse.devise, tYearId, sourceClasse.cycle, schoolId);
        const newClasseId = createResult.lastInsertRowid as number;

        // Copier les matières de la classe
        const matieres = db.prepare("SELECT * FROM classe_matieres WHERE classe_id = ?").all(sClasseId) as any[];
        for (const m of matieres) {
          db.prepare("INSERT INTO classe_matieres (classe_id, matiere_id, coefficient, school_id) VALUES (?, ?, ?, ?)")
            .run(newClasseId, m.matiere_id, m.coefficient, schoolId);
        }

        targetClasse = db.prepare("SELECT * FROM classes WHERE id = ?").get(newClasseId) as any;
      }

      // Sélectionner les élèves éligibles au redoublement
      let studentsQuery = `
        SELECT e.id, e.nom, e.prenom, e.matricule
        FROM eleves e
        JOIN eleve_annees ea ON e.id = ea.eleve_id
        WHERE ea.classe_id = ? AND ea.annee_id = ? AND e.school_id = ?
      `;
      const queryParams: any[] = [sClasseId, sYearId, schoolId];
      if (eleve_ids && Array.isArray(eleve_ids) && eleve_ids.length > 0) {
        studentsQuery += ` AND e.id IN (${eleve_ids.map(() => '?').join(',')})`;
        queryParams.push(...eleve_ids);
      }

      const studentsInClass = db.prepare(studentsQuery).all(...queryParams) as any[];

      // Filtrer les élèves avec moyenne < 10 (ou tous ceux spécifiés si eleve_ids fourni)
      const repeatingStudents: any[] = [];
      for (const st of studentsInClass) {
        const moyenne = calculateAnnualAverage(st.id, sYearId, sClasseId, schoolId);
        if (eleve_ids && Array.isArray(eleve_ids) && eleve_ids.length > 0) {
          repeatingStudents.push({ ...st, moyenne });
        } else if (moyenne !== null && moyenne < 10) {
          repeatingStudents.push({ ...st, moyenne });
        }
      }

      if (repeatingStudents.length === 0) {
        return res.status(400).json({ error: "Aucun élève avec une moyenne annuelle inférieure à 10 trouvé pour cette classe." });
      }

      const stmt = db.prepare("UPDATE eleves SET classe_id = ?, statut = 'Redoublant(e)', arrieres_scolarite = ?, regime_inscription = 'Ancien' WHERE id = ? AND school_id = ?");
      const historyStmt = db.prepare("INSERT OR REPLACE INTO eleve_annees (eleve_id, annee_id, classe_id, statut, school_id, arrieres_scolarite) VALUES (?, ?, ?, 'Redoublant(e)', ?, ?)");

      db.transaction(() => {
        for (const st of repeatingStudents) {
          const arrieres = calculateStudentPreviousArrears(st.id, sYearId, schoolId);
          stmt.run(targetClasse.id, arrieres, st.id, schoolId);
          historyStmt.run(st.id, tYearId, targetClasse.id, schoolId, arrieres);
          try {
            logActivity(req.userId || 1, 'REDOUBLEMENT', 'eleves', st.id, { source_classe: sourceClasse.nom, target_classe: targetClasse.nom, moyenne: st.moyenne }, schoolId);
          } catch (_) {}
        }
      })();

      res.json({
        success: true,
        count: repeatingStudents.length,
        target_classe_id: targetClasse.id,
        target_classe_nom: targetClasse.nom,
        students: repeatingStudents,
        message: `${repeatingStudents.length} élève(s) avec moyenne < 10 maintenu(s) en ${targetClasse.nom} avec la mention "Redoublant(e)".`
      });
    } catch (err: any) {
      console.error("Redoublement error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Annulation réversible d'un passage
  app.post("/api/promotions/revert", authenticateToken, (req: any, res) => {
    const { eleve_ids, target_year_id, force = false } = req.body;
    if (!eleve_ids || !target_year_id) {
      return res.status(400).json({ error: "Paramètres manquants : eleve_ids et target_year_id sont requis." });
    }

    const ids = Array.isArray(eleve_ids) ? eleve_ids : [eleve_ids];
    if (ids.length === 0) {
      return res.status(400).json({ error: "Aucun élève sélectionné pour l'annulation." });
    }

    const schoolId = req.schoolId || 1;
    const yId = parseInt(target_year_id);

    try {
      const reverted: number[] = [];
      const blocked: { id: number; nom: string; motif: string }[] = [];

      db.transaction(() => {
        for (const id of ids) {
          const eleve = db.prepare("SELECT * FROM eleves WHERE id = ? AND (school_id = ? OR school_id IS NULL)").get(id, schoolId) as any;
          if (!eleve) continue;

          // Vérifier si un enregistrement existe bien dans cette année cible
          const targetEnrollment = db.prepare("SELECT * FROM eleve_annees WHERE eleve_id = ? AND annee_id = ? AND (school_id = ? OR school_id IS NULL)").get(id, yId, schoolId) as any;
          if (!targetEnrollment) {
            continue; // Rien à annuler pour cette année
          }

          // Vérifier si l'élève a des notes ou des paiements enregistrés dans l'année de destination
          if (!force) {
            const notesCount = (db.prepare("SELECT COUNT(*) as c FROM notes WHERE eleve_id = ? AND annee_id = ?").get(id, yId) as any)?.c || 0;
            const paymentsCount = (db.prepare("SELECT COUNT(*) as c FROM paiements WHERE eleve_id = ? AND annee_id = ?").get(id, yId) as any)?.c || 0;

            if (notesCount > 0 || paymentsCount > 0) {
              blocked.push({
                id,
                nom: `${eleve.nom} ${eleve.prenom}`,
                motif: `L'élève possède déjà ${notesCount} note(s) et ${paymentsCount} paiement(s) dans cette année.`
              });
              continue;
            }
          }

          // Supprimer l'inscription de l'année cible
          db.prepare("DELETE FROM eleve_annees WHERE eleve_id = ? AND annee_id = ? AND (school_id = ? OR school_id IS NULL)").run(id, yId, schoolId);

          // Récupérer l'inscription antérieure la plus récente pour réintégrer l'élève
          const prevEnrollment = db.prepare(`
            SELECT ea.classe_id, ea.arrieres_scolarite, ea.statut
            FROM eleve_annees ea
            JOIN annees_scolaires a ON ea.annee_id = a.id
            WHERE ea.eleve_id = ? AND (ea.school_id = ? OR ea.school_id IS NULL)
            ORDER BY a.date_debut DESC, ea.id DESC LIMIT 1
          `).get(id, schoolId) as any;

          if (prevEnrollment) {
            db.prepare(`
              UPDATE eleves 
              SET classe_id = ?, arrieres_scolarite = ?, statut = ?
              WHERE id = ? AND (school_id = ? OR school_id IS NULL)
            `).run(prevEnrollment.classe_id, prevEnrollment.arrieres_scolarite || 0, prevEnrollment.statut || 'Passant', id, schoolId);
          } else {
            db.prepare(`
              UPDATE eleves 
              SET classe_id = NULL
              WHERE id = ? AND (school_id = ? OR school_id IS NULL)
            `).run(id, schoolId);
          }

          // Tracé dans les logs d'audit
          try {
            db.prepare(`
              INSERT INTO audit_logs (utilisateur_id, action, entite_type, entite_id, details, school_id)
              VALUES (?, 'ANNULATION_PASSAGE', 'eleves', ?, ?, ?)
            `).run(req.userId || 1, id, JSON.stringify({ annee_id: yId, prev_classe_id: prevEnrollment?.classe_id }), schoolId);
          } catch (_) {}

          reverted.push(id);
        }
      })();

      if (blocked.length > 0 && reverted.length === 0) {
        return res.status(400).json({ 
          error: "Impossible d'annuler le passage : " + blocked.map(b => `${b.nom} (${b.motif})`).join("; "),
          blocked 
        });
      }

      res.json({ 
        success: true, 
        count: reverted.length, 
        reverted, 
        blocked,
        message: `${reverted.length} passage(s) annulé(s) avec succès.${blocked.length > 0 ? ` (${blocked.length} ignoré(s) car des données y sont associées)` : ''}`
      });
    } catch (err: any) {
      console.error("Revert promotions error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Historique des passages effectués
  app.get("/api/promotions/historique", authenticateToken, (req: any, res) => {
    const { target_year_id, source_year_id, cycle, search } = req.query;
    const schoolId = req.schoolId || 1;
    const targetYId = target_year_id ? parseInt(target_year_id as string) : null;

    if (!targetYId) {
      return res.status(400).json({ error: "target_year_id est requis" });
    }

    try {
      let query = `
        SELECT 
          e.id as eleve_id,
          e.nom,
          e.prenom,
          e.matricule,
          e.sexe,
          e.photo,
          ea_dest.classe_id as target_classe_id,
          c_dest.nom as target_classe_nom,
          c_dest.cycle as target_classe_cycle,
          c_dest.niveau as target_classe_niveau,
          ea_dest.annee_id as target_annee_id,
          a_dest.libelle as target_annee_libelle,
          ea_dest.statut as statut,
          ea_dest.arrieres_scolarite,
          ea_dest.created_at as date_passage,
          ea_src.classe_id as source_classe_id,
          c_src.nom as source_classe_nom,
          ea_src.annee_id as source_annee_id,
          a_src.libelle as source_annee_libelle,
          (SELECT COUNT(*) FROM notes WHERE eleve_id = e.id AND annee_id = ea_dest.annee_id) as notes_count,
          (SELECT COUNT(*) FROM paiements WHERE eleve_id = e.id AND annee_id = ea_dest.annee_id) as paiements_count
        FROM eleve_annees ea_dest
        JOIN eleves e ON ea_dest.eleve_id = e.id
        JOIN classes c_dest ON ea_dest.classe_id = c_dest.id
        JOIN annees_scolaires a_dest ON ea_dest.annee_id = a_dest.id
        LEFT JOIN eleve_annees ea_src ON ea_src.eleve_id = e.id 
          AND ea_src.annee_id = (
            SELECT ea_sub.annee_id 
            FROM eleve_annees ea_sub
            JOIN annees_scolaires a_sub ON ea_sub.annee_id = a_sub.id
            WHERE ea_sub.eleve_id = e.id 
              AND a_sub.date_debut < a_dest.date_debut
            ORDER BY a_sub.date_debut DESC, ea_sub.id DESC 
            LIMIT 1
          )
        LEFT JOIN classes c_src ON ea_src.classe_id = c_src.id
        LEFT JOIN annees_scolaires a_src ON ea_src.annee_id = a_src.id
        WHERE ea_dest.annee_id = ? AND (e.school_id = ? OR e.school_id IS NULL)
      `;

      const params: any[] = [targetYId, schoolId];

      if (source_year_id) {
        query += ` AND ea_src.annee_id = ?`;
        params.push(parseInt(source_year_id as string));
      }

      if (cycle && cycle !== 'all') {
        const cycleLower = (cycle as string).toLowerCase();
        if (cycleLower === 'primaire' || cycleLower === 'maternelle') {
          query += ` AND (c_dest.cycle IN ('primaire', 'maternelle', 'primaire_maternelle') OR c_dest.cycle IS NULL)`;
        } else if (cycleLower === 'secondaire') {
          query += ` AND c_dest.cycle = 'secondaire'`;
        }
      }

      if (search) {
        query += ` AND (e.nom LIKE ? OR e.prenom LIKE ? OR e.matricule LIKE ?)`;
        const s = `%${search}%`;
        params.push(s, s, s);
      }

      query += ` ORDER BY ea_dest.id DESC, e.nom ASC`;

      const rows = db.prepare(query).all(...params) as any[];
      res.json(rows);
    } catch (err: any) {
      console.error("Error fetching promotions historique:", err);
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/promotions/automatique/preview", authenticateToken, (req: any, res) => {
    const { source_year_id, target_year_id, cycle, source_classe_id } = req.query;
    if (!source_year_id || !target_year_id) {
      return res.status(400).json({ error: "Données manquantes" });
    }

    // BLOQUER LES TENTATIVES DE PASSAGE VERS LA MÊME ANNÉE
    if (parseInt(source_year_id as string) === parseInt(target_year_id as string)) {
      return res.status(400).json({ error: "Passage bloqué : L'année source et l'année destination ne peuvent pas être identiques." });
    }

    const cycleFilter = getCycleClassSqlFilter(cycle as string | undefined, 'c');
    const classFilter = source_classe_id ? `AND c.id = ${parseInt(source_classe_id as string)}` : '';
    
    const sourceClasses = db.prepare(`SELECT * FROM classes c WHERE annee_id = ? AND school_id = ? ${cycleFilter} ${classFilter}`).all(source_year_id, req.schoolId);
    const targetClasses = db.prepare(`SELECT * FROM classes c WHERE annee_id = ? AND school_id = ? ${cycleFilter}`).all(target_year_id, req.schoolId);

    const suggestions: any[] = [];

    for (const sourceClasse of sourceClasses as any) {
      // Find next level
      const { nextLevel, prefix, intendedName } = detectNextLevel(sourceClasse.nom, sourceClasse.cycle);

      // Find target class for promotion
      let targetClassePromotion = null;
      if (nextLevel && prefix) {
        const suffix = sourceClasse.nom.replace(prefix, '').trim();
        targetClassePromotion = targetClasses.find((c: any) => c.nom.startsWith(nextLevel) && (suffix ? c.nom.endsWith(suffix) : true)) 
                                || targetClasses.find((c: any) => c.nom.startsWith(nextLevel));
      }

      // Find target class for repetition (same name in target year)
      const targetClasseRedoublement = targetClasses.find((c: any) => c.nom === sourceClasse.nom);

      // Get students based on enrollment in the source class in the source year
      const eleves = db.prepare(`
        SELECT e.id, e.nom, e.prenom, e.matricule
        FROM eleves e
        JOIN eleve_annees ea ON e.id = ea.eleve_id
        WHERE ea.classe_id = ? AND e.school_id = ? AND ea.annee_id = ?
      `).all(sourceClasse.id, req.schoolId, source_year_id) as any[];

      for (const eleve of eleves) {
        // Check if student already has a record in the target year to avoid duplicates in preview
        const alreadyPromoted = db.prepare("SELECT 1 FROM eleve_annees WHERE eleve_id = ? AND annee_id = ?").get(eleve.id, target_year_id);
        if (alreadyPromoted) continue;

        const moyenne = calculateAnnualAverage(eleve.id, parseInt(source_year_id as string), sourceClasse.id, req.schoolId);
        const arrieres = calculateStudentPreviousArrears(eleve.id, parseInt(source_year_id as string), req.schoolId);
        const isAdmitted = moyenne >= 10;
        const targetClasse = isAdmitted ? targetClassePromotion : targetClasseRedoublement;
        const intendedTargetName = isAdmitted ? (intendedName || 'Non trouvée') : sourceClasse.nom;

        suggestions.push({
          eleve_id: eleve.id,
          nom: eleve.nom,
          prenom: eleve.prenom,
          matricule: eleve.matricule,
          moyenne: moyenne,
          arrieres: arrieres,
          source_classe_id: sourceClasse.id,
          source_classe_nom: sourceClasse.nom,
          target_classe_id: targetClasse?.id || null,
          target_classe_nom: targetClasse?.nom || intendedTargetName,
          status: isAdmitted ? 'Passant' : 'Redoublant(e)'
        });
      }
    }

    res.json(suggestions);
  });

  app.post("/api/promotions/automatique/execute", authenticateToken, (req: any, res) => {
    const { suggestions, target_year_id, source_year_id } = req.body;
    if (!suggestions || !Array.isArray(suggestions)) {
      return res.status(400).json({ error: "Données manquantes" });
    }

    const schoolId = req.schoolId || 1;
    const yearId = target_year_id || req.anneeId;

    if (source_year_id && parseInt(source_year_id) === parseInt(yearId)) {
      return res.status(400).json({ error: "Passage bloqué : L'année source et l'année cible ne peuvent pas être identiques." });
    }
    if (suggestions.some((s: any) => s.source_year_id && parseInt(s.source_year_id) === parseInt(yearId))) {
      return res.status(400).json({ error: "Passage bloqué : Des élèves tentent de passer au sein de la même année scolaire." });
    }

    const classCache = new Map<string, number>();

    const getOrCreateClass = (name: string, sourceClassId: number) => {
      const cacheKey = `${name}_${yearId}`;
      if (classCache.has(cacheKey)) return classCache.get(cacheKey);

      let cls = db.prepare("SELECT id FROM classes WHERE nom = ? AND annee_id = ? AND (school_id = ? OR school_id IS NULL)").get(name, yearId, schoolId) as any;
      if (cls) {
        classCache.set(cacheKey, cls.id);
        return cls.id;
      }

      // Create class based on source class
      const sourceCls = db.prepare("SELECT * FROM classes WHERE id = ?").get(sourceClassId) as any;
      if (!sourceCls) return null;

      const result = db.prepare(
        "INSERT INTO classes (nom, niveau, frais_scolarite, frais_inscription, tranche1_montant, tranche1_date_limite, tranche2_montant, tranche2_date_limite, tranche3_montant, tranche3_date_limite, devise, annee_id, cycle, school_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)"
      ).run(name, sourceCls.niveau, sourceCls.frais_scolarite, sourceCls.frais_inscription, sourceCls.tranche1_montant, sourceCls.tranche1_date_limite, sourceCls.tranche2_montant, sourceCls.tranche2_date_limite, sourceCls.tranche3_montant, sourceCls.tranche3_date_limite, sourceCls.devise, yearId, sourceCls.cycle, schoolId);
      
      const newId = result.lastInsertRowid as number;

      // Copy subjects from source class to the new class (without teachers)
      const sourceMatieres = db.prepare("SELECT * FROM classe_matieres WHERE classe_id = ?").all(sourceClassId) as any[];
      for (const sm of sourceMatieres) {
        db.prepare(
          "INSERT INTO classe_matieres (classe_id, matiere_id, coefficient, school_id) VALUES (?, ?, ?, ?)"
        ).run(newId, sm.matiere_id, sm.coefficient, schoolId);
      }

      classCache.set(cacheKey, newId);
      return newId;
    };

    const stmt = db.prepare("UPDATE eleves SET classe_id = ?, statut = ?, arrieres_scolarite = ?, regime_inscription = 'Ancien' WHERE id = ? AND school_id = ?");
    const historyStmt = db.prepare("INSERT OR REPLACE INTO eleve_annees (eleve_id, annee_id, classe_id, statut, school_id, arrieres_scolarite) VALUES (?, ?, ?, ?, ?, ?)");
    
    const transaction = db.transaction((list, sId, yId) => {
      let count = 0;
      for (const s of list) {
        let targetId = s.target_classe_id;
        if (!targetId && s.target_classe_nom && s.target_classe_nom !== 'Non trouvée') {
          targetId = getOrCreateClass(s.target_classe_nom, s.source_classe_id);
        }

        if (targetId) {
          const status = s.status || (s.moyenne >= 10 ? 'Passant' : 'Redoublant(e)');
          const sourceYear = db.prepare("SELECT annee_id FROM classes WHERE id = ?").get(s.source_classe_id) as any;
          const sourceYearId = sourceYear ? sourceYear.annee_id : (yId - 1);
          const arrieres = calculateStudentPreviousArrears(s.eleve_id, sourceYearId, sId);

          stmt.run(targetId, status, arrieres, s.eleve_id, sId);
          historyStmt.run(s.eleve_id, yId, targetId, status, sId, arrieres);
          count++;
        }
      }
      return count;
    });

    try {
      const count = transaction(suggestions, schoolId, yearId);
      res.json({ success: true, count });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

