  // Enseignants
  app.get("/api/enseignants", authenticateToken, (req: any, res) => {
    const { cycle } = req.query;
    let query = `
      SELECT e.*, 
             GROUP_CONCAT(DISTINCT COALESCE(p.nom, m.nom)) as matieres_noms, 
             GROUP_CONCAT(DISTINCT m.id) as matieres_ids,
             GROUP_CONCAT(DISTINCT cl.nom) as classes_noms,
             COUNT(DISTINCT cl.id) as count_classes,
             (SELECT GROUP_CONCAT(DISTINCT c_tit.nom) FROM classes c_tit WHERE c_tit.enseignant_id = e.id AND c_tit.school_id = e.school_id) as classe_titulaire_nom,
             u.id as user_id,
             u.email as user_email,
             u.identifiant as user_identifiant,
             u.role as user_role,
             u.approuve as user_approuve,
             u.is_first_login as user_is_first_login,
             COALESCE(u.mot_de_passe_initial, e.mot_de_passe_initial) as mot_de_passe_initial,
             COALESCE(u.identifiant, e.identifiant_compte) as identifiant_compte
      FROM enseignants e
      LEFT JOIN utilisateurs u ON (u.enseignant_id = e.id OR (e.email IS NOT NULL AND LOWER(u.email) = LOWER(e.email))) AND u.school_id = e.school_id
      LEFT JOIN enseignant_matieres em ON e.id = em.enseignant_id
      LEFT JOIN matieres m ON em.matiere_id = m.id
      LEFT JOIN matieres p ON m.parent_id = p.id
      LEFT JOIN (
        SELECT id, nom, enseignant_id, school_id FROM classes WHERE school_id = ?
        UNION
        SELECT c.id, c.nom, cm.enseignant_id, cm.school_id FROM classe_matieres cm JOIN classes c ON cm.classe_id = c.id WHERE cm.school_id = ?
      ) cl ON cl.enseignant_id = e.id AND cl.school_id = e.school_id
      WHERE e.school_id = ?
    `;
    const params: any[] = [req.schoolId, req.schoolId, req.schoolId];

    if (cycle === 'primaire') {
      query += ` AND (
        LOWER(COALESCE(e.cycle, '')) IN ('primaire', 'maternelle')
        OR EXISTS (
          SELECT 1 FROM classes c_chk 
          WHERE (c_chk.enseignant_id = e.id OR c_chk.prof_principal_id = e.id)
          AND c_chk.school_id = e.school_id
          AND (
            LOWER(c_chk.niveau) IN ('primaire', 'maternelle', 'ci', 'cp', 'ce1', 'ce2', 'cm1', 'cm2', 'sil')
            OR LOWER(c_chk.niveau) LIKE '%primaire%'
            OR LOWER(c_chk.niveau) LIKE '%maternelle%'
            OR LOWER(c_chk.nom) LIKE '%ci%'
            OR LOWER(c_chk.nom) LIKE '%cp%'
            OR LOWER(c_chk.nom) LIKE '%ce1%'
            OR LOWER(c_chk.nom) LIKE '%ce2%'
            OR LOWER(c_chk.nom) LIKE '%cm1%'
            OR LOWER(c_chk.nom) LIKE '%cm2%'
            OR LOWER(c_chk.nom) LIKE '%maternelle%'
          )
        )
      )`;
    } else if (cycle === 'secondaire') {
      query += ` AND (
        LOWER(COALESCE(e.cycle, 'secondaire')) NOT IN ('primaire', 'maternelle')
        AND NOT EXISTS (
          SELECT 1 FROM classes c_chk 
          WHERE (c_chk.enseignant_id = e.id OR c_chk.prof_principal_id = e.id)
          AND c_chk.school_id = e.school_id
          AND (
            LOWER(c_chk.niveau) IN ('primaire', 'maternelle', 'ci', 'cp', 'ce1', 'ce2', 'cm1', 'cm2', 'sil')
            OR LOWER(c_chk.niveau) LIKE '%primaire%'
            OR LOWER(c_chk.niveau) LIKE '%maternelle%'
            OR LOWER(c_chk.nom) LIKE '%ci%'
            OR LOWER(c_chk.nom) LIKE '%cp%'
            OR LOWER(c_chk.nom) LIKE '%ce1%'
            OR LOWER(c_chk.nom) LIKE '%ce2%'
            OR LOWER(c_chk.nom) LIKE '%cm1%'
            OR LOWER(c_chk.nom) LIKE '%cm2%'
            OR LOWER(c_chk.nom) LIKE '%maternelle%'
          )
        )
      )`;
    }

    query += ` GROUP BY e.id ORDER BY e.nom, e.prenom`;

    const enseignants = db.prepare(query).all(...params) as any[];

    for (const e of enseignants) {
      const teacherMatieres = db.prepare(`
        SELECT em.matiere_id as id, m.nom, em.est_principale 
        FROM enseignant_matieres em
        JOIN matieres m ON em.matiere_id = m.id
        WHERE em.enseignant_id = ? AND em.school_id = ?
        ORDER BY em.est_principale DESC, m.nom ASC
      `).all(e.id, req.schoolId) as any[];

      const mainMatiere = teacherMatieres.find(m => m.est_principale === 1) || teacherMatieres[0];
      const secMatieres = teacherMatieres.filter(m => m.id !== mainMatiere?.id);

      e.matiere_principale_id = e.matiere_principale_id || (mainMatiere ? mainMatiere.id : null);
      e.matiere_principale_nom = mainMatiere ? mainMatiere.nom : null;
      e.matieres_secondaires_noms = secMatieres.map(m => m.nom);
      e.matieres_secondaires_str = secMatieres.map(m => m.nom).join(', ');
      e.matieres_details = teacherMatieres;

      const activeYearId = req.query.annee_id ? parseInt(req.query.annee_id) : req.anneeId;
      const activeYearObj = activeYearId ? db.prepare("SELECT * FROM annees_scolaires WHERE id = ?").get(activeYearId) as any : null;
      const reconduitInfo = activeYearId ? db.prepare("SELECT statut, created_at FROM enseignant_annees WHERE enseignant_id = ? AND annee_id = ?").get(e.id, activeYearId) as any : null;
      e.est_reconduit = !!reconduitInfo;
      e.statut_reconduction = reconduitInfo?.statut || null;

      // Calcul de l'ancienneté (nombre d'années et mois)
      const seniorityDate = e.date_embauche || e.created_at;
      const anc = calculateSeniority(seniorityDate, activeYearObj?.date_debut || null);
      e.anciennete_texte = anc.texte;
      e.anciennete_annees = anc.annees;
      e.anciennete_mois = anc.mois;
    }

    res.json(enseignants);
  });

