  app.get("/api/personnel-administratif", authenticateToken, (req: any, res) => {
    const activeYearId = req.query.annee_id && req.query.annee_id !== 'all' ? parseInt(req.query.annee_id as string) : req.anneeId;
    const activeYearObj = activeYearId ? db.prepare("SELECT * FROM annees_scolaires WHERE id = ?").get(activeYearId) as any : null;

    let query = `
      SELECT p.*, 
        (CASE WHEN p.is_fonde = 1 OR LOWER(p.poste) LIKE '%fondé%' OR LOWER(p.poste) LIKE '%fondat%' THEN 1 ELSE 0 END) as is_fonde 
      FROM personnel_administratif p
    `;
    const params: any[] = [];

    if (req.query.annee_id && req.query.annee_id !== 'all') {
      query += ` JOIN personnel_annees pa ON p.id = pa.personnel_id AND pa.annee_id = ? `;
      params.push(activeYearId);
    }

    query += ` WHERE p.school_id = ? 
      ORDER BY (CASE WHEN p.is_fonde = 1 OR LOWER(p.poste) LIKE '%fondé%' OR LOWER(p.poste) LIKE '%fondat%' THEN 0 ELSE 1 END), p.poste, p.nom, p.prenom
    `;
    params.push(req.schoolId);

    const list = db.prepare(query).all(...params) as any[];

    for (const p of list) {
      const reconduitInfo = activeYearId ? db.prepare("SELECT statut, created_at, poste_reconduit FROM personnel_annees WHERE personnel_id = ? AND annee_id = ?").get(p.id, activeYearId) as any : null;
      p.est_reconduit = !!reconduitInfo;
      p.statut_reconduction = reconduitInfo?.statut || null;
      p.poste_reconduit = reconduitInfo?.poste_reconduit || p.poste;

      // Calcul de l'ancienneté (nombre d'années et mois)
      const seniorityDate = p.date_embauche || p.created_at;
      const anc = calculateSeniority(seniorityDate, activeYearObj?.date_debut || null);
      p.anciennete_texte = anc.texte;
      p.anciennete_annees = anc.annees;
      p.anciennete_mois = anc.mois;
    }

    res.json(list);
  });

