  // Reconduire le personnel administratif d'une année scolaire à une autre
  app.post("/api/personnel-administratif/reconduire", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const {
        from_year_id,
        to_year_id,
        staff_ids,
        reconduire_postes = true,
        reconduire_salaires = true
      } = req.body;

      if (!from_year_id || !to_year_id) {
        return res.status(400).json({ error: "L'année source et l'année cible sont requises." });
      }

      if (Number(from_year_id) === Number(to_year_id)) {
        return res.status(400).json({ error: "L'année source et l'année cible doivent être différentes." });
      }

      const fromYear = db.prepare("SELECT * FROM annees_scolaires WHERE id = ? AND (school_id = ? OR school_id IS NULL)").get(from_year_id, schoolId) as any;
      const toYear = db.prepare("SELECT * FROM annees_scolaires WHERE id = ? AND (school_id = ? OR school_id IS NULL)").get(to_year_id, schoolId) as any;

      if (!fromYear || !toYear) {
        return res.status(404).json({ error: "Une ou plusieurs années scolaires sont introuvables." });
      }

      const result = db.transaction(() => {
        let staffList: any[] = [];
        if (Array.isArray(staff_ids) && staff_ids.length > 0) {
          const placeholders = staff_ids.map(() => '?').join(',');
          staffList = db.prepare(`SELECT * FROM personnel_administratif WHERE id IN (${placeholders}) AND (school_id = ? OR school_id IS NULL)`).all(...staff_ids, schoolId);
        } else {
          staffList = db.prepare("SELECT * FROM personnel_administratif WHERE (school_id = ? OR school_id IS NULL)").all(schoolId);
        }

        if (staffList.length === 0) {
          return {
            staff_count: 0,
            message: "Aucun membre du personnel trouvé pour la reconduction."
          };
        }

        let staffReconduits = 0;
        const nowStr = new Date().toISOString().split('T')[0];

        for (const s of staffList) {
          // Si date_embauche manquante, initialiser avec fromYear.date_debut ou created_at
          if (!s.date_embauche) {
            const initialDate = fromYear.date_debut || s.created_at || nowStr;
            db.prepare("UPDATE personnel_administratif SET date_embauche = ? WHERE id = ?").run(initialDate, s.id);
          }

          // Enregistrer dans personnel_annees
          db.prepare(`
            INSERT INTO personnel_annees (personnel_id, annee_id, statut, poste_reconduit, school_id)
            VALUES (?, ?, 'Reconduit', ?, ?)
            ON CONFLICT(personnel_id, annee_id) DO UPDATE SET 
              statut = 'Reconduit',
              poste_reconduit = excluded.poste_reconduit
          `).run(s.id, to_year_id, reconduire_postes ? s.poste : null, schoolId);

          staffReconduits++;
        }

        return {
          staff_count: staffReconduits
        };
      })();

      logActivity(
        req.userId,
        'RECONDUCTION_PERSONNEL',
        'PERSONNEL',
        0,
        { from_year: fromYear.libelle, to_year: toYear.libelle, ...result },
        schoolId
      );

      res.json({
        success: true,
        message: `${result.staff_count} membre(s) du personnel reconduit(s) avec succès pour l'année ${toYear.libelle}.`,
        stats: result,
        from_year: fromYear.libelle,
        to_year: toYear.libelle
      });
    } catch (error: any) {
      console.error("Erreur reconduction personnel:", error);
      res.status(500).json({ error: error.message || "Erreur lors de la reconduction du personnel." });
    }
  });

