  app.post("/api/personnel-administratif/fonde-profile", authenticateToken, (req: any, res) => {
    if (req.user.role !== 'admin' && req.user.role !== 'super_admin' && req.user.role !== 'fonde') {
      return res.status(403).json({ error: "Seul l'administrateur principal (Fondé) peut configurer son profil." });
    }

    const {
      nom, prenom, telephone, email, adresse, sexe, date_naissance,
      niveau_etudes, diplome, type_contrat, salaire_mensuel, statut,
      photo, matricule, lieu_naissance
    } = req.body;

    if (!nom || !prenom) {
      return res.status(400).json({ error: "Le nom et le prénom du Fondé sont obligatoires." });
    }

    const existingFonde = db.prepare("SELECT * FROM personnel_administratif WHERE school_id = ? AND (is_fonde = 1 OR LOWER(poste) LIKE '%fondé%' OR LOWER(poste) LIKE '%fondat%') LIMIT 1").get(req.schoolId) as any;

    let finalMatricule = (matricule && typeof matricule === 'string' && matricule.trim() !== '') 
      ? matricule.trim() 
      : (existingFonde?.matricule || `FONDE-${new Date().getFullYear()}-${String(req.schoolId).padStart(3, '0')}`);

    let fondeId: number;

    if (existingFonde) {
      db.prepare(`
        UPDATE personnel_administratif
        SET nom = ?, prenom = ?, poste = 'Fondateur / Fondé (Admi)', telephone = ?, email = ?, adresse = ?,
            sexe = ?, date_naissance = ?, niveau_etudes = ?, diplome = ?,
            type_contrat = ?, salaire_mensuel = ?, statut = ?,
            photo = COALESCE(?, photo), matricule = ?, lieu_naissance = COALESCE(?, lieu_naissance),
            is_fonde = 1, user_id = ?
        WHERE id = ? AND school_id = ?
      `).run(
        nom.trim(), prenom.trim(), telephone || '', email || '', adresse || '',
        sexe || 'M', date_naissance || '', niveau_etudes || 'Supérieur', diplome || '',
        type_contrat || 'Fondateur', parseFloat(salaire_mensuel) || 0, statut || 'Actif',
        photo || null, finalMatricule, lieu_naissance || '', req.userId, existingFonde.id, req.schoolId
      );
      fondeId = existingFonde.id;
    } else {
      const info = db.prepare(`
        INSERT INTO personnel_administratif (
          nom, prenom, poste, telephone, email, adresse, sexe, date_naissance,
          niveau_etudes, diplome, type_contrat, salaire_mensuel, statut,
          photo, matricule, lieu_naissance, is_fonde, user_id, school_id
        ) VALUES (?, ?, 'Fondateur / Fondé (Admi)', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
      `).run(
        nom.trim(), prenom.trim(), telephone || '', email || '', adresse || '',
        sexe || 'M', date_naissance || '', niveau_etudes || 'Supérieur', diplome || '',
        type_contrat || 'Fondateur', parseFloat(salaire_mensuel) || 0, statut || 'Actif',
        photo || null, finalMatricule, lieu_naissance || '', req.userId, req.schoolId
      );
      fondeId = info.lastInsertRowid as number;
    }

    // Link user account to the Fondé staff record
    db.prepare("UPDATE utilisateurs SET personnel_id = ?, nom = ? WHERE id = ?").run(fondeId, `${prenom.trim()} ${nom.trim()}`, req.userId);
    
    // Update school info founder name
    try {
      db.prepare("UPDATE school_info SET nom_fondateur = ?, contact_fondateur = COALESCE(NULLIF(contact_fondateur, ''), ?) WHERE id = ?")
        .run(`${prenom.trim()} ${nom.trim()}`, telephone || '', req.schoolId);
    } catch(e) {}

    logActivity(req.userId, 'UPDATE', 'FONDE_PROFILE', fondeId, { nom, prenom, matricule: finalMatricule }, req.schoolId);
    res.json({ success: true, id: fondeId, matricule: finalMatricule, fullName: `${prenom.trim()} ${nom.trim()}` });
  });

