  // Helper for administrative staff duplicate check
  function checkStaffDuplicate(dbInstance: any, schoolId: number, data: { nom?: string; prenom?: string; telephone?: string; email?: string; date_naissance?: string; lieu_naissance?: string; matricule?: string }, excludeId: number | null = null) {
    try {
      const existingStaff = dbInstance.prepare("SELECT id, matricule, nom, prenom, telephone, email, date_naissance, lieu_naissance FROM personnel_administratif WHERE school_id = ? OR school_id IS NULL").all(schoolId) as any[];
      const res = evaluatePersonDuplicateCascade(existingStaff, data, excludeId);
      if (res.status === 'strict_duplicate') return res.reason;
      return null;
    } catch (e) {
      console.warn("checkStaffDuplicate error:", e);
      return null;
    }
  }

  function checkStaffDuplicateFull(dbInstance: any, schoolId: number, data: any, excludeId: number | null = null) {
    const existingStaff = dbInstance.prepare("SELECT id, matricule, nom, prenom, telephone, email, date_naissance, lieu_naissance FROM personnel_administratif WHERE school_id = ? OR school_id IS NULL").all(schoolId) as any[];
    return evaluatePersonDuplicateCascade(existingStaff, data, excludeId);
  }

  

