  app.post("/api/enseignant-bilans-hebdo", authenticateToken, (req: any, res) => {
    try {
      const { items, annee_id, semaine_numero, date_debut, date_fin } = req.body;
      const yearId = annee_id || req.anneeId;
      if (!Array.isArray(items) || !yearId || !semaine_numero) {
        return res.status(400).json({ error: "Données manquantes ou invalides" });
      }

      const now = new Date().toISOString();
      const saveTx = db.transaction(() => {
        for (const item of items) {
          const existing = db.prepare(`
            SELECT id FROM enseignant_bilans_hebdo 
            WHERE enseignant_id = ? AND semaine_numero = ? AND annee_id = ? AND school_id = ?
          `).get(item.enseignant_id, semaine_numero, yearId, req.schoolId) as any;

          const heuresPrev = parseFloat(item.heures_prevues) || 0;
          const heuresEff = parseFloat(item.heures_effectuees) || 0;
          const taux = parseFloat(item.taux_horaire) || 0;
          const montantCalc = heuresEff * taux;
          const detailsJson = item.details_creneaux ? JSON.stringify(item.details_creneaux) : '[]';

          if (existing) {
            db.prepare(`
              UPDATE enseignant_bilans_hebdo
              SET heures_prevues = ?, heures_effectuees = ?, taux_horaire = ?, montant_calcule = ?,
                  statut = ?, commentaires = ?, details_creneaux = ?, valide_par = ?, date_validation = ?
              WHERE id = ? AND school_id = ?
            `).run(
              heuresPrev, heuresEff, taux, montantCalc,
              item.statut || 'Validé', item.commentaires || '', detailsJson,
              req.userId, now, existing.id, req.schoolId
            );
          } else {
            db.prepare(`
              INSERT INTO enseignant_bilans_hebdo (
                annee_id, enseignant_id, semaine_numero, date_debut, date_fin,
                heures_prevues, heures_effectuees, taux_horaire, montant_calcule,
                statut, commentaires, details_creneaux, valide_par, date_validation, school_id
              ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            `).run(
              yearId, item.enseignant_id, semaine_numero, date_debut || '', date_fin || '',
              heuresPrev, heuresEff, taux, montantCalc,
              item.statut || 'Validé', item.commentaires || '', detailsJson,
              req.userId, now, req.schoolId
            );
          }
        }
      });

      saveTx();
      res.json({ success: true });
    } catch (error: any) {
      console.error("Error in POST /api/enseignant-bilans-hebdo:", error);
      res.status(500).json({ error: error.message });
    }
  });

