  // Global Financial Relations & Cash Flow Overview
  app.get("/api/finances/overview", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId;
      const { annee_id, cycle, startDate, endDate } = req.query;
      const yearId = annee_id || getActiveYearId(schoolId);

      // 1. Encaissements de scolarité
      let scolQuery = `
        SELECT p.*, c.cycle as classe_cycle, c.nom as classe_nom
        FROM paiements p
        JOIN eleves e ON p.eleve_id = e.id
        LEFT JOIN classes c ON e.classe_id = c.id
        WHERE p.school_id = ?
      `;
      const scolParams: any[] = [schoolId];
      if (yearId) {
        scolQuery += ` AND p.annee_id = ?`;
        scolParams.push(yearId);
      }
      if (cycle && cycle !== 'all') {
        scolQuery += ` AND c.cycle = ?`;
        scolParams.push(cycle);
      }
      if (startDate) {
        scolQuery += ` AND p.date_paiement >= ?`;
        scolParams.push(startDate);
      }
      if (endDate) {
        scolQuery += ` AND p.date_paiement <= ?`;
        scolParams.push(endDate);
      }

      const allPaiements = db.prepare(scolQuery).all(...scolParams) as any[];
      const totalScolarite = allPaiements.reduce((sum, p) => sum + (parseFloat(p.montant) || 0), 0);

      // Group tuition by type
      const scolariteByTypeMap: Record<string, { total: number; count: number }> = {};
      allPaiements.forEach(p => {
        const type = p.type_paiement || 'Frais de scolarité';
        if (!scolariteByTypeMap[type]) scolariteByTypeMap[type] = { total: 0, count: 0 };
        scolariteByTypeMap[type].total += (parseFloat(p.montant) || 0);
        scolariteByTypeMap[type].count += 1;
      });

      // 2. Autres recettes (Dons, Subventions, etc.)
      let autresRecQuery = `SELECT * FROM autres_recettes WHERE school_id = ? AND statut != 'Annulé'`;
      const autresRecParams: any[] = [schoolId];
      if (yearId) {
        autresRecQuery += ` AND annee_id = ?`;
        autresRecParams.push(yearId);
      }
      if (cycle && cycle !== 'all') {
        autresRecQuery += ` AND (cycle = ? OR cycle = 'all')`;
        autresRecParams.push(cycle);
      }
      if (startDate) {
        autresRecQuery += ` AND date_recette >= ?`;
        autresRecParams.push(startDate);
      }
      if (endDate) {
        autresRecQuery += ` AND date_recette <= ?`;
        autresRecParams.push(endDate);
      }

      const allAutresRecettes = db.prepare(autresRecQuery).all(...autresRecParams) as any[];
      const totalAutresRecettes = allAutresRecettes.reduce((sum, r) => sum + (parseFloat(r.montant) || 0), 0);

      const autresRecettesByTypeMap: Record<string, { total: number; count: number }> = {};
      allAutresRecettes.forEach(r => {
        const cat = r.categorie || 'Autre recette';
        if (!autresRecettesByTypeMap[cat]) autresRecettesByTypeMap[cat] = { total: 0, count: 0 };
        autresRecettesByTypeMap[cat].total += (parseFloat(r.montant) || 0);
        autresRecettesByTypeMap[cat].count += 1;
      });

      const totalEntrees = totalScolarite + totalAutresRecettes;

      // 3. Salaires enseignants
      let profQuery = `
        SELECT p.*, e.cycle as enseignant_cycle
        FROM enseignant_paiements_mensuels p
        JOIN enseignants e ON p.enseignant_id = e.id
        WHERE p.school_id = ?
      `;
      const profParams: any[] = [schoolId];
      if (yearId) {
        profQuery += ` AND p.annee_id = ?`;
        profParams.push(yearId);
      }
      if (cycle && cycle !== 'all') {
        profQuery += ` AND (p.type_cycle = ? OR e.cycle = ?)`;
        profParams.push(cycle, cycle);
      }
      if (startDate) {
        profQuery += ` AND p.date_paiement >= ?`;
        profParams.push(startDate);
      }
      if (endDate) {
        profQuery += ` AND p.date_paiement <= ?`;
        profParams.push(endDate);
      }

      const allProfPaiements = db.prepare(profQuery).all(...profParams) as any[];
      const totalSalairesProfsPaye = allProfPaiements.reduce((sum, p) => sum + (parseFloat(p.montant_paye) || 0), 0);
      const totalSalairesProfsDus = allProfPaiements.reduce((sum, p) => sum + (parseFloat(p.montant) || 0), 0);
      const resteAPayerProfs = Math.max(0, totalSalairesProfsDus - totalSalairesProfsPaye);

      // 4. Salaires personnel administratif
      let adminQuery = `
        SELECT p.*
        FROM personnel_paiements p
        JOIN personnel_administratif pa ON p.personnel_id = pa.id
        WHERE p.school_id = ?
      `;
      const adminParams: any[] = [schoolId];
      if (yearId) {
        adminQuery += ` AND p.annee_id = ?`;
        adminParams.push(yearId);
      }
      if (startDate) {
        adminQuery += ` AND p.date_paiement >= ?`;
        adminParams.push(startDate);
      }
      if (endDate) {
        adminQuery += ` AND p.date_paiement <= ?`;
        adminParams.push(endDate);
      }

      const allAdminPaiements = db.prepare(adminQuery).all(...adminParams) as any[];
      const totalSalairesAdminPaye = allAdminPaiements.reduce((sum, p) => sum + (parseFloat(p.montant_paye) || 0), 0);
      const totalSalairesAdminDus = allAdminPaiements.reduce((sum, p) => sum + (parseFloat(p.net_a_payer) || 0), 0);
      const resteAPayerAdmin = Math.max(0, totalSalairesAdminDus - totalSalairesAdminPaye);

      const totalMasseSalarialePayee = totalSalairesProfsPaye + totalSalairesAdminPaye;
      const totalMasseSalarialeDue = totalSalairesProfsDus + totalSalairesAdminDus;

      // 5. Autres dépenses (Loyer, Eau/Électricité, Fournitures, Maintenance, etc.)
      let depQuery = `SELECT * FROM depenses WHERE school_id = ? AND statut != 'Annulé'`;
      const depParams: any[] = [schoolId];
      if (yearId) {
        depQuery += ` AND annee_id = ?`;
        depParams.push(yearId);
      }
      if (cycle && cycle !== 'all') {
        depQuery += ` AND (cycle = ? OR cycle = 'all')`;
        depParams.push(cycle);
      }
      if (startDate) {
        depQuery += ` AND date_depense >= ?`;
        depParams.push(startDate);
      }
      if (endDate) {
        depQuery += ` AND date_depense <= ?`;
        depParams.push(endDate);
      }

      const allDepenses = db.prepare(depQuery).all(...depParams) as any[];
      const totalAutresDepenses = allDepenses.reduce((sum, d) => sum + (parseFloat(d.montant) || 0), 0);

      const depensesByCatMap: Record<string, { total: number; count: number }> = {};
      allDepenses.forEach(d => {
        const cat = d.categorie || 'Autres charges';
        if (!depensesByCatMap[cat]) depensesByCatMap[cat] = { total: 0, count: 0 };
        depensesByCatMap[cat].total += (parseFloat(d.montant) || 0);
        depensesByCatMap[cat].count += 1;
      });

      const totalSorties = totalMasseSalarialePayee + totalAutresDepenses;
      const soldeNet = totalEntrees - totalSorties;

      // Financial Correlation Ratios
      const tauxCouvertureDepenses = totalSorties > 0 ? ((totalScolarite / totalSorties) * 100) : 100;
      const ratioMasseSalariale = totalScolarite > 0 ? ((totalMasseSalarialePayee / totalScolarite) * 100) : 0;
      const ratioAutresDepenses = totalScolarite > 0 ? ((totalAutresDepenses / totalScolarite) * 100) : 0;
      const margeNettePourcent = totalEntrees > 0 ? ((soldeNet / totalEntrees) * 100) : 0;

      // 6. Monthly Breakdown (12 academic months: Septembre à Août)
      const monthsOrder = [
        { key: '09', name: 'Septembre' },
        { key: '10', name: 'Octobre' },
        { key: '11', name: 'Novembre' },
        { key: '12', name: 'Décembre' },
        { key: '01', name: 'Janvier' },
        { key: '02', name: 'Février' },
        { key: '03', name: 'Mars' },
        { key: '04', name: 'Avril' },
        { key: '05', name: 'Mai' },
        { key: '06', name: 'Juin' },
        { key: '07', name: 'Juillet' },
        { key: '08', name: 'Août' },
      ];

      let runningSolde = 0;
      const monthlyTrend = monthsOrder.map(m => {
        // Tuitions in month
        const scolM = allPaiements
          .filter(p => p.date_paiement && p.date_paiement.split('-')[1] === m.key)
          .reduce((sum, p) => sum + (parseFloat(p.montant) || 0), 0);

        // Other revenues in month
        const recM = allAutresRecettes
          .filter(r => r.date_recette && r.date_recette.split('-')[1] === m.key)
          .reduce((sum, r) => sum + (parseFloat(r.montant) || 0), 0);

        // Teacher salaries in month
        const profM = allProfPaiements
          .filter(p => {
            if (p.mois && p.mois.toLowerCase().includes(m.name.toLowerCase())) return true;
            if (p.date_paiement && p.date_paiement.split('-')[1] === m.key) return true;
            return false;
          })
          .reduce((sum, p) => sum + (parseFloat(p.montant_paye) || 0), 0);

        // Staff salaries in month
        const staffM = allAdminPaiements
          .filter(p => {
            if (p.mois && p.mois.toLowerCase().includes(m.name.toLowerCase())) return true;
            if (p.date_paiement && p.date_paiement.split('-')[1] === m.key) return true;
            return false;
          })
          .reduce((sum, p) => sum + (parseFloat(p.montant_paye) || 0), 0);

        // Expenses in month
        const depM = allDepenses
          .filter(d => d.date_depense && d.date_depense.split('-')[1] === m.key)
          .reduce((sum, d) => sum + (parseFloat(d.montant) || 0), 0);

        const entreesM = scolM + recM;
        const sortiesM = profM + staffM + depM;
        const netM = entreesM - sortiesM;
        runningSolde += netM;

        return {
          mois: m.name,
          moisKey: m.key,
          scolarite: scolM,
          autres_recettes: recM,
          entrees: entreesM,
          salaires_enseignants: profM,
          salaires_personnel: staffM,
          masse_salariale: profM + staffM,
          autres_depenses: depM,
          sorties: sortiesM,
          solde_mensuel: netM,
          solde_cumule: runningSolde
        };
      });

      res.json({
        total_scolarite: totalScolarite,
        scolarite_by_type: Object.entries(scolariteByTypeMap).map(([type, data]) => ({ type, ...data })),
        total_autres_recettes: totalAutresRecettes,
        autres_recettes_by_cat: Object.entries(autresRecettesByTypeMap).map(([cat, data]) => ({ categorie: cat, ...data })),
        total_entrees: totalEntrees,

        total_salaires_enseignants_paye: totalSalairesProfsPaye,
        total_salaires_enseignants_dus: totalSalairesProfsDus,
        reste_a_payer_enseignants: resteAPayerProfs,

        total_salaires_personnel_paye: totalSalairesAdminPaye,
        total_salaires_personnel_dus: totalSalairesAdminDus,
        reste_a_payer_personnel: resteAPayerAdmin,

        total_masse_salariale_payee: totalMasseSalarialePayee,
        total_masse_salariale_due: totalMasseSalarialeDue,
        total_autres_depenses: totalAutresDepenses,
        depenses_by_cat: Object.entries(depensesByCatMap).map(([cat, data]) => ({ categorie: cat, ...data })),
        total_sorties: totalSorties,

        solde_net: soldeNet,
        taux_couverture_depenses: Math.round(tauxCouvertureDepenses * 10) / 10,
        ratio_masse_salariale: Math.round(ratioMasseSalariale * 10) / 10,
        ratio_autres_depenses: Math.round(ratioAutresDepenses * 10) / 10,
        marge_nette_pourcent: Math.round(margeNettePourcent * 10) / 10,

        monthly_trend: monthlyTrend,
        summary_counts: {
          paiements_count: allPaiements.length,
          autres_recettes_count: allAutresRecettes.length,
          prof_paiements_count: allProfPaiements.length,
          admin_paiements_count: allAdminPaiements.length,
          depenses_count: allDepenses.length
        }
      });
    } catch (error: any) {
      console.error("Error in /api/finances/overview:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Aperçu Prévisionnel des Recettes : Tranches & Total Annuel par Classe
  app.get("/api/finances/previsions-recettes", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId;
      const { annee_id } = req.query;
      const yearId = annee_id ? parseInt(annee_id as string, 10) : getActiveYearId(schoolId);
      if (!yearId) {
        return res.json({ classes: [], synthese: null });
      }

      // Fetch all classes for the school and year
      const classesRaw = db.prepare(`
        SELECT c.*,
          (SELECT COUNT(*) FROM eleve_annees ea 
           JOIN eleves e ON ea.eleve_id = e.id 
           WHERE ea.classe_id = c.id AND (ea.school_id = :schoolId OR ea.school_id IS NULL)
           AND (e.statut_scolaire IS NULL OR e.statut_scolaire != 'Abandon')
           AND (e.est_abandonne IS NULL OR e.est_abandonne = 0)) as nombre_eleves
        FROM classes c
        WHERE (c.school_id = :schoolId OR c.school_id IS NULL)
          AND (c.annee_id = :yearId OR c.annee_id IS NULL)
        ORDER BY 
          CASE 
            WHEN LOWER(COALESCE(c.cycle, '')) LIKE '%matern%' THEN 1 
            WHEN LOWER(COALESCE(c.cycle, '')) LIKE '%prim%' THEN 2 
            ELSE 3 
          END,
          c.nom ASC
      `).all({ schoolId, yearId }) as any[];

      // Fetch collected tuition payments grouped by class
      const paiementsGrouped = db.prepare(`
        SELECT ea.classe_id,
          SUM(p.montant) as total_encaisse,
          SUM(CASE WHEN LOWER(COALESCE(p.tranche, '')) LIKE '%1%' OR LOWER(p.type_paiement) LIKE '%tranche 1%' THEN p.montant ELSE 0 END) as tranche1_encaissee,
          SUM(CASE WHEN LOWER(COALESCE(p.tranche, '')) LIKE '%2%' OR LOWER(p.type_paiement) LIKE '%tranche 2%' THEN p.montant ELSE 0 END) as tranche2_encaissee,
          SUM(CASE WHEN LOWER(COALESCE(p.tranche, '')) LIKE '%3%' OR LOWER(p.type_paiement) LIKE '%tranche 3%' THEN p.montant ELSE 0 END) as tranche3_encaissee,
          SUM(CASE WHEN LOWER(p.type_paiement) LIKE '%inscription%' THEN p.montant ELSE 0 END) as inscription_encaissee,
          SUM(CASE WHEN LOWER(p.type_paiement) NOT LIKE '%scolarit%' AND LOWER(p.type_paiement) NOT LIKE '%tranche%' AND LOWER(p.type_paiement) NOT LIKE '%inscription%' THEN p.montant ELSE 0 END) as autres_encaisse
        FROM paiements p
        JOIN eleve_annees ea ON p.eleve_id = ea.eleve_id AND ea.annee_id = p.annee_id
        WHERE (p.school_id = :schoolId OR p.school_id IS NULL)
          AND p.annee_id = :yearId
        GROUP BY ea.classe_id
      `).all({ schoolId, yearId }) as any[];

      const payMap = new Map<number, any>();
      paiementsGrouped.forEach(p => payMap.set(p.classe_id, p));

      const processedClasses = classesRaw.map((cls: any) => {
        const effectif = Number(cls.nombre_eleves || 0);
        const fraisInscription = Number(cls.frais_inscription || 0);
        let scolarite = Number(cls.frais_scolarite || 0);
        let t1 = Number(cls.tranche1_montant || 0);
        let t2 = Number(cls.tranche2_montant || 0);
        let t3 = Number(cls.tranche3_montant || 0);
        const annexes = Number(cls.frais_annexes || 0);

        // If scolarite is set but tranches are 0, distribute default 40% - 30% - 30%
        if (scolarite > 0 && (t1 + t2 + t3 === 0)) {
          t1 = Math.round(scolarite * 0.4);
          t2 = Math.round(scolarite * 0.3);
          t3 = scolarite - (t1 + t2);
        } else if ((t1 + t2 + t3 > 0) && scolarite === 0) {
          scolarite = t1 + t2 + t3;
        }

        const totalInscriptionPrevu = effectif * fraisInscription;
        const totalT1Prevu = effectif * t1;
        const totalT2Prevu = effectif * t2;
        const totalT3Prevu = effectif * t3;
        const totalScolaritePrevu = effectif * scolarite;
        const totalAnnexesPrevu = effectif * annexes;
        const totalAnnuelPrevu = totalInscriptionPrevu + totalScolaritePrevu + totalAnnexesPrevu;

        const actualPay = payMap.get(cls.id) || {};
        const totalEncaisse = Number(actualPay.total_encaisse || 0);
        const t1Encaissee = Number(actualPay.tranche1_encaissee || 0);
        const t2Encaissee = Number(actualPay.tranche2_encaissee || 0);
        const t3Encaissee = Number(actualPay.tranche3_encaissee || 0);
        const inscriptionEncaissee = Number(actualPay.inscription_encaissee || 0);
        const autresEncaisse = Number(actualPay.autres_encaisse || 0);

        const resteARecouvrer = Math.max(0, totalAnnuelPrevu - totalEncaisse);
        const tauxRecouvrement = totalAnnuelPrevu > 0 ? Math.min(100, Math.round((totalEncaisse / totalAnnuelPrevu) * 100)) : 0;

        // Normalize cycle
        let normalizedCycle = (cls.cycle || '').toLowerCase().trim();
        const niveauLower = (cls.niveau || '').toLowerCase();
        const nomLower = (cls.nom || '').toLowerCase();

        if (normalizedCycle.includes('matern') || niveauLower.includes('matern') || nomLower.includes('matern') || nomLower.includes('ci') || nomLower.includes('petite') || nomLower.includes('moyenne') || nomLower.includes('grande section')) {
          normalizedCycle = 'maternelle';
        } else if (normalizedCycle.includes('prim') || niveauLower.includes('prim') || nomLower.includes('cp') || nomLower.includes('ce1') || nomLower.includes('ce2') || nomLower.includes('cm1') || nomLower.includes('cm2')) {
          normalizedCycle = 'primaire';
        } else {
          normalizedCycle = 'secondaire';
        }

        return {
          id: cls.id,
          nom: cls.nom,
          niveau: cls.niveau,
          cycle: normalizedCycle,
          devise: cls.devise || 'FCFA',
          nombre_eleves: effectif,
          frais_inscription: fraisInscription,
          tranche1_montant: t1,
          tranche1_date_limite: cls.tranche1_date_limite || '',
          tranche2_montant: t2,
          tranche2_date_limite: cls.tranche2_date_limite || '',
          tranche3_montant: t3,
          tranche3_date_limite: cls.tranche3_date_limite || '',
          frais_scolarite: scolarite,
          frais_annexes: annexes,
          total_inscription_prevu: totalInscriptionPrevu,
          total_tranche1_prevu: totalT1Prevu,
          total_tranche2_prevu: totalT2Prevu,
          total_tranche3_prevu: totalT3Prevu,
          total_scolarite_prevu: totalScolaritePrevu,
          total_annexes_prevu: totalAnnexesPrevu,
          total_annuel_prevu: totalAnnuelPrevu,
          total_encaisse: totalEncaisse,
          tranche1_encaissee: t1Encaissee,
          tranche2_encaissee: t2Encaissee,
          tranche3_encaissee: t3Encaissee,
          inscription_encaissee: inscriptionEncaissee,
          autres_encaisse: autresEncaisse,
          reste_a_recouvrer: resteARecouvrer,
          taux_recouvrement: tauxRecouvrement
        };
      });

      const computeSubtotal = (classList: any[]) => {
        return classList.reduce((acc, c) => {
          acc.effectif += c.nombre_eleves;
          acc.total_inscription_prevu += c.total_inscription_prevu;
          acc.total_tranche1_prevu += c.total_tranche1_prevu;
          acc.total_tranche2_prevu += c.total_tranche2_prevu;
          acc.total_tranche3_prevu += c.total_tranche3_prevu;
          acc.total_scolarite_prevu += c.total_scolarite_prevu;
          acc.total_annexes_prevu += c.total_annexes_prevu;
          acc.total_annuel_prevu += c.total_annuel_prevu;
          acc.total_encaisse += c.total_encaisse;
          acc.reste_a_recouvrer += c.reste_a_recouvrer;
          return acc;
        }, {
          effectif: 0,
          total_inscription_prevu: 0,
          total_tranche1_prevu: 0,
          total_tranche2_prevu: 0,
          total_tranche3_prevu: 0,
          total_scolarite_prevu: 0,
          total_annexes_prevu: 0,
          total_annuel_prevu: 0,
          total_encaisse: 0,
          reste_a_recouvrer: 0,
          taux_recouvrement: 0
        });
      };

      const matClasses = processedClasses.filter(c => c.cycle === 'maternelle');
      const primClasses = processedClasses.filter(c => c.cycle === 'primaire');
      const matPrimClasses = processedClasses.filter(c => c.cycle === 'maternelle' || c.cycle === 'primaire');
      const secClasses = processedClasses.filter(c => c.cycle === 'secondaire');

      const matTotal = computeSubtotal(matClasses);
      matTotal.taux_recouvrement = matTotal.total_annuel_prevu > 0 ? Math.round((matTotal.total_encaisse / matTotal.total_annuel_prevu) * 100) : 0;

      const primTotal = computeSubtotal(primClasses);
      primTotal.taux_recouvrement = primTotal.total_annuel_prevu > 0 ? Math.round((primTotal.total_encaisse / primTotal.total_annuel_prevu) * 100) : 0;

      const matPrimTotal = computeSubtotal(matPrimClasses);
      matPrimTotal.taux_recouvrement = matPrimTotal.total_annuel_prevu > 0 ? Math.round((matPrimTotal.total_encaisse / matPrimTotal.total_annuel_prevu) * 100) : 0;

      const secTotal = computeSubtotal(secClasses);
      secTotal.taux_recouvrement = secTotal.total_annuel_prevu > 0 ? Math.round((secTotal.total_encaisse / secTotal.total_annuel_prevu) * 100) : 0;

      const ensembleTotal = computeSubtotal(processedClasses);
      ensembleTotal.taux_recouvrement = ensembleTotal.total_annuel_prevu > 0 ? Math.round((ensembleTotal.total_encaisse / ensembleTotal.total_annuel_prevu) * 100) : 0;

      res.json({
        success: true,
        yearId,
        classes: processedClasses,
        synthese: {
          maternelle: matTotal,
          primaire: primTotal,
          maternelle_primaire: matPrimTotal,
          secondaire: secTotal,
          ensemble: ensembleTotal
        }
      });
    } catch (error: any) {
      console.error("Error in /api/finances/previsions-recettes:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Mise à jour rapide des tranches et frais d'une classe
  app.put("/api/finances/classes/:id/frais", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId;
      const classId = req.params.id;
      const { 
        frais_scolarite, 
        frais_inscription, 
        tranche1_montant, 
        tranche1_date_limite, 
        tranche2_montant, 
        tranche2_date_limite, 
        tranche3_montant, 
        tranche3_date_limite, 
        frais_annexes,
        cycle
      } = req.body;

      db.prepare(`
        UPDATE classes SET 
          frais_scolarite = COALESCE(?, frais_scolarite),
          frais_inscription = COALESCE(?, frais_inscription),
          tranche1_montant = COALESCE(?, tranche1_montant),
          tranche1_date_limite = COALESCE(?, tranche1_date_limite),
          tranche2_montant = COALESCE(?, tranche2_montant),
          tranche2_date_limite = COALESCE(?, tranche2_date_limite),
          tranche3_montant = COALESCE(?, tranche3_montant),
          tranche3_date_limite = COALESCE(?, tranche3_date_limite),
          frais_annexes = COALESCE(?, frais_annexes),
          cycle = COALESCE(?, cycle)
        WHERE id = ? AND (school_id = ? OR school_id IS NULL)
      `).run(
        frais_scolarite !== undefined ? Number(frais_scolarite) : null,
        frais_inscription !== undefined ? Number(frais_inscription) : null,
        tranche1_montant !== undefined ? Number(tranche1_montant) : null,
        tranche1_date_limite !== undefined ? tranche1_date_limite : null,
        tranche2_montant !== undefined ? Number(tranche2_montant) : null,
        tranche2_date_limite !== undefined ? tranche2_date_limite : null,
        tranche3_montant !== undefined ? Number(tranche3_montant) : null,
        tranche3_date_limite !== undefined ? tranche3_date_limite : null,
        frais_annexes !== undefined ? Number(frais_annexes) : null,
        cycle || null,
        classId,
        schoolId
      );

      res.json({ success: true, message: "Paramètres tarifaires de la classe mis à jour !" });
    } catch (error: any) {
      console.error("Error in /api/finances/classes/:id/frais:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Unified Chronological Financial Ledger / Grand Livre des Flux
  app.get("/api/finances/journal", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId;
      const { annee_id, cycle, startDate, endDate, direction, source, search } = req.query;
      const yearId = annee_id || getActiveYearId(schoolId);

      const stream: any[] = [];

      // 1. Inflows from student tuitions (paiements)
      if (!direction || direction === 'ALL' || direction === 'IN') {
        if (!source || source === 'ALL' || source === 'scolarite') {
          let q = `
            SELECT p.*, e.nom as eleve_nom, e.prenom as eleve_prenom, e.matricule, c.nom as classe_nom, c.cycle as classe_cycle
            FROM paiements p
            JOIN eleves e ON p.eleve_id = e.id
            LEFT JOIN classes c ON e.classe_id = c.id
            WHERE p.school_id = ?
          `;
          const pms: any[] = [schoolId];
          if (yearId) {
            q += ` AND p.annee_id = ?`;
            pms.push(yearId);
          }
          if (cycle && cycle !== 'all') {
            q += ` AND c.cycle = ?`;
            pms.push(cycle);
          }
          if (startDate) {
            q += ` AND p.date_paiement >= ?`;
            pms.push(startDate);
          }
          if (endDate) {
            q += ` AND p.date_paiement <= ?`;
            pms.push(endDate);
          }
          const paiements = db.prepare(q).all(...pms) as any[];
          paiements.forEach(p => {
            stream.push({
              id: `scol-${p.id}`,
              original_id: p.id,
              date: p.date_paiement,
              direction: 'IN',
              type_source: 'scolarite',
              nature: 'Encaissement Scolarité',
              categorie: p.type_paiement || 'Frais de scolarité',
              montant: parseFloat(p.montant) || 0,
              libelle: `Scolarité: ${p.eleve_nom} ${p.eleve_prenom} (${p.classe_nom || 'Classe non assignée'})`,
              tiers: `${p.eleve_nom} ${p.eleve_prenom} [${p.matricule || 'N/A'}]`,
              methode: p.methode || 'Espèces',
              reference: p.reference_transaction || `REÇU #${p.id}`,
              statut: p.status || 'Terminé',
              cycle: p.classe_cycle || 'all',
              description: `Paiement scolarité de ${p.eleve_nom} ${p.eleve_prenom}`
            });
          });
        }

        // 2. Inflows from other revenues
        if (!source || source === 'ALL' || source === 'autre_recette') {
          let q = `SELECT * FROM autres_recettes WHERE school_id = ? AND statut != 'Annulé'`;
          const pms: any[] = [schoolId];
          if (yearId) {
            q += ` AND annee_id = ?`;
            pms.push(yearId);
          }
          if (cycle && cycle !== 'all') {
            q += ` AND (cycle = ? OR cycle = 'all')`;
            pms.push(cycle);
          }
          if (startDate) {
            q += ` AND date_recette >= ?`;
            pms.push(startDate);
          }
          if (endDate) {
            q += ` AND date_recette <= ?`;
            pms.push(endDate);
          }
          const autresRec = db.prepare(q).all(...pms) as any[];
          autresRec.forEach(r => {
            stream.push({
              id: `rec-${r.id}`,
              original_id: r.id,
              date: r.date_recette,
              direction: 'IN',
              type_source: 'autre_recette',
              nature: 'Autre Recette',
              categorie: r.categorie || 'Recette diverse',
              montant: parseFloat(r.montant) || 0,
              libelle: r.titre,
              tiers: r.source || 'Donateur / Payeur externe',
              methode: r.methode || 'Espèces',
              reference: r.reference_piece || `OP-REC-${r.id}`,
              statut: r.statut || 'Encaissé',
              cycle: r.cycle || 'all',
              description: r.description || ''
            });
          });
        }
      }

      // 3. Outflows: Teacher salaries
      if (!direction || direction === 'ALL' || direction === 'OUT') {
        if (!source || source === 'ALL' || source === 'salaire_enseignant') {
          let q = `
            SELECT p.*, e.nom, e.prenom, e.matricule, e.cycle as prof_cycle
            FROM enseignant_paiements_mensuels p
            JOIN enseignants e ON p.enseignant_id = e.id
            WHERE p.school_id = ? AND (p.montant_paye > 0 OR p.montant > 0)
          `;
          const pms: any[] = [schoolId];
          if (yearId) {
            q += ` AND p.annee_id = ?`;
            pms.push(yearId);
          }
          if (cycle && cycle !== 'all') {
            q += ` AND (p.type_cycle = ? OR e.cycle = ?)`;
            pms.push(cycle, cycle);
          }
          if (startDate) {
            q += ` AND p.date_paiement >= ?`;
            pms.push(startDate);
          }
          if (endDate) {
            q += ` AND p.date_paiement <= ?`;
            pms.push(endDate);
          }
          const profSalaires = db.prepare(q).all(...pms) as any[];
          profSalaires.forEach(p => {
            const paye = parseFloat(p.montant_paye) || 0;
            if (paye > 0) {
              stream.push({
                id: `ens-${p.id}`,
                original_id: p.id,
                date: p.date_paiement || new Date().toISOString().split('T')[0],
                direction: 'OUT',
                type_source: 'salaire_enseignant',
                nature: 'Salaire Enseignant',
                categorie: 'Rémunération Pédagogique',
                montant: paye,
                libelle: `Paie Enseignant (${p.mois}): ${p.nom} ${p.prenom}`,
                tiers: `Prof. ${p.nom} ${p.prenom}`,
                methode: p.methode || 'Espèces',
                reference: `BULLETIN-${p.id}`,
                statut: p.statut || 'Payé',
                cycle: p.type_cycle || p.prof_cycle || 'all',
                description: p.commentaires || `Salaire du mois de ${p.mois} (Total dû: ${p.montant} FCFA)`
              });
            }
          });
        }

        // 4. Outflows: Staff salaries
        if (!source || source === 'ALL' || source === 'salaire_personnel') {
          let q = `
            SELECT p.*, pa.nom, pa.prenom, pa.poste
            FROM personnel_paiements p
            JOIN personnel_administratif pa ON p.personnel_id = pa.id
            WHERE p.school_id = ? AND (p.montant_paye > 0 OR p.net_a_payer > 0)
          `;
          const pms: any[] = [schoolId];
          if (yearId) {
            q += ` AND p.annee_id = ?`;
            pms.push(yearId);
          }
          if (startDate) {
            q += ` AND p.date_paiement >= ?`;
            pms.push(startDate);
          }
          if (endDate) {
            q += ` AND p.date_paiement <= ?`;
            pms.push(endDate);
          }
          const staffSalaires = db.prepare(q).all(...pms) as any[];
          staffSalaires.forEach(p => {
            const paye = parseFloat(p.montant_paye) || 0;
            if (paye > 0) {
              stream.push({
                id: `pers-${p.id}`,
                original_id: p.id,
                date: p.date_paiement || new Date().toISOString().split('T')[0],
                direction: 'OUT',
                type_source: 'salaire_personnel',
                nature: 'Salaire Personnel Admin',
                categorie: 'Rémunération Administrative',
                montant: paye,
                libelle: `Paie Personnel (${p.mois}): ${p.nom} ${p.prenom} (${p.poste || 'Administration'})`,
                tiers: `${p.nom} ${p.prenom} [${p.poste || 'Personnel'}]`,
                methode: p.methode || 'Espèces',
                reference: `PAIE-ADM-${p.id}`,
                statut: p.statut || 'Payé',
                cycle: 'all',
                description: p.commentaires || `Salaire mois de ${p.mois} (Net: ${p.net_a_payer} FCFA)`
              });
            }
          });
        }

        // 5. Outflows: Other School Expenses
        if (!source || source === 'ALL' || source === 'depense') {
          let q = `SELECT * FROM depenses WHERE school_id = ? AND statut != 'Annulé'`;
          const pms: any[] = [schoolId];
          if (yearId) {
            q += ` AND annee_id = ?`;
            pms.push(yearId);
          }
          if (cycle && cycle !== 'all') {
            q += ` AND (cycle = ? OR cycle = 'all')`;
            pms.push(cycle);
          }
          if (startDate) {
            q += ` AND date_depense >= ?`;
            pms.push(startDate);
          }
          if (endDate) {
            q += ` AND date_depense <= ?`;
            pms.push(endDate);
          }
          const depenses = db.prepare(q).all(...pms) as any[];
          depenses.forEach(d => {
            stream.push({
              id: `dep-${d.id}`,
              original_id: d.id,
              date: d.date_depense,
              direction: 'OUT',
              type_source: 'depense',
              nature: 'Dépense d\'Établissement',
              categorie: d.categorie || 'Charges d\'exploitation',
              montant: parseFloat(d.montant) || 0,
              libelle: d.titre,
              tiers: d.beneficiaire || 'Prestataire / Fournisseur',
              methode: d.methode || 'Espèces',
              reference: d.reference_piece || `DEP-${d.id}`,
              statut: d.statut || 'Payé',
              cycle: d.cycle || 'all',
              description: d.description || ''
            });
          });
        }
      }

      // Sort by date DESC
      stream.sort((a, b) => {
        const da = a.date || '';
        const db = b.date || '';
        return db.localeCompare(da);
      });

      // Search filter if supplied
      let filtered = stream;
      if (search && typeof search === 'string' && search.trim() !== '') {
        const s = search.toLowerCase().trim();
        filtered = stream.filter(item =>
          (item.libelle && item.libelle.toLowerCase().includes(s)) ||
          (item.tiers && item.tiers.toLowerCase().includes(s)) ||
          (item.reference && item.reference.toLowerCase().includes(s)) ||
          (item.categorie && item.categorie.toLowerCase().includes(s)) ||
          (item.description && item.description.toLowerCase().includes(s))
        );
      }

      res.json(filtered);
    } catch (error: any) {
      console.error("Error in /api/finances/journal:", error);
      res.status(500).json({ error: error.message });
    }
  });

