  // Bulk assign subjects to one or multiple classes in one click (Secondaire & Primaire)
  app.post("/api/matieres/assign-to-classes", authenticateToken, (req: any, res) => {
    const { classe_ids, matiere_ids, assignments, replace_existing, include_sub_subjects, options } = req.body;
    
    if (!classe_ids || !Array.isArray(classe_ids) || classe_ids.length === 0) {
      return res.status(400).json({ error: "Veuillez sélectionner au moins une classe cible." });
    }

    // Support either assignments array or direct matiere_ids array
    let resolvedAssignments: Array<{ matiere_id: number, coefficient?: number, heures_hebdo?: number, enseignant_id?: number | null }> = [];

    if (Array.isArray(assignments) && assignments.length > 0) {
      resolvedAssignments = [...assignments];
    } else if (Array.isArray(matiere_ids) && matiere_ids.length > 0) {
      // Fetch coefficients and metadata for these subjects
      const placeholders = matiere_ids.map(() => '?').join(',');
      const subjects = db.prepare(`SELECT id, coefficient, heures_hebdo, parent_id FROM matieres WHERE id IN (${placeholders}) AND school_id = ?`).all(...matiere_ids, req.schoolId) as any[];
      
      const subjectMap = new Map<number, any>();
      subjects.forEach(s => subjectMap.set(s.id, s));

      for (const mId of matiere_ids) {
        const sub = subjectMap.get(mId);
        resolvedAssignments.push({
          matiere_id: mId,
          coefficient: sub?.coefficient || 1,
          heures_hebdo: sub?.heures_hebdo || 0,
          enseignant_id: null
        });
      }

      // If include_sub_subjects is true (default true), also add all sub-subjects of the selected parents!
      if (include_sub_subjects !== false) {
        const subSubjects = db.prepare(`
          SELECT id, coefficient, heures_hebdo, parent_id 
          FROM matieres 
          WHERE parent_id IN (${placeholders}) AND school_id = ?
        `).all(...matiere_ids, req.schoolId) as any[];

        for (const sub of subSubjects) {
          if (!resolvedAssignments.some(a => a.matiere_id === sub.id)) {
            resolvedAssignments.push({
              matiere_id: sub.id,
              coefficient: sub.coefficient || 1,
              heures_hebdo: sub.heures_hebdo || 0,
              enseignant_id: null
            });
          }
        }
      }
    } else {
      return res.status(400).json({ error: "Veuillez sélectionner au moins une matière à assigner." });
    }

    const preserveTeachers = options?.preserve_existing_teachers !== false;
    const overwriteCoefs = options?.overwrite_coefficients !== false;

    try {
      const checkStmt = db.prepare("SELECT * FROM classe_matieres WHERE classe_id = ? AND matiere_id = ? AND (school_id = ? OR school_id IS NULL)");
      const insertStmt = db.prepare(`
        INSERT INTO classe_matieres (classe_id, matiere_id, enseignant_id, heures_hebdo, coefficient, school_id)
        VALUES (?, ?, ?, ?, ?, ?)
      `);
      const updateStmt = db.prepare(`
        UPDATE classe_matieres 
        SET coefficient = ?, heures_hebdo = ?, enseignant_id = CASE WHEN ? IS NOT NULL THEN ? ELSE enseignant_id END
        WHERE classe_id = ? AND matiere_id = ? AND (school_id = ? OR school_id IS NULL)
      `);
      const deleteExistingStmt = db.prepare("DELETE FROM classe_matieres WHERE classe_id = ? AND (school_id = ? OR school_id IS NULL)");

      let totalCreated = 0;
      let totalUpdated = 0;

      const runBatch = db.transaction(() => {
        for (const classeId of classe_ids) {
          if (replace_existing === true) {
            deleteExistingStmt.run(classeId, req.schoolId);
          }

          for (const a of resolvedAssignments) {
            const matiereId = a.matiere_id;
            const coef = a.coefficient !== undefined ? a.coefficient : 1;
            const heures = a.heures_hebdo !== undefined ? a.heures_hebdo : 0;
            const teacherId = a.enseignant_id || null;

            const existing = replace_existing ? null : checkStmt.get(classeId, matiereId, req.schoolId) as any;
            if (existing) {
              const targetTeacher = preserveTeachers ? (teacherId || null) : teacherId;
              const targetCoef = overwriteCoefs ? coef : existing.coefficient;
              updateStmt.run(targetCoef, heures, targetTeacher, targetTeacher, classeId, matiereId, req.schoolId);
              totalUpdated++;
            } else {
              insertStmt.run(classeId, matiereId, teacherId, heures, coef, req.schoolId);
              totalCreated++;
            }
          }
        }
      });

      runBatch();

      // Fetch the updated classes names for recap
      const classesNames = db.prepare(`
        SELECT nom FROM classes WHERE id IN (${classe_ids.map(() => '?').join(',')})
      `).all(...classe_ids).map((c: any) => c.nom);

      res.json({
        success: true,
        message: `Matières assignées avec succès à ${classe_ids.length} classe(s) (${classesNames.join(', ')})`,
        classesCount: classe_ids.length,
        matieresCount: resolvedAssignments.length,
        classes_count: classe_ids.length,
        classes_names: classesNames,
        created_count: totalCreated,
        updated_count: totalUpdated
      });
    } catch (error: any) {
      console.error("Error in /api/matieres/assign-to-classes:", error);
      res.status(500).json({ error: error.message || "Erreur lors de l'assignation des matières" });
    }
  });

