    app.post("/api/matieres", authenticateToken, (req: any, res) => {
    try {
      const { nom, code, sigle, categorie, coefficient, parent_id, description, cycle, color, est_disciplinaire, heures_hebdo } = req.body;
      
      if (!nom || !nom.trim()) {
        return res.status(400).json({ error: "Le nom de la matière est obligatoire." });
      }

      const existingSubjects = db.prepare("SELECT id, nom, code, sigle, categorie, coefficient, cycle, parent_id FROM matieres WHERE school_id = ?").all(req.schoolId) as any[];
      const targetCycle = cycle || 'secondaire';

      // Duplicate prevention with cycle and parent_id awareness
      const dupCheck = checkSubjectDuplicate({ nom: nom.trim(), code, sigle, cycle: targetCycle, categorie, parent_id }, existingSubjects, null, targetCycle);
      if (dupCheck.isDuplicate) {
        return res.status(400).json({ 
          error: dupCheck.reason || "Une matière similaire existe déjà dans votre établissement.",
          isDuplicate: true,
          matchedSubject: dupCheck.matchedSubject
        });
      }

      // Auto-extract sigle and generate unique ID / code
      const resolvedSigle = extractOrGenerateSigle(nom, sigle, targetCycle);
      const resolvedCode = code && code.trim() ? code.trim().toUpperCase() : generateSubjectCode(nom, resolvedSigle, existingSubjects);
      const resolvedCategorie = categorie && categorie.trim() ? categorie.trim() : (dupCheck.standardCatalogMatch?.categorie || (targetCycle === 'primaire' ? 'Langage, Lecture & Français (Primaire)' : 'Sciences & Technologies'));
      const resolvedCoef = Number(coefficient) > 0 ? Number(coefficient) : (dupCheck.standardCatalogMatch?.coefficient || 1);
      const resolvedCycle = cycle || (dupCheck.standardCatalogMatch?.cycle || (targetCycle === 'primaire' ? 'primaire' : 'secondaire'));
      const resolvedColor = color || dupCheck.standardCatalogMatch?.color || null;
      const resolvedDescription = description || dupCheck.standardCatalogMatch?.description || null;
      const resolvedDisciplinaire = est_disciplinaire ? 1 : 0;
      const resolvedHeuresHebdo = Number(heures_hebdo) >= 0 ? Number(heures_hebdo) : 0;

      const result = db.prepare(`
        INSERT INTO matieres (nom, code, sigle, categorie, coefficient, parent_id, school_id, description, cycle, color, est_disciplinaire, heures_hebdo) 
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        nom.trim(), 
        resolvedCode, 
        resolvedSigle, 
        resolvedCategorie, 
        resolvedCoef, 
        parent_id || null, 
        req.schoolId,
        resolvedDescription,
        resolvedCycle,
        resolvedColor,
        resolvedDisciplinaire,
        resolvedHeuresHebdo
      );

      res.json({ 
        id: result.lastInsertRowid, 
        code: resolvedCode, 
        sigle: resolvedSigle, 
        nom: nom.trim(),
        categorie: resolvedCategorie,
        coefficient: resolvedCoef,
        parent_id: parent_id || null,
        cycle: resolvedCycle,
        est_disciplinaire: resolvedDisciplinaire === 1,
        heures_hebdo: resolvedHeuresHebdo
      });
    } catch (error: any) {
      console.error("Create subject error:", error);
      res.status(500).json({ error: error.message || "Erreur lors de la création de la matière." });
    }
  });

  app.post("/api/matieres/default-pack", authenticateToken, (req: any, res) => {
    const { matieresList, clearExisting, cycle } = req.body;
    const targetCycle = cycle === 'primaire' ? 'primaire' : (cycle === 'secondaire' ? 'secondaire' : 'all');
    
    // Use standardized catalog if no specific list provided
    const sourceList = Array.isArray(matieresList) && matieresList.length > 0 
      ? matieresList 
      : getCatalogByCycle(targetCycle);

    let addedCount = 0;
    const insertStmt = db.prepare(`
      INSERT INTO matieres (nom, code, sigle, categorie, coefficient, parent_id, school_id, description, cycle, color, est_disciplinaire) 
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);
    
    try {
      db.transaction(() => {
        // If clearExisting is requested
        if (clearExisting) {
          const isPrimaire = targetCycle === 'primaire';
          const filterSql = isPrimaire
            ? "WHERE school_id = ? AND (cycle = 'primaire' OR categorie LIKE '%primaire%' OR categorie LIKE '%maternelle%')"
            : targetCycle === 'secondaire'
            ? "WHERE school_id = ? AND (cycle = 'secondaire' OR cycle = 'technique' OR (categorie NOT LIKE '%primaire%' AND categorie NOT LIKE '%maternelle%'))"
            : "WHERE school_id = ?";

          const subjectsToDelete = db.prepare(`SELECT id FROM matieres ${filterSql}`).all(req.schoolId) as { id: number }[];
          for (const s of subjectsToDelete) {
            db.prepare("DELETE FROM classe_matieres WHERE matiere_id = ?").run(s.id);
            db.prepare("DELETE FROM notes WHERE matiere_id = ?").run(s.id);
            db.prepare("DELETE FROM emplois_du_temps WHERE matiere_id = ?").run(s.id);
            db.prepare("DELETE FROM devoirs WHERE matiere_id = ?").run(s.id);
            db.prepare("DELETE FROM enseignant_matieres WHERE matiere_id = ?").run(s.id);
            db.prepare("UPDATE matieres SET parent_id = NULL WHERE parent_id = ?").run(s.id);
            db.prepare("DELETE FROM matieres WHERE id = ? AND school_id = ?").run(s.id, req.schoolId);
          }
        }

        let currentSubjects = db.prepare("SELECT id, nom, code, sigle, categorie, coefficient, cycle FROM matieres WHERE school_id = ?").all(req.schoolId) as any[];

        for (const m of sourceList) {
          if (!m || !m.nom) continue;
          const subjCycle = m.cycle || (targetCycle !== 'all' ? targetCycle : 'secondaire');
          
          // Check duplicate before inserting
          const dup = checkSubjectDuplicate({ nom: m.nom, code: m.code, sigle: m.sigle, cycle: subjCycle, categorie: m.categorie }, currentSubjects, null, targetCycle);
          if (!dup.isDuplicate) {
            const sigle = extractOrGenerateSigle(m.nom, m.sigle, targetCycle);
            const code = generateSubjectCode(m.nom, sigle, currentSubjects);
            const categorie = m.categorie || (subjCycle === 'primaire' ? 'Langage, Lecture & Français (Primaire)' : 'Sciences & Technologies');
            const coefficient = Number(m.coefficient) || 1;
            const desc = m.description || null;
            const color = m.color || null;

            const resInsert = insertStmt.run(
              m.nom.trim(), 
              code, 
              sigle, 
              categorie, 
              coefficient, 
              m.parent_id || null, 
              req.schoolId,
              desc,
              subjCycle,
              color,
              m.est_disciplinaire ? 1 : 0
            );

            currentSubjects.push({
              id: resInsert.lastInsertRowid,
              nom: m.nom.trim(),
              code,
              sigle,
              categorie,
              coefficient,
              cycle: subjCycle
            });
            addedCount++;
          }
        }
      })();

      res.json({ success: true, count: addedCount });
    } catch (error: any) {
      console.error("Default pack error:", error);
      res.status(500).json({ error: error.message });
    }
  });

