  app.put("/api/matieres/:id", authenticateToken, (req: any, res) => {
    try {
      const { id } = req.params;
      const { nom, code, sigle, categorie, coefficient, parent_id, description, cycle, color, est_disciplinaire, heures_hebdo } = req.body;
      
      if (!nom || !nom.trim()) {
        return res.status(400).json({ error: "Le nom de la matière est obligatoire." });
      }

      const currentSubject = db.prepare("SELECT * FROM matieres WHERE id = ? AND school_id = ?").get(id, req.schoolId) as any;
      const resolvedParentId = parent_id !== undefined
        ? (parent_id !== null && parent_id !== '' ? Number(parent_id) : null)
        : (currentSubject ? currentSubject.parent_id : null);
      const existingSubjects = db.prepare("SELECT id, nom, code, sigle, categorie, coefficient, cycle, parent_id FROM matieres WHERE school_id = ? AND id != ?").all(req.schoolId, id) as any[];
      const targetCycle = resolvedParentId ? 'secondaire' : (cycle || (currentSubject?.cycle || 'secondaire'));
      
      // Duplicate prevention (excluding current subject id)
      const dupCheck = checkSubjectDuplicate({ 
        nom: nom.trim(), 
        code, 
        sigle, 
        id: Number(id), 
        cycle: targetCycle, 
        categorie, 
        parent_id: resolvedParentId 
      }, existingSubjects, Number(id), targetCycle);

      if (dupCheck.isDuplicate) {
        return res.status(400).json({ 
          error: dupCheck.reason || "Une autre matière similaire existe déjà dans votre établissement.",
          isDuplicate: true,
          matchedSubject: dupCheck.matchedSubject
        });
      }

      const resolvedSigle = extractOrGenerateSigle(nom, sigle, targetCycle);
      const resolvedCode = code && code.trim() ? code.trim().toUpperCase() : generateSubjectCode(nom, resolvedSigle, existingSubjects, Number(id));
      const resolvedDisciplinaire = est_disciplinaire !== undefined ? (est_disciplinaire ? 1 : 0) : (currentSubject?.est_disciplinaire || 0);
      const resolvedHeuresHebdo = heures_hebdo !== undefined 
        ? (Number(heures_hebdo) >= 0 ? Number(heures_hebdo) : 0) 
        : (currentSubject?.heures_hebdo || 0);

      db.prepare(`
        UPDATE matieres 
        SET nom = ?, code = ?, sigle = ?, categorie = ?, coefficient = ?, parent_id = ?, description = ?, cycle = ?, color = ?, est_disciplinaire = ?, heures_hebdo = ?
        WHERE id = ? AND school_id = ?
      `).run(
        nom.trim(), 
        resolvedCode, 
        resolvedSigle, 
        categorie || (resolvedParentId ? 'Lettres & Langues' : 'Sciences & Technologies'), 
        Number(coefficient) > 0 ? Number(coefficient) : 1, 
        resolvedParentId, 
        description || null,
        targetCycle,
        color || null,
        resolvedDisciplinaire,
        resolvedHeuresHebdo,
        id, 
        req.schoolId
      );

      res.json({ 
        success: true, 
        id: Number(id),
        code: resolvedCode, 
        sigle: resolvedSigle,
        parent_id: resolvedParentId,
        cycle: targetCycle,
        est_disciplinaire: resolvedDisciplinaire === 1,
        heures_hebdo: resolvedHeuresHebdo
      });
    } catch (error: any) {
      console.error("Update subject error:", error);
      res.status(500).json({ error: error.message || "Erreur lors de la mise à jour." });
    }
  });


  app.delete("/api/matieres/:id", authenticateToken, (req: any, res) => {
    const { id } = req.params;
    
    try {
      db.transaction(() => {
        // Delete related records first to avoid foreign key constraint failures
        db.prepare("DELETE FROM classe_matieres WHERE matiere_id = ?").run(id);
        db.prepare("DELETE FROM notes WHERE matiere_id = ?").run(id);
        db.prepare("DELETE FROM emplois_du_temps WHERE matiere_id = ?").run(id);
        db.prepare("DELETE FROM devoirs WHERE matiere_id = ?").run(id);
        db.prepare("DELETE FROM enseignant_matieres WHERE matiere_id = ?").run(id);
        
        // Also handle child subjects
        db.prepare("UPDATE matieres SET parent_id = NULL WHERE parent_id = ?").run(id);

        db.prepare("DELETE FROM matieres WHERE id = ? AND school_id = ?").run(id, req.schoolId);
      })();
      res.json({ success: true });
    } catch (error: any) {
      console.error("Delete subject error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Assigner des matières à une ou plusieurs classes en un clic (Secondaire & tous cycles)
  app.post("/api/matieres/assign-to-classes", authenticateToken, (req: any, res) => {
    try {
      const { classe_ids, matiere_ids, assignments, replace_existing, include_sub_subjects = true } = req.body;
      
      if (!Array.isArray(classe_ids) || classe_ids.length === 0) {
        return res.status(400).json({ error: "Veuillez sélectionner au moins une classe cible." });
      }
      if (!Array.isArray(matiere_ids) || matiere_ids.length === 0) {
        return res.status(400).json({ error: "Veuillez sélectionner au moins une matière à assigner." });
      }

      const allSubjects = db.prepare("SELECT * FROM matieres WHERE school_id = ? OR school_id IS NULL").all(req.schoolId) as any[];
      const subjectsMap = new Map<number, any>(allSubjects.map(s => [Number(s.id), s]));

      // Resolve all target subjects including child sub-subjects if requested
      const targetMatiereIds = new Set<number>();
      for (const mId of matiere_ids) {
        const numId = Number(mId);
        targetMatiereIds.add(numId);
        if (include_sub_subjects) {
          const children = allSubjects.filter(s => Number(s.parent_id) === numId);
          for (const c of children) {
            targetMatiereIds.add(Number(c.id));
          }
        }
      }

      const stmtInsert = db.prepare(`
        INSERT OR REPLACE INTO classe_matieres (classe_id, matiere_id, enseignant_id, heures_hebdo, coefficient, school_id)
        VALUES (?, ?, ?, ?, ?, ?)
      `);

      let totalAssigned = 0;

      db.transaction(() => {
        for (const classId of classe_ids) {
          if (replace_existing) {
            db.prepare("DELETE FROM classe_matieres WHERE classe_id = ? AND (school_id = ? OR school_id IS NULL)").run(classId, req.schoolId);
          }

          for (const mId of targetMatiereIds) {
            const subj = subjectsMap.get(mId);
            if (!subj) continue;

            const custom = assignments && assignments[mId] ? assignments[mId] : {};
            const coeff = custom.coefficient !== undefined && custom.coefficient !== null && Number(custom.coefficient) > 0 
              ? Number(custom.coefficient) 
              : (subj.coefficient || 1);
            const heures = custom.heures_hebdo !== undefined && custom.heures_hebdo !== null 
              ? Number(custom.heures_hebdo) 
              : (subj.heures_hebdo || 0);
            const enseignantId = custom.enseignant_id || null;

            stmtInsert.run(classId, mId, enseignantId, heures, coeff, req.schoolId);
            totalAssigned++;
          }
        }
      })();

      res.json({ 
        success: true, 
        classesCount: classe_ids.length, 
        matieresCount: targetMatiereIds.size, 
        totalAssignments: totalAssigned 
      });
    } catch (e: any) {
      console.error("Assign subjects to classes error:", e);
      res.status(500).json({ error: e.message || "Erreur lors de l'assignation des matières" });
    }
  });

