  app.get("/api/teacher-classes", authenticateToken, (req: any, res) => {
    let teacherId = req.user?.enseignant_id;
    if (!teacherId) {
      const userWithEns = db.prepare("SELECT enseignant_id FROM utilisateurs WHERE id = ?").get(req.userId) as any;
      if (userWithEns?.enseignant_id) teacherId = userWithEns.enseignant_id;
    }
    if (!teacherId) return res.json([]);
    
    const yearId = req.anneeId;
    const teacherClasses = db.prepare(`
      SELECT DISTINCT c.* 
      FROM classes c
      LEFT JOIN classe_matieres cm ON c.id = cm.classe_id
      WHERE (c.enseignant_id = ? OR c.professeur_principal_id = ? OR cm.enseignant_id = ?) 
        AND c.school_id = ?
        ${yearId ? `AND c.annee_id = ${yearId}` : ''}
      ORDER BY c.nom
    `).all(teacherId, teacherId, teacherId, req.schoolId);

    res.json(teacherClasses);
  });

  app.post("/api/emplois", authenticateToken, (req: any, res) => {
    const { classe_id, jour, heure_debut, heure_fin, matiere_id, salle_id, enseignant_id } = req.body;
    const staffRoles = ['super_admin', 'admin', 'direction', 'censeur', 'secretariat', 'secretaire'];
    
    const dbUser = db.prepare("SELECT role, permissions, enseignant_id FROM utilisateurs WHERE id = ?").get(req.userId) as any;
    let userPerms: any[] = [];
    try {
      if (dbUser?.permissions) userPerms = typeof dbUser.permissions === 'string' ? JSON.parse(dbUser.permissions) : dbUser.permissions;
    } catch (e) {}

    const isStaff = staffRoles.includes(req.user?.role) || 
      (Array.isArray(userPerms) && userPerms.some((p: any) => 
        (p === '/emplois-du-temps' || p.path === '/emplois-du-temps') && (p.access_type === 'read_write' || p.can_write)
      ));
    
    let teacherId = req.user?.enseignant_id || dbUser?.enseignant_id;

    if (!isStaff && req.user?.role === 'enseignant') {
      if (!teacherId) return res.status(403).json({ error: "Compte enseignant non rattaché." });

      // Check if teacher has an approved request for this class, day, and time window
      const approved = db.prepare(`
        SELECT * FROM timetable_requests 
        WHERE enseignant_id = ? 
          AND status = 'approved' 
          AND type_modification = 'emploi_du_temps'
          AND (classe_id IS NULL OR classe_id = ?) 
          AND (jour IS NULL OR jour = '' OR jour = ?)
          AND school_id = ?
      `).get(teacherId, classe_id, jour, req.schoolId) as any;

      if (!approved) {
        return res.status(403).json({ error: "Vous n'avez pas d'autorisation approuvée pour programmer un cours dans cette classe." });
      }

      // Check if the subject is assigned to this teacher, primary class, or approved in a timetable request
      const teacherTaught = db.prepare(`
        SELECT 1 FROM classe_matieres WHERE classe_id = ? AND matiere_id = ? AND (enseignant_id = ? OR enseignant_id IS NULL) AND school_id = ?
        UNION
        SELECT 1 FROM enseignant_matieres WHERE enseignant_id = ? AND matiere_id = ? AND school_id = ?
        UNION
        SELECT 1 FROM classes WHERE (enseignant_id = ? OR professeur_principal_id = ?) AND id = ? AND school_id = ?
        UNION
        SELECT 1 FROM timetable_requests WHERE enseignant_id = ? AND status = 'approved' AND (classe_id IS NULL OR classe_id = ?) AND (matiere_id IS NULL OR matiere_id = ?) AND school_id = ?
      `).get(classe_id, matiere_id, teacherId, req.schoolId, teacherId, matiere_id, req.schoolId, teacherId, teacherId, classe_id, req.schoolId, teacherId, classe_id, matiere_id, req.schoolId);

      if (!teacherTaught) {
        return res.status(403).json({ error: "Vous ne pouvez programmer que vos propres matières d'enseignement ou celles autorisées." });
      }
    }

    // Automatic association: Check if subject is already in classe_matieres
    const association = db.prepare("SELECT * FROM classe_matieres WHERE classe_id = ? AND matiere_id = ? AND school_id = ?")
      .get(classe_id, matiere_id, req.schoolId) as any;
    
    if (!association) {
      db.prepare("INSERT INTO classe_matieres (classe_id, matiere_id, coefficient, heures_hebdo, enseignant_id, school_id) VALUES (?, ?, ?, ?, ?, ?)")
        .run(classe_id, matiere_id, 1, 0, teacherId || null, req.schoolId);
    } else if (!association.enseignant_id && teacherId) {
      db.prepare("UPDATE classe_matieres SET enseignant_id = ? WHERE classe_id = ? AND matiere_id = ? AND school_id = ?")
        .run(teacherId, classe_id, matiere_id, req.schoolId);
    }

    const targetTeacherId = enseignant_id || teacherId || (association ? association.enseignant_id : null);

    if (targetTeacherId) {
      const conflict = db.prepare(`
        SELECT ed.*, c.nom as classe_nom, m.nom as matiere_nom
        FROM emplois_du_temps ed
        JOIN classes c ON ed.classe_id = c.id
        JOIN matieres m ON ed.matiere_id = m.id
        WHERE (ed.enseignant_id = ? OR EXISTS (
          SELECT 1 FROM classe_matieres cm2 
          WHERE cm2.classe_id = ed.classe_id AND cm2.matiere_id = ed.matiere_id AND cm2.enseignant_id = ?
        ))
          AND ed.jour = ? 
          AND ed.school_id = ?
          AND ed.heure_debut < ? 
          AND ? < ed.heure_fin
      `).get(targetTeacherId, targetTeacherId, jour, req.schoolId, heure_fin, heure_debut) as any;

      if (conflict) {
        return res.status(409).json({ 
          error: `Cet enseignant est déjà programmé pour un cours de ${conflict.matiere_nom} en classe de ${conflict.classe_nom} le ${jour} de ${conflict.heure_debut} à ${conflict.heure_fin}.` 
        });
      }
    }

    const result = db.prepare("INSERT INTO emplois_du_temps (classe_id, jour, heure_debut, heure_fin, matiere_id, enseignant_id, salle_id, school_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
      .run(classe_id, jour, heure_debut, heure_fin, matiere_id, targetTeacherId || null, salle_id || null, req.schoolId);
    
    saveCheckpoint();
    res.json({ id: result.lastInsertRowid });
  });

  app.put("/api/emplois/:id", authenticateToken, (req: any, res) => {
    const { id } = req.params;
    const { jour, heure_debut, heure_fin, matiere_id, salle_id, enseignant_id } = req.body;
    const staffRoles = ['super_admin', 'admin', 'direction', 'censeur', 'secretariat', 'secretaire'];
    
    const dbUser = db.prepare("SELECT role, permissions, enseignant_id FROM utilisateurs WHERE id = ?").get(req.userId) as any;
    let userPerms: any[] = [];
    try {
      if (dbUser?.permissions) userPerms = typeof dbUser.permissions === 'string' ? JSON.parse(dbUser.permissions) : dbUser.permissions;
    } catch (e) {}

    const isStaff = staffRoles.includes(req.user?.role) || 
      (Array.isArray(userPerms) && userPerms.some((p: any) => 
        (p === '/emplois-du-temps' || p.path === '/emplois-du-temps') && (p.access_type === 'read_write' || p.can_write)
      ));

    const existing = db.prepare(`
      SELECT ed.*, cm.enseignant_id AS matiere_enseignant_id
      FROM emplois_du_temps ed
      LEFT JOIN classe_matieres cm ON ed.classe_id = cm.classe_id AND ed.matiere_id = cm.matiere_id
      WHERE ed.id = ? AND ed.school_id = ?
    `).get(id, req.schoolId) as any;

    if (!existing) return res.status(404).json({ error: "Créneau introuvable." });

    if (!isStaff && req.user?.role === 'enseignant') {
      const teacherId = req.user?.enseignant_id || dbUser?.enseignant_id;
      if (!teacherId || (existing.enseignant_id && existing.enseignant_id !== teacherId)) {
        return res.status(403).json({ error: "Vous ne pouvez pas modifier les cours d'un autre enseignant." });
      }

      const approved = db.prepare(`
        SELECT * FROM timetable_requests 
        WHERE enseignant_id = ? 
          AND status = 'approved' 
          AND type_modification = 'emploi_du_temps'
          AND (classe_id IS NULL OR classe_id = ?) 
          AND (jour IS NULL OR jour = '' OR jour = ?)
          AND school_id = ?
      `).get(teacherId, existing.classe_id, existing.jour, req.schoolId) as any;

      if (!approved) {
        return res.status(403).json({ error: "Aucune autorisation approuvée pour modifier ce cours." });
      }
    }

    const targetTeacherId = enseignant_id || existing.enseignant_id || existing.matiere_enseignant_id;

    if (targetTeacherId) {
      const conflict = db.prepare(`
        SELECT ed.*, c.nom as classe_nom, m.nom as matiere_nom
        FROM emplois_du_temps ed
        JOIN classes c ON ed.classe_id = c.id
        JOIN matieres m ON ed.matiere_id = m.id
        WHERE (ed.enseignant_id = ? OR EXISTS (
          SELECT 1 FROM classe_matieres cm2 
          WHERE cm2.classe_id = ed.classe_id AND cm2.matiere_id = ed.matiere_id AND cm2.enseignant_id = ?
        ))
          AND ed.jour = ? 
          AND ed.school_id = ?
          AND ed.heure_debut < ? 
          AND ? < ed.heure_fin
          AND ed.id != ?
      `).get(targetTeacherId, targetTeacherId, jour, req.schoolId, heure_fin, heure_debut, id) as any;

      if (conflict) {
        return res.status(409).json({ 
          error: `Cet enseignant est déjà programmé pour un cours de ${conflict.matiere_nom} en classe de ${conflict.classe_nom} le ${jour} de ${conflict.heure_debut} à ${conflict.heure_fin}.` 
        });
      }
    }

    db.prepare(`
      UPDATE emplois_du_temps 
      SET jour = ?, heure_debut = ?, heure_fin = ?, matiere_id = ?, enseignant_id = ?, salle_id = ?
      WHERE id = ? AND school_id = ?
    `).run(jour, heure_debut, heure_fin, matiere_id, enseignant_id || null, salle_id || null, id, req.schoolId);
    saveCheckpoint();
    res.json({ success: true });
  });

