  app.patch("/api/timetable-requests/:id/status", authenticateToken, (req: any, res) => {
    const { id } = req.params;
    const { status, reponse_admin } = req.body;
    const staffRoles = ['super_admin', 'admin', 'direction', 'censeur', 'secretariat', 'secretaire', 'surveillant'];
    
    const dbUser = db.prepare("SELECT role, permissions FROM utilisateurs WHERE id = ?").get(req.userId) as any;
    let userPerms: any[] = [];
    try {
      if (dbUser?.permissions) userPerms = typeof dbUser.permissions === 'string' ? JSON.parse(dbUser.permissions) : dbUser.permissions;
    } catch (e) {}

    const canProcess = staffRoles.includes(req.user?.role) || 
      (Array.isArray(userPerms) && userPerms.some((p: any) => 
        (p === '/emploi-du-temps-requests' || p.path === '/emploi-du-temps-requests') && 
        (p.access_type === 'read_write' || p.can_write)
      ));

    if (!canProcess) {
      return res.status(403).json({ error: "Accès refusé. Vous n'avez pas l'autorisation de traiter les demandes." });
    }

    const now = new Date().toISOString();
    db.prepare(`
      UPDATE timetable_requests 
      SET status = ?, reponse_admin = ?, processed_by = ?, processed_at = ?
      WHERE id = ? AND school_id = ?
    `).run(status, reponse_admin || null, req.userId, now, id, req.schoolId);
    
    // Notify the teacher about their request status
    const reqInfo = db.prepare(`
      SELECT tr.*, e.nom, e.prenom, u.id as utilisateur_id
      FROM timetable_requests tr
      JOIN enseignants e ON tr.enseignant_id = e.id
      JOIN utilisateurs u ON u.enseignant_id = e.id
      WHERE tr.id = ? AND tr.school_id = ?
    `).get(id, req.schoolId) as any;

    if (reqInfo && reqInfo.utilisateur_id) {
      let statusMsg = "a été mise à jour";
      if (status === 'approved') statusMsg = "a été approuvée";
      if (status === 'rejected') statusMsg = "a été rejetée";
      const noteMsg = reponse_admin ? ` (Note : ${reponse_admin})` : '';
      const subjectType = reqInfo.type_modification === 'notes' ? 'de modification de notes' : "d'ajustement d'emploi du temps";
      const targetLink = reqInfo.type_modification === 'notes'
        ? '/notes'
        : `/emploi-du-temps?classe_id=${reqInfo.classe_id || ''}&jour=${encodeURIComponent(reqInfo.jour || '')}&heure_debut=${encodeURIComponent(reqInfo.heure_debut || '')}&heure_fin=${encodeURIComponent(reqInfo.heure_fin || '')}&matiere_id=${reqInfo.matiere_id || ''}&request_id=${reqInfo.id}`;

      createNotification(
        reqInfo.utilisateur_id, 
        `Demande ${subjectType}`, 
        `Votre demande ${subjectType} ${statusMsg}.${noteMsg}`, 
        status === 'approved' ? 'success' : (status === 'rejected' ? 'error' : 'info'), 
        targetLink, 
        req.schoolId
      );
    }

    res.json({ success: true });
  });

  app.post("/api/timetable-requests", authenticateToken, (req: any, res) => {
    let { 
      enseignant_id, 
      type_modification, 
      classe_id, 
      matiere_id, 
      jour, 
      heure_debut, 
      heure_fin, 
      trimestre, 
      type_evaluation, 
      description 
    } = req.body;

    if (!enseignant_id && req.user?.enseignant_id) {
      enseignant_id = req.user.enseignant_id;
    }

    if (!enseignant_id) {
      const userWithEns = db.prepare("SELECT enseignant_id FROM utilisateurs WHERE id = ?").get(req.userId) as any;
      if (userWithEns?.enseignant_id) enseignant_id = userWithEns.enseignant_id;
    }

    if (!enseignant_id) {
      return res.status(400).json({ error: "Identifiant enseignant introuvable pour cette demande." });
    }

    const typeMod = type_modification === 'notes' ? 'notes' : 'emploi_du_temps';
    const anneeId = req.anneeId || getActiveYearId(req.schoolId);

    // If type is notes, ensure teacher actually teaches this class/matiere
    if (typeMod === 'notes' && classe_id) {
      const isTeacherInClass = db.prepare(`
        SELECT 1 FROM classe_matieres WHERE enseignant_id = ? AND classe_id = ? AND school_id = ?
        UNION
        SELECT 1 FROM classes WHERE (enseignant_id = ? OR professeur_principal_id = ?) AND id = ? AND school_id = ?
      `).get(enseignant_id, classe_id, req.schoolId, enseignant_id, enseignant_id, classe_id, req.schoolId);

      if (!isTeacherInClass) {
        return res.status(403).json({ error: "Vous ne pouvez demander une modification de notes que pour vos classes d'intervention." });
      }
    }

    db.prepare(`
      INSERT INTO timetable_requests (
        enseignant_id, type_modification, classe_id, matiere_id,
        jour, heure_debut, heure_fin, trimestre, type_evaluation,
        description, school_id, annee_id
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).run(
      enseignant_id, typeMod, classe_id || null, matiere_id || null,
      jour || null, heure_debut || null, heure_fin || null, trimestre || null, type_evaluation || null,
      description, req.schoolId, anneeId
    );
    
    // Notify admins and authorized pedagogical staff (Direction, Censeur, etc.)
    const ens = db.prepare("SELECT nom, prenom FROM enseignants WHERE id = ?").get(enseignant_id) as any;
    const ensNom = ens ? `${ens.prenom} ${ens.nom}` : 'Un enseignant';
    const notifTitle = typeMod === 'notes' ? `Demande modification Notes - ${ensNom}` : `Demande ajustement EDT - ${ensNom}`;
    broadcastNotification(
      ['super_admin', 'admin', 'direction', 'censeur', 'secretariat', 'secretaire', 'surveillant'], 
      notifTitle, 
      description ? (description.length > 80 ? description.substring(0, 77) + '...' : description) : "Demande transmise", 
      'info', 
      '/emploi-du-temps-requests', 
      req.schoolId
    );

    res.json({ success: true });
  });

  // Document Requests
  app.get("/api/document-requests", authenticateToken, (req: any, res) => {
    const { annee_id } = req.query;
    let query = `
      SELECT dr.*, u.nom as u_nom, u.role, u.email,
             e.nom as e_nom, e.prenom as e_prenom,
             p.nom as p_nom, p.prenom as p_prenom,
             proc.nom as proc_nom
      FROM document_requests dr
      JOIN utilisateurs u ON dr.requester_id = u.id
      LEFT JOIN enseignants e ON u.enseignant_id = e.id
      LEFT JOIN personnel_administratif p ON u.personnel_id = p.id
      LEFT JOIN utilisateurs proc ON dr.processed_by = proc.id
      WHERE dr.school_id = ?
    `;
    let params: any[] = [req.schoolId];

    if (annee_id && annee_id !== "all") {
      query += ` AND dr.annee_id = ?`;
      params.push(annee_id);
    }

    const adminRoles = ['super_admin', 'admin', 'direction', 'secretariat', 'secretaire', 'censeur', 'surveillant'];
    if (!adminRoles.includes(req.user.role)) {
      query += ` AND dr.requester_id = ?`;
      params.push(req.userId);
    }

    query += ` ORDER BY dr.created_at DESC`;
    
    const results = db.prepare(query).all(...params) as any[];
    
    // Map nom/prenom based on user role/join
    const mapped = results.map(r => ({
      ...r,
      nom: r.e_nom || r.p_nom || r.u_nom || '',
      prenom: r.e_prenom || r.p_prenom || ''
    }));
    
    res.json(mapped);
  });

