  app.delete("/api/document-requests/:id", authenticateToken, (req: any, res) => {
    const { id } = req.params;
    const adminRoles = ['super_admin', 'admin', 'direction', 'secretariat', 'secretaire', 'censeur'];
    
    const reqInfo = db.prepare(`SELECT requester_id, status FROM document_requests WHERE id = ? AND school_id = ?`).get(id, req.schoolId) as any;
    if (!reqInfo) {
      return res.status(404).json({ error: "Demande non trouvée" });
    }

    // Requester can delete if pending, admins can delete anytime
    if (reqInfo.requester_id !== req.userId && !adminRoles.includes(req.user.role)) {
      return res.status(403).json({ error: "Accès refusé" });
    }

    db.prepare(`DELETE FROM document_requests WHERE id = ? AND school_id = ?`).run(id, req.schoolId);
    res.json({ success: true });
  });

  // Import/Export
  app.get("/api/eleves/template", authenticateToken, (req: any, res) => {
    const classes = db.prepare("SELECT id, nom FROM classes WHERE school_id = ? ORDER BY nom").all(req.schoolId);
    const workbook = XLSX.utils.book_new();
    
    classes.forEach((c: any) => {
      const worksheet = XLSX.utils.aoa_to_sheet([
        ["Matricule", "Nom", "Prénom", "Sexe", "Date Naissance", "Nom Parent", "Tel Parent", "Adresse"]
      ]);
      XLSX.utils.book_append_sheet(workbook, worksheet, c.nom);
    });
    
    const buffer = XLSX.write(workbook, { type: 'buffer', bookType: 'xlsx' });
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.setHeader('Content-Disposition', 'attachment; filename="template_eleves.xlsx"');
    res.send(buffer);
  });

