  // Generate / Create / Reset account for a single administrative staff member
  app.post("/api/users/generate-staff", authenticateToken, async (req: any, res) => {
    const { personnel_id, role: customRole, permissions: customPermissions } = req.body;
    const staff = db.prepare("SELECT * FROM personnel_administratif WHERE id = ? AND school_id = ?").get(personnel_id, req.schoolId) as any;
    if (!staff) return res.status(404).json({ error: "Personnel administratif non trouvé" });
    if (!staff.email || !staff.email.includes('@')) {
      return res.status(400).json({ error: "Ce membre du personnel n'a pas d'adresse email valide renseignée." });
    }

    // Determine role & permissions
    const role = customRole || mapPosteToRole(staff.poste);
    let permissions = customPermissions;
    if (!permissions || !Array.isArray(permissions) || permissions.length === 0) {
      const rolePerms = db.prepare("SELECT permissions FROM role_permissions WHERE role = ? AND school_id = ?").get(role, req.schoolId) as any;
      permissions = rolePerms ? JSON.parse(rolePerms.permissions) : getDefaultRolePermissions(role);
    }
    const permissionsStr = JSON.stringify(permissions);

    // Check if user already exists
    const existingUser = db.prepare("SELECT * FROM utilisateurs WHERE personnel_id = ? OR email = ?").get(staff.id, staff.email) as any;
    
    const password = Math.random().toString(36).slice(-8);
    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    const otp_expiry = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(); // 24h
    const hashedPassword = bcrypt.hashSync(password, 10);

    let userId: number;
    if (existingUser) {
      db.prepare(`
        UPDATE utilisateurs 
        SET nom = ?, email = ?, role = ?, approuve = 1, permissions = ?, otp_code = ?, otp_expiry = ?, is_first_login = 1, personnel_id = ?, school_id = ?
        WHERE id = ?
      `).run(`${staff.prenom} ${staff.nom}`, staff.email, role, permissionsStr, otp, otp_expiry, staff.id, req.schoolId, existingUser.id);
      userId = existingUser.id;
    } else {
      const result = db.prepare(`
        INSERT INTO utilisateurs (nom, email, mot_de_passe, role, approuve, permissions, is_first_login, personnel_id, otp_code, otp_expiry, parent_admin_id, school_id)
        VALUES (?, ?, ?, ?, 1, ?, 1, ?, ?, ?, ?, ?)
      `).run(`${staff.prenom} ${staff.nom}`, staff.email, hashedPassword, role, permissionsStr, staff.id, otp, otp_expiry, req.userId, req.schoolId);
      userId = result.lastInsertRowid as number;
    }

    const setupLink = `${APP_URL}/setup-password?email=${encodeURIComponent(staff.email)}&otp=${otp}`;
    const textBody = `Bonjour ${staff.prenom} ${staff.nom},\n\nUn compte d'accès pour le poste de "${staff.poste}" (Rôle: ${role.toUpperCase()}) a été configuré pour vous sur MégafixaEduc Pro.\n\nEmail de connexion : ${staff.email}\nCode OTP d'activation : ${otp}\nMot de passe temporaire : ${password}\n\nPour activer votre compte et définir votre mot de passe personnel, veuillez cliquer sur le lien ci-dessous :\n${setupLink}\n\nCe lien expire dans 24 heures.`;
    const htmlBody = textBody.replace(/\n/g, '<br>').replace(setupLink, `<a href="${setupLink}" style="display: inline-block; padding: 10px 20px; background-color: #10b981; color: white; text-decoration: none; border-radius: 8px; font-weight: bold;">Activer mon compte</a>`);

    const mailResult = await sendMailWithFallback({
      to: staff.email,
      subject: `Activation de votre compte ${staff.poste} - MégafixaEduc Pro`,
      text: textBody,
      html: htmlBody,
      otp
    });

    const schoolInfo = db.prepare("SELECT id, nom, code_ecole FROM school_info WHERE id = ?").get(req.schoolId) as any;
    const schoolName = schoolInfo?.nom || 'Votre Établissement';
    const schoolCode = schoolInfo?.code_ecole || `SCH-${String(req.schoolId).padStart(4, '0')}`;

    logActivity(req.userId, 'CREATE', 'USER_STAFF', userId, { email: staff.email, role, personnel_id: staff.id }, req.schoolId);
    res.json({ 
      success: true, 
      id: userId, 
      username: staff.email, 
      password, 
      otp, 
      role, 
      poste: staff.poste,
      fullName: `${staff.prenom} ${staff.nom}`,
      matricule: staff.matricule || null,
      schoolId: req.schoolId,
      schoolCode: schoolCode,
      schoolName: schoolName,
      schoolLoginUrl: `/login?school_id=${req.schoolId}`,
      setupLink,
      simulated: mailResult.simulated 
    });
  });

  // Batch create/sync accounts for all administrative staff
  app.post("/api/users/sync-staff", authenticateToken, async (req: any, res) => {
    if (req.user.role !== 'admin' && req.user.role !== 'super_admin' && req.user.role !== 'direction') {
      return res.status(403).json({ error: "Accès refusé. Administrateur requis." });
    }
    try {
      const staffList = db.prepare("SELECT * FROM personnel_administratif WHERE school_id = ?").all(req.schoolId) as any[];
      let createdCount = 0;
      let updatedCount = 0;
      let skippedCount = 0;
      const errors: string[] = [];
      let anySimulated = false;

      for (const member of staffList) {
        if (!member.email || !member.email.includes('@')) {
          skippedCount++;
          continue;
        }

        const role = mapPosteToRole(member.poste);
        const rolePerms = db.prepare("SELECT permissions FROM role_permissions WHERE role = ? AND school_id = ?").get(role, req.schoolId) as any;
        const permissions = rolePerms ? JSON.parse(rolePerms.permissions) : getDefaultRolePermissions(role);
        const permissionsStr = JSON.stringify(permissions);

        const existingUser = db.prepare("SELECT * FROM utilisateurs WHERE personnel_id = ? OR email = ?").get(member.id, member.email) as any;

        const defaultPassword = 'MegaFixaStaff2024!';
        const hashedPassword = bcrypt.hashSync(defaultPassword, 10);
        const otpCode = Math.floor(100000 + Math.random() * 900000).toString();
        const otpExpiry = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

        if (existingUser) {
          if (!existingUser.personnel_id) {
            db.prepare("UPDATE utilisateurs SET personnel_id = ? WHERE id = ?").run(member.id, existingUser.id);
            updatedCount++;
          } else {
            skippedCount++;
          }
          continue;
        }

        try {
          db.prepare(`
            INSERT INTO utilisateurs (nom, email, mot_de_passe, role, approuve, personnel_id, permissions, otp_code, otp_expiry, is_first_login, school_id, parent_admin_id)
            VALUES (?, ?, ?, ?, 1, ?, ?, ?, ?, 1, ?, ?)
          `).run(`${member.prenom} ${member.nom}`, member.email, hashedPassword, role, member.id, permissionsStr, otpCode, otpExpiry, req.schoolId, req.userId);

          createdCount++;

          const setupLink = `${APP_URL}/setup-password?email=${encodeURIComponent(member.email)}&otp=${otpCode}`;
          const body = `Bonjour ${member.prenom} ${member.nom},\n\nUn compte d'accès MégafixaEduc Pro (${member.poste}) a été créé pour vous.\n\nIdentifiants :\nEmail : ${member.email}\nCode OTP : ${otpCode}\n\nPour activer votre compte et définir votre mot de passe personnel, veuillez cliquer sur le lien suivant :\n${setupLink}\n\nCe lien expire dans 24 heures.`;
          const htmlBody = body.replace(/\n/g, '<br>').replace(setupLink, `<a href="${setupLink}" style="display: inline-block; padding: 10px 20px; background-color: #10b981; color: white; text-decoration: none; border-radius: 8px; font-weight: bold;">Activer mon compte</a>`);

          const mailRes = await sendMailWithFallback({
            to: member.email,
            subject: `Création de votre compte ${member.poste} - MégafixaEduc Pro`,
            text: body,
            html: htmlBody,
            otp: otpCode
          });
          if (mailRes.simulated) anySimulated = true;
        } catch (err: any) {
          errors.push(`Erreur pour ${member.email}: ${err.message}`);
        }
      }

      res.json({
        success: true,
        created: createdCount,
        updated: updatedCount,
        skipped: skippedCount,
        errors,
        simulated: anySimulated
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  function cleanStringForUsername(str: string): string {
    if (!str) return '';
    return str
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]/g, '')
      .trim();
  }

  function generateTeacherLoginCredentials(teacher: any, schoolId: number, schoolCode: string, excludeUserId?: number) {
    const cleanPrenom = cleanStringForUsername(teacher.prenom) || 'prof';
    const cleanNom = cleanStringForUsername(teacher.nom) || 'enseignant';
    const cleanSchoolCode = cleanStringForUsername(schoolCode) || `ecole${schoolId}`;
    
    // Auto code suffix: 3-digit random or matricule-based
    const randomSuffix = Math.floor(100 + Math.random() * 900);
    const identifier = `${cleanPrenom}.${cleanNom}.${randomSuffix}`;
    
    // Auto generated secure password
    const passDigits = Math.floor(1000 + Math.random() * 9000);
    const password = `Prof#${passDigits}`;

    // Verify if an email is already taken by another account in `utilisateurs`
    const isEmailTaken = (candidate: string, usedSet?: Set<string>): boolean => {
      if (!candidate) return true;
      const normalized = candidate.trim().toLowerCase();
      if (usedSet && usedSet.has(normalized)) return true;
      try {
        if (excludeUserId) {
          const row = db.prepare("SELECT id FROM utilisateurs WHERE LOWER(TRIM(email)) = LOWER(TRIM(?)) AND id != ?").get(normalized, excludeUserId) as any;
          return !!row;
        } else {
          const row = db.prepare("SELECT id FROM utilisateurs WHERE LOWER(TRIM(email)) = LOWER(TRIM(?))").get(normalized) as any;
          return !!row;
        }
      } catch (e) {
        return false;
      }
    };

    const rawEmail = (teacher.email && typeof teacher.email === 'string' && teacher.email.includes('@')) 
      ? teacher.email.trim().toLowerCase() 
      : '';

    let userEmail = '';
    if (rawEmail && !isEmailTaken(rawEmail)) {
      userEmail = rawEmail;
    } else {
      // If no valid email or if teacher's email is already registered to another account (e.g. admin or other teacher)
      let safeFallback = `${cleanPrenom}.${cleanNom}.${randomSuffix}@${cleanSchoolCode}.local`.toLowerCase();
      let attempt = 1;
      while (isEmailTaken(safeFallback) && attempt <= 30) {
        const extraRand = Math.floor(1000 + Math.random() * 9000);
        safeFallback = `${cleanPrenom}.${cleanNom}.${Date.now().toString().slice(-4)}${extraRand}@${cleanSchoolCode}.local`.toLowerCase();
        attempt++;
      }
      userEmail = safeFallback;
    }

    return {
      identifier,
      password,
      userEmail,
      contactEmail: rawEmail || userEmail
    };
  }

