  app.post("/api/users/generate-teachers-batch", authenticateToken, async (req: any, res) => {
    if (req.user.role !== 'admin' && req.user.role !== 'super_admin' && req.user.role !== 'direction') {
      return res.status(403).json({ error: "Accès refusé. Administrateur ou Direction requis." });
    }

    try {
      const { teacher_ids, role: customRole } = req.body;
      const role = customRole || 'enseignant';

      const schoolInfo = db.prepare("SELECT id, nom, code_ecole FROM school_info WHERE id = ?").get(req.schoolId) as any;
      const schoolName = schoolInfo?.nom || 'Votre Établissement';
      const schoolCode = schoolInfo?.code_ecole || `SCH-${String(req.schoolId).padStart(4, '0')}`;
      const schoolLoginUrl = `/login?code=${encodeURIComponent(schoolCode)}`;

      const rolePerms = db.prepare("SELECT permissions FROM role_permissions WHERE role = ? AND school_id = ?").get(role, req.schoolId) as any;
      const permissions = rolePerms ? JSON.parse(rolePerms.permissions) : getDefaultRolePermissions(role);
      const permissionsStr = JSON.stringify(permissions);

      let teachers: any[] = [];
      if (Array.isArray(teacher_ids) && teacher_ids.length > 0) {
        const placeholders = teacher_ids.map(() => '?').join(',');
        teachers = db.prepare(`SELECT * FROM enseignants WHERE id IN (${placeholders}) AND school_id = ?`).all(...teacher_ids, req.schoolId) as any[];
      } else {
        teachers = db.prepare("SELECT * FROM enseignants WHERE school_id = ?").all(req.schoolId) as any[];
      }

      if (teachers.length === 0) {
        return res.status(400).json({ error: "Aucun enseignant sélectionné ou trouvé." });
      }

      const createdAccounts: any[] = [];
      const errors: string[] = [];
      const usedEmailsInBatch = new Set<string>();

      for (const teacher of teachers) {
        try {
          // Safely locate existing user account specifically linked to this teacher
          let existingUser: any = null;
          if (teacher.user_id) {
            existingUser = db.prepare("SELECT * FROM utilisateurs WHERE id = ? AND school_id = ?").get(teacher.user_id, req.schoolId) as any;
          }
          if (!existingUser) {
            existingUser = db.prepare("SELECT * FROM utilisateurs WHERE enseignant_id = ? AND school_id = ?").get(teacher.id, req.schoolId) as any;
          }
          if (!existingUser && teacher.email && teacher.email.includes('@')) {
            existingUser = db.prepare(`
              SELECT * FROM utilisateurs 
              WHERE LOWER(TRIM(email)) = LOWER(TRIM(?)) 
                AND school_id = ? 
                AND (enseignant_id IS NULL OR enseignant_id = ?) 
                AND personnel_id IS NULL 
                AND eleve_id IS NULL
            `).get(teacher.email.trim(), req.schoolId, teacher.id) as any;
          }

          let creds = generateTeacherLoginCredentials(teacher, req.schoolId, schoolCode, existingUser?.id);
          let userEmail = creds.userEmail;
          let identifier = creds.identifier;
          let password = creds.password;

          // Ensure email not already claimed in this batch
          if (usedEmailsInBatch.has(userEmail.toLowerCase())) {
            const extraRand = Math.floor(1000 + Math.random() * 9000);
            userEmail = `prof.${teacher.id}.${Date.now().toString().slice(-4)}${extraRand}@${cleanStringForUsername(schoolCode) || 'ecole'}.local`.toLowerCase();
          }
          usedEmailsInBatch.add(userEmail.toLowerCase());

          const hashedPassword = bcrypt.hashSync(password, 10);

          let userId: number;
          if (existingUser) {
            try {
              db.prepare(`
                UPDATE utilisateurs 
                SET nom = ?, email = ?, identifiant = ?, mot_de_passe = ?, mot_de_passe_initial = ?, role = ?, approuve = 1, permissions = ?, otp_code = NULL, otp_expiry = NULL, is_first_login = 0, enseignant_id = ?, school_id = ?
                WHERE id = ?
              `).run(
                `${teacher.prenom} ${teacher.nom}`,
                userEmail,
                identifier,
                hashedPassword,
                password,
                role,
                permissionsStr,
                teacher.id,
                req.schoolId,
                existingUser.id
              );
            } catch (upErr: any) {
              if (upErr.message?.includes('UNIQUE') && upErr.message?.includes('email')) {
                userEmail = `prof.${teacher.id}.${Date.now()}@${cleanStringForUsername(schoolCode) || 'ecole'}.local`.toLowerCase();
                usedEmailsInBatch.add(userEmail.toLowerCase());
                db.prepare(`
                  UPDATE utilisateurs 
                  SET nom = ?, email = ?, identifiant = ?, mot_de_passe = ?, mot_de_passe_initial = ?, role = ?, approuve = 1, permissions = ?, otp_code = NULL, otp_expiry = NULL, is_first_login = 0, enseignant_id = ?, school_id = ?
                  WHERE id = ?
                `).run(
                  `${teacher.prenom} ${teacher.nom}`,
                  userEmail,
                  identifier,
                  hashedPassword,
                  password,
                  role,
                  permissionsStr,
                  teacher.id,
                  req.schoolId,
                  existingUser.id
                );
              } else {
                throw upErr;
              }
            }
            userId = existingUser.id;
          } else {
            try {
              const insertRes = db.prepare(`
                INSERT INTO utilisateurs (nom, email, identifiant, mot_de_passe, mot_de_passe_initial, role, approuve, permissions, is_first_login, enseignant_id, otp_code, otp_expiry, parent_admin_id, school_id)
                VALUES (?, ?, ?, ?, ?, ?, 1, ?, 0, ?, NULL, NULL, ?, ?)
              `).run(
                `${teacher.prenom} ${teacher.nom}`,
                userEmail,
                identifier,
                hashedPassword,
                password,
                role,
                permissionsStr,
                teacher.id,
                req.userId,
                req.schoolId
              );
              userId = insertRes.lastInsertRowid as number;
            } catch (insErr: any) {
              if (insErr.message?.includes('UNIQUE') && insErr.message?.includes('email')) {
                userEmail = `prof.${teacher.id}.${Date.now()}@${cleanStringForUsername(schoolCode) || 'ecole'}.local`.toLowerCase();
                usedEmailsInBatch.add(userEmail.toLowerCase());
                const insertRes = db.prepare(`
                  INSERT INTO utilisateurs (nom, email, identifiant, mot_de_passe, mot_de_passe_initial, role, approuve, permissions, is_first_login, enseignant_id, otp_code, otp_expiry, parent_admin_id, school_id)
                  VALUES (?, ?, ?, ?, ?, ?, 1, ?, 0, ?, NULL, NULL, ?, ?)
                `).run(
                  `${teacher.prenom} ${teacher.nom}`,
                  userEmail,
                  identifier,
                  hashedPassword,
                  password,
                  role,
                  permissionsStr,
                  teacher.id,
                  req.userId,
                  req.schoolId
                );
                userId = insertRes.lastInsertRowid as number;
              } else {
                throw insErr;
              }
            }
          }

          // Update teacher record with account credentials and user_id
          db.prepare(`
            UPDATE enseignants 
            SET identifiant_compte = ?, mot_de_passe_initial = ?, user_id = ?
            WHERE id = ? AND school_id = ?
          `).run(identifier, password, userId, teacher.id, req.schoolId);

          logActivity(req.userId, 'GENERATE_TEACHER_ACCOUNT', 'USER', userId, { teacher_id: teacher.id, identifiant: identifier }, req.schoolId);

          createdAccounts.push({
            id: userId,
            teacherId: teacher.id,
            fullName: `${teacher.nom} ${teacher.prenom}`,
            nom: teacher.nom,
            prenom: teacher.prenom,
            matricule: teacher.matricule || '',
            matiere: teacher.matieres_noms || '',
            classes: teacher.classes_noms || '',
            username: identifier,
            identifiant: identifier,
            password: password,
            mot_de_passe_initial: password,
            email: teacher.email || userEmail,
            role,
            schoolId: req.schoolId,
            schoolCode: schoolCode,
            schoolName: schoolName,
            schoolLoginUrl: schoolLoginUrl
          });
        } catch (itemErr: any) {
          console.error(`Error generating account for teacher ${teacher.id} (${teacher.nom} ${teacher.prenom}):`, itemErr);
          errors.push(`Erreur pour ${teacher.nom} ${teacher.prenom}: ${itemErr.message}`);
        }
      }

      res.json({
        success: true,
        count: createdAccounts.length,
        accounts: createdAccounts,
        errors: errors.length > 0 ? errors : undefined,
        schoolInfo: {
          id: req.schoolId,
          nom: schoolName,
          code_ecole: schoolCode,
          schoolLoginUrl: schoolLoginUrl
        }
      });
    } catch (error: any) {
      console.error("Batch generate teachers error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/users/sync-teachers", authenticateToken, async (req: any, res) => {
    if (req.user.role !== 'admin' && req.user.role !== 'super_admin' && req.user.role !== 'direction') {
      return res.status(403).json({ error: "Accès refusé. Administrateur requis." });
    }
    try {
      const teachers = db.prepare("SELECT * FROM enseignants WHERE school_id = ?").all(req.schoolId) as any[];
      let createdCount = 0;
      let updatedCount = 0;
      let skippedCount = 0;
      const errors: string[] = [];
      let anySimulated = false;

      const rolePerms = db.prepare("SELECT permissions FROM role_permissions WHERE role = 'enseignant' AND school_id = ?").get(req.schoolId) as any;
      const permissions = rolePerms ? JSON.parse(rolePerms.permissions) : getDefaultRolePermissions('enseignant');
      const permissionsStr = JSON.stringify(permissions);

      const schoolInfo = db.prepare("SELECT id, nom, code_ecole FROM school_info WHERE id = ?").get(req.schoolId) as any;
      const schoolCode = schoolInfo?.code_ecole || `SCH-${String(req.schoolId).padStart(4, '0')}`;

      for (const teacher of teachers) {
        if (!teacher.email || !teacher.email.includes('@')) {
          skippedCount++;
          continue;
        }

        // Check if user already exists specifically for this teacher
        let existingUser: any = null;
        if (teacher.user_id) {
          existingUser = db.prepare("SELECT * FROM utilisateurs WHERE id = ? AND school_id = ?").get(teacher.user_id, req.schoolId) as any;
        }
        if (!existingUser) {
          existingUser = db.prepare("SELECT * FROM utilisateurs WHERE enseignant_id = ? AND school_id = ?").get(teacher.id, req.schoolId) as any;
        }
        if (!existingUser && teacher.email) {
          existingUser = db.prepare(`
            SELECT * FROM utilisateurs 
            WHERE LOWER(email) = LOWER(?) 
              AND school_id = ? 
              AND (enseignant_id IS NULL OR enseignant_id = ?) 
              AND personnel_id IS NULL 
              AND eleve_id IS NULL
          `).get(teacher.email.trim(), req.schoolId, teacher.id) as any;
        }
        
        if (existingUser) {
          // If user exists but enseignant_id is not set, link it
          if (!existingUser.enseignant_id) {
            db.prepare("UPDATE utilisateurs SET enseignant_id = ? WHERE id = ?").run(teacher.id, existingUser.id);
            db.prepare("UPDATE enseignants SET user_id = ? WHERE id = ? AND school_id = ?").run(existingUser.id, teacher.id, req.schoolId);
            updatedCount++;
          } else {
            skippedCount++;
          }
          continue;
        }

        // Create new user with collision-safe email
        const defaultPassword = 'MegaFixa2024!';
        const hashedPassword = bcrypt.hashSync(defaultPassword, 10);

        try {
          const { identifier, userEmail } = generateTeacherLoginCredentials(teacher, req.schoolId, schoolCode);

          const result = db.prepare(`
            INSERT INTO utilisateurs (nom, email, identifiant, mot_de_passe, role, approuve, enseignant_id, permissions, otp_code, otp_expiry, is_first_login, school_id, parent_admin_id)
            VALUES (?, ?, ?, ?, 'enseignant', 1, ?, ?, NULL, NULL, 0, ?, ?)
          `).run(`${teacher.prenom} ${teacher.nom}`, userEmail, identifier, hashedPassword, teacher.id, permissionsStr, req.schoolId, req.userId);

          const newUserId = result.lastInsertRowid as number;
          db.prepare("UPDATE enseignants SET user_id = ?, identifiant_compte = ? WHERE id = ? AND school_id = ?").run(newUserId, identifier, teacher.id, req.schoolId);

          createdCount++;

          const body = `Bonjour ${teacher.prenom} ${teacher.nom},\n\nUn compte enseignant a été créé pour vous sur MégafixaEduc Pro.\n\nVos identifiants de connexion :\nIdentifiant : ${identifier}\nEmail de connexion : ${userEmail}\nMot de passe : ${defaultPassword}\nLien de connexion : ${APP_URL}/login\n\nVous pouvez vous connecter directement avec ces identifiants sans code OTP requis.`;
          const htmlBody = body.replace(/\n/g, '<br>');

          const mailRes = await sendMailWithFallback({
            to: teacher.email,
            subject: "Création de votre compte enseignant - MégafixaEduc Pro",
            text: body,
            html: htmlBody
          });
          if (mailRes.simulated) anySimulated = true;
        } catch (err: any) {
          errors.push(`Erreur pour ${teacher.email}: ${err.message}`);
        }
      }

      res.json({ 
        success: true, 
        created: createdCount, 
        updated: updatedCount, 
        skipped: skippedCount, 
        errors,
        simulated: anySimulated 
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

