  // Auth - Google Authentication
  app.post("/api/auth/google", async (req, res) => {
    try {
      const { idToken, email: bodyEmail, nom: bodyNom, name: bodyName, google_id: bodyGoogleId, uid: bodyUid } = req.body;
      
      let email = bodyEmail;
      let name = bodyNom || bodyName;
      let uid = bodyGoogleId || bodyUid;

      if (idToken || req.body.credential) {
        const rawToken = idToken || req.body.credential;
        try {
          // Direct base64 JWT payload decode for GIS credential
          const parts = rawToken.split('.');
          if (parts.length === 3) {
            const payload = JSON.parse(Buffer.from(parts[1], 'base64').toString('utf8'));
            if (payload.email) email = payload.email;
            if (payload.name) name = payload.name;
            if (payload.sub) uid = payload.sub;
          }
        } catch (jwtErr) {
          console.warn("Direct JWT credential parse fallback:", jwtErr);
        }

        if (idToken) {
          try {
            const { auth: adminAuth } = await import("./src/lib/firebase-admin.ts");
            const decoded = await adminAuth.verifyIdToken(idToken);
            if (decoded.email) email = decoded.email;
            if (decoded.name) name = decoded.name;
            if (decoded.uid) uid = decoded.uid;
          } catch (tokenErr) {
            console.warn("Token verification fallback to decoded attributes:", tokenErr);
          }
        }
      }

      if (!email && !uid) {
        return res.status(400).json({ success: false, error: "Identifiants Google requis (email ou token)" });
      }

      const cleanEmail = email ? email.toString().trim().toLowerCase() : null;
      const cleanNom = name || cleanEmail?.split('@')[0] || "Utilisateur Google";
      const cleanUid = uid || cleanEmail;

      // Find user in SQLite by email or google_id
      let user = db.prepare(`
        SELECT * FROM utilisateurs 
        WHERE (google_id IS NOT NULL AND google_id = ?) 
           OR (? IS NOT NULL AND LOWER(TRIM(email)) = ?)
        LIMIT 1
      `).get(cleanUid, cleanEmail, cleanEmail) as any;

      if (!user) {
        return res.status(200).json({
          success: false,
          unlinkedEmail: true,
          email: cleanEmail,
          nom: cleanNom,
          redirectUrl: "/signup",
          error: "Cette adresse email n'est liée à aucun compte école existant.",
          message: "Cet email n'est rattaché à aucun compte école. Vous n'avez accès qu'à la page d'information et de création de compte école."
        });
      } else {
        if (!user.google_id || user.approuve === 0) {
          db.prepare("UPDATE utilisateurs SET google_id = COALESCE(google_id, ?), approuve = 1 WHERE id = ?").run(cleanUid, user.id);
          user.google_id = user.google_id || cleanUid;
          user.approuve = 1;
        }
      }

      logActivity(user.id, 'LOGIN_GOOGLE', 'USER', user.id, { email: user.email }, user.school_id);

      // Check if teacher
      let enseignant_id = user.enseignant_id || null;
      let cycle = null;
      if (user.role === 'enseignant' || user.enseignant_id) {
        const enseignant = db.prepare("SELECT id, cycle FROM enseignants WHERE (email = ? OR id = ?) AND school_id = ?").get(user.email, user.enseignant_id, user.school_id) as any;
        if (enseignant) {
          enseignant_id = enseignant.id;
          cycle = enseignant.cycle;
        }
      }

      // Get role permissions
      const rolePerms = db.prepare("SELECT permissions FROM role_permissions WHERE role = ? AND school_id = ?").get(user.role, user.school_id) as any;
      const defaultPermissions = rolePerms ? JSON.parse(rolePerms.permissions) : [];

      const token = jwt.sign(
        { 
          id: user.id, 
          email: user.email, 
          role: user.role, 
          schoolId: user.school_id, 
          eleve_id: user.eleve_id,
          enseignant_id: enseignant_id || user.enseignant_id,
          cycle: cycle,
          google_id: user.google_id,
          lastSeen: new Date().toISOString() 
        },
        JWT_SECRET,
        { expiresIn: '24h' }
      );

      res.json({ 
        success: true, 
        token,
        user: { 
          id: user.id, 
          nom: user.nom, 
          email: user.email, 
          role: user.role,
          cycle: cycle,
          school_id: user.school_id,
          google_id: user.google_id,
          can_write: user.can_write,
          is_test_account: user.is_test_account || 0,
          enseignant_id: enseignant_id,
          eleve_id: user.eleve_id,
          permissions: user.permissions ? JSON.parse(user.permissions) : defaultPermissions
        } 
      });
    } catch (error: any) {
      console.error("Google Auth Error:", error);
      res.status(500).json({ success: false, error: error.message || "Échec de l'authentification Google" });
    }
  });

