  // Helper functions for OpenAI and Gemini multi-provider support
  function getOpenAIKey(): string | null {
    if (process.env.OPENAI_API_KEY && process.env.OPENAI_API_KEY.trim()) {
      return process.env.OPENAI_API_KEY.trim();
    }
    try {
      const row = db.prepare("SELECT value FROM super_admin_settings WHERE key = 'openai_api_key'").get() as any;
      if (row && row.value && row.value.trim()) return row.value.trim();
    } catch (e) {}
    return null;
  }

  async function callOpenAIChat({
    model = "gpt-4o",
    messages,
    temperature = 0.7,
    max_tokens = 1200,
    user
  }: {
    model?: string;
    messages: Array<{ role: string; content: string }>;
    temperature?: number;
    max_tokens?: number;
    user?: string;
  }): Promise<string> {
    if (STRICT_OFFLINE_MODE) {
      throw new Error("Mode Hors-ligne strict actif : l'accès aux serveurs externes OpenAI est interdit.");
    }
    const apiKey = getOpenAIKey();
    if (!apiKey) {
      throw new Error("Clé API OpenAI (OPENAI_API_KEY) non configurée sur le serveur. Veuillez ajouter OPENAI_API_KEY dans votre fichier .env pour activer ChatGPT, ou basculer sur Google Gemini.");
    }
    const response = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        model: model || "gpt-4o",
        messages,
        temperature,
        max_tokens,
        user
      })
    });

    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      const errMsg = data?.error?.message || `Erreur HTTP ${response.status} de l'API OpenAI`;
      throw new Error(`OpenAI: ${errMsg}`);
    }

    const content = data?.choices?.[0]?.message?.content;
    if (!content) {
      throw new Error("Réponse vide reçue de ChatGPT");
    }
    return content;
  }

  async function callOpenAIImage({
    prompt,
    size = "1024x1024",
    model = "dall-e-3",
    user
  }: {
    prompt: string;
    size?: string;
    model?: string;
    user?: string;
  }): Promise<string> {
    if (STRICT_OFFLINE_MODE) {
      throw new Error("Mode Hors-ligne strict actif : l'accès aux serveurs externes DALL-E / OpenAI est interdit.");
    }
    const apiKey = getOpenAIKey();
    if (!apiKey) {
      throw new Error("Clé API OpenAI (OPENAI_API_KEY) non configurée sur le serveur. Veuillez ajouter OPENAI_API_KEY dans votre fichier .env pour utiliser DALL-E 3, ou basculer sur Google Gemini Flash Image.");
    }
    const response = await fetch("https://api.openai.com/v1/images/generations", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${apiKey}`
      },
      body: JSON.stringify({
        model: model || "dall-e-3",
        prompt,
        n: 1,
        size,
        response_format: "b64_json",
        user
      })
    });

    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      const errMsg = data?.error?.message || `Erreur HTTP ${response.status} de DALL-E 3`;
      throw new Error(`DALL-E 3: ${errMsg}`);
    }

    const b64 = data?.data?.[0]?.b64_json;
    if (!b64) {
      throw new Error("Aucune image reçue de DALL-E 3");
    }
    return `data:image/png;base64,${b64}`;
  }

