  // Download Payment Receipt PDF directly
  app.get("/api/subscriptions/receipt-pdf/:reference", (req, res) => {
    try {
      const { reference } = req.params;
      const tx = db.prepare("SELECT * FROM subscription_transactions WHERE reference = ?").get(reference) as any;
      if (!tx) return res.status(404).send("Transaction introuvable");

      const lic = db.prepare("SELECT * FROM subscription_licenses WHERE transaction_ref = ?").get(reference) as any;
      const licenseKey = lic?.license_key || tx.subscription_key || 'MEG-OFFICIEL';
      const durationDays = (tx.plan_name || '').toLowerCase().includes('starter') ? 90 : 365;
      const durationText = durationDays >= 365 ? '1 an (Annuel)' : `${Math.round(durationDays / 30)} mois`;
      const dateDebut = tx.date_creation ? tx.date_creation.split(' ')[0] : new Date().toISOString().split('T')[0];
      const expiryDate = lic?.expires_at ? lic.expires_at.split(' ')[0] : new Date(Date.now() + durationDays * 86400000).toISOString().split('T')[0];

      const reqProto = req.headers['x-forwarded-proto'] || 'https';
      const host = req.headers.host || 'ais-dev-zd7qxhnwatli2x7sfezpbx-323991635372.europe-west2.run.app';
      const originUrl = req.headers.origin || `${reqProto}://${host}`;
      const loginUrl = `${originUrl}/login?schoolKey=${encodeURIComponent(licenseKey)}`;

      const totalAmountVal = tx.total_amount || lic?.total_amount || (tx.billing_cycle === 'annuel' ? tx.amount : Math.round(Number(tx.amount) / 0.45));
      const initialPctVal = tx.initial_percentage || lic?.initial_percentage || (tx.billing_cycle === 'annuel' ? 100 : 45);
      const initialAmountVal = tx.initial_amount || lic?.initial_amount || tx.amount;
      const remainingAmountVal = tx.remaining_amount ?? lic?.remaining_amount ?? (totalAmountVal - initialAmountVal);
      const modNameVal = tx.modality_name || lic?.modality_name || (tx.billing_cycle === 'annuel' ? 'Annuel (Paiement unique)' : 'Échelonné (45% initial)');
      const remScheduleVal = tx.remaining_schedule || lic?.remaining_schedule || (initialPctVal === 100 ? 'Aucun solde (100% réglé)' : 'Solde de 55% exigible selon modalité');

      const buf = generateReceiptPdfBuffer({
        reference: tx.reference,
        schoolName: tx.school_name,
        adminNom: tx.admin_nom || 'Directeur / Fondateur',
        email: tx.email,
        phone: tx.payer_phone || undefined,
        planName: tx.plan_name,
        amount: tx.amount,
        totalPlanAmount: totalAmountVal,
        initialPercentage: initialPctVal,
        initialAmount: initialAmountVal,
        remainingPercentage: (initialPctVal === 100 ? 0 : 55),
        remainingAmount: remainingAmountVal,
        modalityName: modNameVal,
        remainingSchedule: remScheduleVal,
        currency: tx.currency || 'FCFA',
        operator: tx.operator || 'Mobile Money',
        dateDebut,
        dateFin: expiryDate,
        durationText,
        licenseKey,
        loginUrl
      });

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Recu_Paiement_${reference}.pdf"`);
      res.send(buf);
    } catch (err: any) {
      res.status(500).send("Erreur génération reçu PDF: " + err.message);
    }
  });

  // Download Subscription Sheet PDF directly
