  // ==========================================
  // SUBSCRIPTION LICENSE KEY MANAGEMENT API
  // ==========================================

  // Verify a subscription key
  app.get("/api/subscriptions/verify-key/:key", (req, res) => {
    try {
      const { key } = req.params;
      if (!key) return res.status(400).json({ valid: false, error: "Clé requise" });

      const license = db.prepare("SELECT * FROM subscription_licenses WHERE license_key = ?").get(key.trim()) as any;
      if (!license) {
        return res.status(404).json({ valid: false, error: "Clé d'abonnement introuvable ou invalide" });
      }

      const isExpired = license.expires_at && new Date(license.expires_at) < new Date();
      if (isExpired) {
        return res.status(400).json({ 
          valid: false, 
          expired: true, 
          error: "Cette clé d'abonnement a expiré le " + license.expires_at 
        });
      }

      res.json({
        valid: true,
        license_key: license.license_key,
        plan_name: license.plan_name,
        school_name: license.school_name,
        client_email: license.client_email,
        expires_at: license.expires_at,
        duration_days: license.duration_days,
        features: typeof license.features === 'string' ? JSON.parse(license.features || '[]') : license.features,
        status: license.status,
        used_at: license.used_at
      });
    } catch (err: any) {
      res.status(500).json({ valid: false, error: err.message });
    }
  });

  // Activate school using a subscription key (First Access or Renewal)
  app.post("/api/subscriptions/activate-key", async (req: any, res) => {
    try {
      const keyInput = req.body.license_key || req.body.licenseKey || req.body.key;
      const emailInput = req.body.admin_email || req.body.email;
      const schoolIdInput = req.body.school_id || req.body.schoolId;
      const schoolNameInput = req.body.school_name || req.body.schoolName;

      if (!keyInput) {
        return res.status(400).json({ success: false, error: "Clé d'abonnement requise." });
      }

      const cleanKey = keyInput.toString().trim();
      const license = db.prepare("SELECT * FROM subscription_licenses WHERE license_key = ?").get(cleanKey) as any;
      if (!license) {
        return res.status(404).json({ success: false, error: "Clé d'abonnement inexistante ou invalide." });
      }

      if (license.status === 'revoked') {
        return res.status(400).json({ success: false, error: "Cette clé d'abonnement a été révoquée par l'administrateur." });
      }

      // Determine target school
      let targetSchoolId = schoolIdInput || req.schoolId;

      if (!targetSchoolId && schoolNameInput) {
        const found = db.prepare("SELECT id FROM school_info WHERE LOWER(TRIM(nom)) = LOWER(TRIM(?))").get(schoolNameInput.trim()) as any;
        if (found) targetSchoolId = found.id;
      }

      if (!targetSchoolId && emailInput) {
        const user = db.prepare("SELECT school_id FROM utilisateurs WHERE LOWER(TRIM(email)) = LOWER(TRIM(?))").get(emailInput.trim()) as any;
        if (user) targetSchoolId = user.school_id;
      }

      if (!targetSchoolId && license.school_id) {
        targetSchoolId = license.school_id;
      }

      // Enforce single-use rule for subscription activation keys
      if (license.status === 'used') {
        const alreadySchool = license.school_id ? db.prepare("SELECT id, nom, statut_abonnement FROM school_info WHERE id = ?").get(license.school_id) as any : null;
        const schoolNameInfo = alreadySchool?.nom || license.school_name || "votre établissement";
        
        // If this key is being activated/re-checked for this same school, return a clear success status rather than a blocking error
        let isSameSchool = false;
        if (targetSchoolId && alreadySchool && Number(targetSchoolId) === Number(alreadySchool.id)) {
          isSameSchool = true;
        } else if (targetSchoolId && db.prepare("SELECT id FROM school_info WHERE id = ? AND subscription_key = ?").get(targetSchoolId, cleanKey)) {
          isSameSchool = true;
        } else if (schoolNameInput && alreadySchool && schoolNameInput.trim().toLowerCase() === alreadySchool.nom.trim().toLowerCase()) {
          isSameSchool = true;
        } else if (!targetSchoolId && alreadySchool) {
          isSameSchool = true;
        }

        if (isSameSchool) {
          return res.json({ 
            success: true, 
            already_active: true,
            message: `Votre compte école pour « ${schoolNameInfo} » est déjà activé avec succès pour la formule « ${license.plan_name} ». Vous pouvez vous connecter librement avec votre adresse email et votre mot de passe.`,
            plan: license.plan_name,
            license_key: cleanKey,
            school_id: alreadySchool?.id || targetSchoolId,
            expires_at: license.expires_at,
            features: typeof license.features === 'string' ? JSON.parse(license.features || '[]') : license.features
          });
        }

        return res.status(400).json({ 
          success: false, 
          already_used: true,
          error: `Cette clé d'activation a déjà été utilisée pour un autre établissement (« ${schoolNameInfo} ») et n'est valable qu'une seule fois.` 
        });
      }

      const isExpired = license.expires_at && new Date(license.expires_at) < new Date();
      if (isExpired) {
        return res.status(400).json({ success: false, error: `Cette clé a expiré le ${license.expires_at}.` });
      }

      if (!targetSchoolId) {
        // If still no school, pick the first school or create one
        const firstSchool = db.prepare("SELECT id FROM school_info ORDER BY id ASC LIMIT 1").get() as any;
        if (firstSchool) {
          targetSchoolId = firstSchool.id;
        } else {
          const newSchool = db.prepare("INSERT INTO school_info (nom, plan_abonnement, statut_abonnement) VALUES (?, ?, 'actif')")
            .run(license.school_name || "Mon Établissement Scolaire", license.plan_name);
          targetSchoolId = newSchool.lastInsertRowid;
        }
      }

      // Apply subscription formula and expiry date to the school
      const expiryDate = license.expires_at || new Date(Date.now() + (license.duration_days || 365) * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

      // Atomic activation transaction
      const activateTx = db.transaction(() => {
        db.prepare(`
          UPDATE school_info 
          SET plan_abonnement = ?, statut_abonnement = 'actif', date_fin_abonnement = ?, subscription_key = ?
          WHERE id = ?
        `).run(license.plan_name, expiryDate, cleanKey, targetSchoolId);

        // Unlock all features for this school
        try {
          db.prepare("DELETE FROM school_feature_locks WHERE school_id = ?").run(targetSchoolId);
        } catch (e) {}

        // Update license record with school association and mark as USED (single-use)
        db.prepare(`
          UPDATE subscription_licenses 
          SET school_id = ?, used_at = CURRENT_TIMESTAMP, status = 'used'
          WHERE license_key = ?
        `).run(targetSchoolId, cleanKey);

        // Automatically approve and authorize the school admin user so they log in freely with email and password
        if (emailInput) {
          db.prepare(`
            UPDATE utilisateurs 
            SET approuve = 1, is_first_login = 0, otp_code = NULL, otp_expiry = NULL, school_id = ?
            WHERE LOWER(TRIM(email)) = LOWER(TRIM(?))
          `).run(targetSchoolId, emailInput.trim());
        }
        if (license.client_email) {
          db.prepare(`
            UPDATE utilisateurs 
            SET approuve = 1, is_first_login = 0, otp_code = NULL, otp_expiry = NULL, school_id = ?
            WHERE LOWER(TRIM(email)) = LOWER(TRIM(?))
          `).run(targetSchoolId, license.client_email.trim());
        }
        db.prepare(`
          UPDATE utilisateurs 
          SET approuve = 1, is_first_login = 0, otp_code = NULL, otp_expiry = NULL 
          WHERE school_id = ? AND role = 'admin'
        `).run(targetSchoolId);
      });

      activateTx();

      // Log activity
      logActivity(req.userId || 1, 'LICENSE_KEY_ACTIVATED', 'SCHOOL', targetSchoolId, {
        license_key: cleanKey,
        plan: license.plan_name,
        school_id: targetSchoolId
      }, targetSchoolId);

      const features = typeof license.features === 'string' ? JSON.parse(license.features || '[]') : license.features;

      res.json({
        success: true,
        message: `Félicitations ! Votre compte école a été activé avec succès pour la formule « ${license.plan_name} ». La clé a été validée (usage unique). Vous pouvez désormais vous connecter librement avec votre adresse email et votre mot de passe pour accéder à votre espace école.`,
        plan: license.plan_name,
        license_key: cleanKey,
        school_id: targetSchoolId,
        expires_at: expiryDate,
        features: features || getPlanFeaturesList(license.plan_name)
      });
    } catch (err: any) {
      console.error("Error activating license key:", err);
      res.status(500).json({ success: false, error: "Erreur lors de l'activation de la clé: " + err.message });
    }
  });

  // Get Fiche d'Abonnement HTML directly by key
  app.get("/api/subscriptions/fiche/:key", (req, res) => {
    try {
      const { key } = req.params;
      const license = db.prepare("SELECT * FROM subscription_licenses WHERE license_key = ?").get(key.trim()) as any;
      if (!license) {
        return res.status(404).send("<h1>Fiche d'abonnement introuvable</h1>");
      }

      if (license.fiche_html) {
        res.setHeader('Content-Type', 'text/html; charset=utf-8');
        return res.send(license.fiche_html);
      }

      // Generate if not stored
      const features = typeof license.features === 'string' ? JSON.parse(license.features || '[]') : (license.features || getPlanFeaturesList(license.plan_name));
      const html = generateFicheAbonnementHtml({
        schoolName: license.school_name || "Établissement Scolaire",
        adminNom: license.client_name || "Direction",
        email: license.client_email,
        planName: license.plan_name,
        amount: license.amount,
        currency: license.currency || 'FCFA',
        reference: license.transaction_ref || license.license_key,
        licenseKey: license.license_key,
        dateDebut: (license.created_at || '').split(' ')[0] || new Date().toISOString().split('T')[0],
        dateFin: license.expires_at || '',
        durationText: `${license.duration_days || 365} jours`,
        features
      });

      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      res.send(html);
    } catch (err: any) {
      res.status(500).send("<h1>Erreur lors de la génération de la fiche d'abonnement</h1>");
    }
  });

  // Get current active license for authenticated school
