  const handleSignupRequestOld = async (req: any, res: any) => {
    const { nom, email: rawEmail, password, schoolName, plan, paymentMethod, paymentReference } = req.body;
    if (!rawEmail || !nom || !password || !schoolName) {
      return res.status(400).json({ success: false, error: "Tous les champs sont requis" });
    }
    const email = rawEmail.toString().trim().toLowerCase();
    try {
      // Check if email already exists before doing anything else
      const existingUser = db.prepare("SELECT id FROM utilisateurs WHERE LOWER(TRIM(email)) = LOWER(TRIM(?))").get(email);
      if (existingUser) {
        return res.status(409).json({ 
          success: false, 
          code: "EMAIL_ALREADY_EXISTS", 
          error: "Cette adresse email est déjà associée à un compte établissement. Veuillez vous connecter directement." 
        });
      }

      // Password security check: minimum 8 characters, uppercase, lowercase, number
      if (password.length < 8 || !/[A-Z]/.test(password) || !/[a-z]/.test(password) || !/[0-9]/.test(password)) {
        return res.status(400).json({ 
          success: false, 
          error: "Le mot de passe doit comporter au moins 8 caractères et inclure au moins une majuscule, une minuscule et un chiffre." 
        });
      }

      const hashedPassword = bcrypt.hashSync(password, 8);
      
      // Functional subscription plan selected by the user
      const rawPlan = (plan || 'standard').toString().toLowerCase().trim();
      const validPlans = ['starter', 'standard', 'excellence'];
      const chosenPlan = validPlans.includes(rawPlan) ? rawPlan : 'standard';
      
      const now = new Date();
      // Set validity: 90 days for starter (quarterly), 365 days for standard/excellence
      const validityDays = chosenPlan === 'starter' ? 90 : 365;
      const expiry = new Date(now.getTime() + validityDays * 24 * 60 * 60 * 1000);
      const expiryDate = expiry.toISOString().split('T')[0];
      const initialStatus = 'en_attente_activation';

      // Create school first with subscription details (status awaiting activation)
      const schoolInfo = db.prepare(`
        INSERT INTO school_info (nom, plan_abonnement, statut_abonnement, date_fin_abonnement) 
        VALUES (?, ?, ?, ?)
      `).run(schoolName, chosenPlan, initialStatus, expiryDate);
      const schoolId = schoolInfo.lastInsertRowid;

      // If there's a payment reference, link it
      if (paymentReference) {
        db.prepare("UPDATE subscription_transactions SET school_name = ? WHERE reference = ?").run(schoolName, paymentReference);
      }

      // If there's a payment method, record the intent (simplified)
      if (paymentMethod && paymentMethod !== 'none') {
        // Here you would normally integrate with Stripe/PayPal/etc.
        // For now, we just log it or mark the school as 'pending_payment'
        console.log(`School ${schoolName} registered with plan ${chosenPlan} and payment method ${paymentMethod}`);
      }

      // Seed default role permissions for the new school
      const allPaths = [
        '/', '/classes', '/eleves', '/promotions', '/enseignants', 
        '/matieres', '/notes', '/paiements', '/emploi-du-temps', 
        '/ecole', '/parametres', '/audit-logs', '/alertes'
      ];

      const defaultPermissions = {
        admin: allPaths.map(path => ({ path, can_write: true })),
        secretariat: [
          { path: '/', can_write: true },
          { path: '/classes', can_write: true },
          { path: '/eleves', can_write: true },
          { path: '/promotions', can_write: true },
          { path: '/enseignants', can_write: false },
          { path: '/matieres', can_write: false },
          { path: '/notes', can_write: true },
          { path: '/emploi-du-temps', can_write: true },
          { path: '/alertes', can_write: true }
        ],
        enseignant: [
          { path: '/', can_write: false },
          { path: '/eleves', can_write: false },
          { path: '/notes', can_write: true },
          { path: '/emploi-du-temps', can_write: false }
        ],
        comptable: [
          { path: '/', can_write: false },
          { path: '/eleves', can_write: false },
          { path: '/paiements', can_write: true }
        ]
      };

      const insertRolePerm = db.prepare("INSERT INTO role_permissions (role, permissions, school_id) VALUES (?, ?, ?)");
      Object.entries(defaultPermissions).forEach(([role, perms]) => {
        insertRolePerm.run(role, JSON.stringify(perms), schoolId);
      });

      // Seed default academic year for the new school
      const currentLibelle = getCurrentAcademicYearLibelle();
      const today = new Date();
      const dateDebut = new Date(today.getFullYear(), 8, 1).toISOString().split('T')[0]; // Sept 1st
      const dateFin = new Date(today.getFullYear() + 1, 6, 31).toISOString().split('T')[0]; // July 31st
      db.prepare("INSERT INTO annees_scolaires (libelle, date_debut, date_fin, est_active, school_id) VALUES (?, ?, ?, 1, ?)").run(currentLibelle, dateDebut, dateFin, schoolId);

      // Check if an activation key was provided at signup
      const keyProvided = (req.body.activation_key || req.body.license_key || req.body.subscription_key || '').toString().trim();
      let keyPlan = null;
      if (keyProvided) {
        const lic = db.prepare("SELECT * FROM subscription_licenses WHERE license_key = ?").get(keyProvided) as any;
        if (!lic) {
          return res.status(404).json({ success: false, error: "Clé d'abonnement inexistante ou invalide." });
        }
        if (lic.status === 'revoked') {
          return res.status(400).json({ success: false, error: "Cette clé d'abonnement a été révoquée." });
        }
        if (lic.status === 'used') {
          return res.status(400).json({ success: false, error: "Cette clé d'activation a déjà été utilisée. Chaque clé est à usage unique pour activer un compte école." });
        }
        // Link key to the school WITHOUT marking as used: user will explicitly activate it
        db.prepare("UPDATE subscription_licenses SET school_id = ?, status = 'available' WHERE license_key = ?").run(schoolId, keyProvided);
        db.prepare("UPDATE school_info SET plan_abonnement = ?, statut_abonnement = 'en_attente_activation', subscription_key = ? WHERE id = ?").run(lic.plan_name, keyProvided, schoolId);
        keyPlan = lic.plan_name;
      }

      // New school accounts: email is immediately recognized as authorized to log in freely with their password
      const info = db.prepare("INSERT INTO utilisateurs (nom, email, mot_de_passe, role, approuve, is_first_login, can_write, school_id, otp_code, otp_expiry) VALUES (?, ?, ?, 'admin', 1, 0, 1, ?, NULL, NULL)")
        .run(nom, email, hashedPassword, schoolId);
      
      logActivity(info.lastInsertRowid as number, 'SIGNUP_ADMIN', 'USER', info.lastInsertRowid as number, { email, schoolId }, schoolId as number);
      
      const reqProto = req.headers['x-forwarded-proto'] || 'https';
      const host = req.headers.host || 'ais-dev-zd7qxhnwatli2x7sfezpbx-323991635372.europe-west2.run.app';
      const originUrl = req.headers.origin || `${reqProto}://${host}`;
      const loginUrl = `${originUrl}/login?email=${encodeURIComponent(email)}`;

      const mailResult = await sendMailWithFallback({
        to: email,
        subject: `Bienvenue sur MégafixaEduc Pro - Compte École ${schoolName}`,
        text: `Bonjour ${nom},\n\nBienvenue sur MégafixaEduc Pro.\n\nVotre compte école pour "${schoolName}" a été créé avec succès.\n\nVotre adresse email (${email}) est désormais reconnue et autorisée comme identifiant pour vous connecter directement à votre espace école avec votre mot de passe.\n\nLien direct de connexion : ${loginUrl}\n\nL'équipe MégafixaEduc Pro`
      });

      res.json({ 
        success: true, 
        id: info.lastInsertRowid,
        schoolId,
        loginUrl,
        plan: keyPlan || chosenPlan,
        simulated: mailResult.simulated,
        message: "Compte école créé avec succès ! Votre adresse email est autorisée à vous connecter directement avec votre mot de passe."
      });
    } catch (err: any) {
      console.error("Signup error:", err);
      if (err.message && err.message.includes("UNIQUE constraint failed")) {
        return res.status(409).json({ 
          success: false, 
          code: "EMAIL_ALREADY_EXISTS", 
          error: "Cette adresse email est déjà associée à un compte établissement. Veuillez vous connecter directement." 
        });
      }
      res.status(500).json({ success: false, error: "Une erreur est survenue lors de la création du compte: " + err.message });
    }
  };

