  const isStaffMiddleware = (req: any, res: any, next: any) => {
    const role = req.user?.role;
    const staffRoles = ["admin", "super_admin", "fonde", "direction", "censeur", "proviseur", "directeur_etudes", "surveillant_general", "surveillant", "secretariat", "coordonnateur"];
    if (!staffRoles.includes(role)) {
      return res.status(403).json({ 
        error: "Accès strictement interdit. Cet espace est exclusivement réservé au personnel de direction et d'organisation des examens." 
      });
    }
    next();
  };

  // GET /api/epreuves-composition - List retained exams for compositions
  app.get("/api/epreuves-composition", authenticateToken, isStaffMiddleware, (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const { cycle, trimestre, statut_tirage, session, search, annee_id } = req.query;

      let query = `
        SELECT 
          rc.*,
          e.titre as epreuve_titre,
          e.fichier_epreuve_url,
          e.fichier_epreuve_nom,
          e.fichier_epreuve_type,
          e.fichier_corrige_url,
          e.fichier_corrige_nom,
          e.bareme,
          e.coefficient,
          e.consignes as epreuve_consignes,
          e.enseignant_nom as auteur_epreuve_nom,
          e.type_evaluation,
          e.statut as epreuve_statut
        FROM epreuves_retenues_composition rc
        JOIN epreuves e ON rc.epreuve_id = e.id
        WHERE (rc.school_id = ? OR rc.school_id IS NULL)
      `;
      const params: any[] = [schoolId];

      if (annee_id && annee_id !== "all") {
        query += ` AND rc.annee_id = ?`;
        params.push(annee_id);
      }

      if (cycle && cycle !== "all" && cycle !== "tous") {
        query += ` AND (rc.cycle = ? OR e.cycle = ?)`;
        params.push(cycle, cycle);
      }

      if (trimestre && trimestre !== "all") {
        query += ` AND rc.trimestre = ?`;
        params.push(parseInt(trimestre, 10));
      }

      if (statut_tirage && statut_tirage !== "all") {
        query += ` AND rc.statut_tirage = ?`;
        params.push(statut_tirage);
      }

      if (session && typeof session === "string" && session.trim()) {
        query += ` AND rc.session_nom LIKE ?`;
        params.push(`%${session.trim()}%`);
      }

      if (search && typeof search === "string" && search.trim()) {
        const term = `%${search.trim()}%`;
        query += ` AND (
          rc.session_nom LIKE ? OR e.titre LIKE ? OR rc.matiere_nom LIKE ? OR rc.classe_nom LIKE ? OR rc.salle LIKE ? OR rc.surveillants LIKE ? OR e.enseignant_nom LIKE ?
        )`;
        params.push(term, term, term, term, term, term, term);
      }

      query += ` ORDER BY rc.date_composition DESC, rc.heure_debut ASC, rc.id DESC`;
      const list = db.prepare(query).all(...params);
      res.json(list);
    } catch (error: any) {
      console.error("Error fetching compositions epreuves:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // GET /api/epreuves-composition/stats - Stats for composition secretarial desk
  app.get("/api/epreuves-composition/stats", authenticateToken, isStaffMiddleware, (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const { cycle } = req.query;

      let cycleFilter = "";
      const params: any[] = [schoolId];
      if (cycle && cycle !== "all" && cycle !== "tous") {
        cycleFilter = ` AND (cycle = ? OR cycle IS NULL)`;
        params.push(cycle);
      }

      const rows = db.prepare(`
        SELECT statut_tirage, COUNT(*) as count, SUM(nombre_copies_prevues) as total_copies
        FROM epreuves_retenues_composition
        WHERE (school_id = ? OR school_id IS NULL) ${cycleFilter}
        GROUP BY statut_tirage
      `).all(...params) as any[];

      const stats = {
        total_retenues: 0,
        en_attente_tirage: 0,
        en_impression: 0,
        pret_sous_pli: 0,
        distribue: 0,
        total_copies_prevues: 0
      };

      rows.forEach((r: any) => {
        const c = parseInt(r.count, 10) || 0;
        const copies = parseInt(r.total_copies, 10) || 0;
        stats.total_retenues += c;
        stats.total_copies_prevues += copies;

        if (r.statut_tirage === "en_impression") stats.en_impression += c;
        else if (r.statut_tirage === "pret_sous_pli") stats.pret_sous_pli += c;
        else if (r.statut_tirage === "distribue") stats.distribue += c;
        else stats.en_attente_tirage += c;
      });

      res.json(stats);
    } catch (error: any) {
      console.error("Error fetching compositions epreuves stats:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // POST /api/epreuves-composition - Retain an exam from validated bank for a composition session
  app.post("/api/epreuves-composition", authenticateToken, isStaffMiddleware, (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const {
        epreuve_id,
        session_nom,
        trimestre,
        date_composition,
        heure_debut,
        heure_fin,
        duree_minutes,
        salle,
        surveillants,
        nombre_copies_prevues,
        statut_tirage,
        consignes_secretariat
      } = req.body;

      if (!epreuve_id) {
        return res.status(400).json({ error: "L'identifiant de l'épreuve validée est obligatoire." });
      }

      // Check exam exists and is validated
      const epreuve = db.prepare("SELECT * FROM epreuves WHERE id = ? AND (school_id = ? OR school_id IS NULL)").get(epreuve_id, schoolId) as any;
      if (!epreuve) {
        return res.status(404).json({ error: "Épreuve source introuvable." });
      }

      if (epreuve.statut !== "validee") {
        return res.status(400).json({ error: "Seules les épreuves validées par l'encadrement pédagogique peuvent être retenues pour la composition." });
      }

      const activeYear = epreuve.annee_id || getActiveYearId(schoolId);
      const staffNom = (req.user?.nom || "Secrétariat des Examens").trim();

      const stmt = db.prepare(`
        INSERT INTO epreuves_retenues_composition (
          school_id, epreuve_id, session_nom, cycle, classe_id, classe_nom,
          niveau, matiere_nom, trimestre, annee_id, annee_libelle,
          date_composition, heure_debut, heure_fin, duree_minutes,
          salle, surveillants, nombre_copies_prevues, statut_tirage,
          consignes_secretariat, retenu_par, retenu_par_nom
        ) VALUES (
          ?, ?, ?, ?, ?, ?,
          ?, ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?, ?,
          ?, ?, ?
        )
      `);

      const result = stmt.run(
        schoolId,
        epreuve_id,
        (session_nom || "Composition Officielle").trim(),
        epreuve.cycle || "secondaire",
        epreuve.classe_id || null,
        epreuve.classe_nom || null,
        epreuve.niveau || null,
        epreuve.matiere_nom || "",
        trimestre || epreuve.trimestre || 1,
        activeYear || null,
        epreuve.annee_libelle || null,
        date_composition || null,
        heure_debut || null,
        heure_fin || null,
        duree_minutes || epreuve.duree_minutes || 120,
        (salle || "").trim() || "Toutes les salles",
        (surveillants || "").trim() || null,
        parseInt(nombre_copies_prevues || "0", 10) || 0,
        statut_tirage || "en_attente",
        (consignes_secretariat || "").trim() || null,
        req.userId,
        staffNom
      );

      const newId = result.lastInsertRowid;
      logActivity(req.userId, "CREATE", "epreuves_retenues_composition", newId, { epreuve_id, session_nom }, schoolId);

      res.json({ success: true, id: newId, message: "Épreuve retenue avec succès pour la composition officielle." });
    } catch (error: any) {
      console.error("Error creating composition epreuve:", error);
      res.status(500).json({ error: error.message });
    }
  });

