  // ==========================================
  // SYSTEME DE MESSAGERIE INTERNE ET SMS
  // ==========================================

  // SMS Dispatcher / Gateway simulation & execution
  async function sendSmsService(schoolId: number, senderId: number, recipientPhone: string, recipientName: string, recipientType: string, messageText: string) {
    try {
      const config = db.prepare("SELECT * FROM sms_configs WHERE school_id = ?").get(schoolId) as any;
      const provider = config?.provider || 'simulation';
      const senderNumberOrName = config?.sender_number_or_name || 'MEGAFIXA';
      
      // Clean phone number (strip spaces, symbols)
      const cleanPhone = recipientPhone.replace(/[^0-9+]/g, '');
      const smsCount = Math.max(1, Math.ceil(messageText.length / 160));
      let status = 'sent';
      let costEstimate = smsCount * 25; // 25 FCFA approx par SMS

      if (config?.is_active === 0) {
        status = 'failed';
      } else if (provider === 'twilio' && config?.account_sid && config?.auth_token) {
        // Twilio integration
        try {
          const auth = Buffer.from(`${config.account_sid}:${config.auth_token}`).toString('base64');
          const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${config.account_sid}/Messages.json`;
          const params = new URLSearchParams();
          params.append('To', cleanPhone);
          params.append('From', senderNumberOrName);
          params.append('Body', messageText);

          const twilioRes = await fetch(twilioUrl, {
            method: 'POST',
            headers: {
              'Authorization': `Basic ${auth}`,
              'Content-Type': 'application/x-www-form-urlencoded'
            },
            body: params.toString()
          });

          if (twilioRes.ok) {
            status = 'delivered';
          } else {
            const errData = await twilioRes.json();
            console.error("Twilio error:", errData);
            status = 'failed';
          }
        } catch (e: any) {
          console.error("Twilio exception:", e);
          status = 'failed';
        }
      } else {
        // High-fidelity instant simulation with gateway log
        status = 'simulated';
      }

      // Deduct credit balance if active
      if (config && config.credit_balance !== undefined) {
        const newBalance = Math.max(0, (config.credit_balance || 1000) - smsCount);
        db.prepare("UPDATE sms_configs SET credit_balance = ? WHERE school_id = ?").run(newBalance, schoolId);
      }

      // Save log entry
      const anneeId = getActiveYearId(schoolId);
      db.prepare(`
        INSERT INTO sms_logs (school_id, sender_id, recipient_phone, recipient_name, recipient_type, message, status, provider, sms_count, cost_estimate, annee_id)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(schoolId, senderId, cleanPhone, recipientName || 'Destinataire', recipientType || 'autre', messageText, status, provider, smsCount, costEstimate, anneeId);

      return { success: status !== 'failed', status, provider, cleanPhone };
    } catch (err: any) {
      console.error("SMS Dispatch error:", err);
      return { success: false, error: err.message };
    }
  }

  // Get conversation contacts and groups (Teachers, Admins, Staff, Classes)
  app.get("/api/messagerie/contacts", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const currentUserId = req.userId;
      const userRole = req.user?.role || 'enseignant';
      const isTeacher = userRole === 'enseignant';

      // 1. Staff & Admin & Teacher Users
      // If teacher, strictly restrict contacts to administration and all teachers
      const roleFilterClause = isTeacher
        ? "AND u.role IN ('admin', 'super_admin', 'fonde', 'direction', 'censeur', 'surveillant', 'secretariat', 'comptable', 'enseignant')"
        : "";

      const userTableCols = (db.prepare("PRAGMA table_info(utilisateurs)").all() as any[]).map((c: any) => c.name);
      const userTelExpression = userTableCols.includes('telephone')
        ? "COALESCE(u.telephone, e.telephone, p.telephone, '')"
        : "COALESCE(e.telephone, p.telephone, '')";

      const users = db.prepare(`
        SELECT u.id, u.nom, u.email, u.role,
               ${userTelExpression} as telephone,
               u.enseignant_id, u.personnel_id,
               e.photo as photo_ens, p.photo as photo_pers
        FROM utilisateurs u
        LEFT JOIN enseignants e ON u.enseignant_id = e.id
        LEFT JOIN personnel_administratif p ON u.personnel_id = p.id
        WHERE u.school_id = ? AND u.id != ? AND u.approuve = 1 ${roleFilterClause}
        ORDER BY u.nom ASC
      `).all(schoolId, currentUserId) as any[];

      // Format user contacts
      const userContacts = users.map(u => ({
        id: u.id,
        name: u.nom,
        role: u.role,
        email: u.email,
        telephone: u.telephone || '',
        photo: u.photo_ens || u.photo_pers || '',
        type: 'user'
      }));

      // 2. Classes for broadcast to parents (only available for administrative staff / non-teachers)
      const classes = isTeacher ? [] : (db.prepare(`
        SELECT c.id, c.nom, c.niveau, COUNT(e.id) as nombre_eleves
        FROM classes c
        LEFT JOIN eleves e ON c.id = e.classe_id AND e.school_id = ?
        WHERE c.school_id = ?
        GROUP BY c.id
        ORDER BY c.nom ASC
      `).all(schoolId, schoolId) as any[]);

      // 3. Parents List with children names (only available for administrative staff / non-teachers)
      const parents = isTeacher ? [] : (db.prepare(`
        SELECT e.nom_parent as name, e.tel_parent as telephone, e.email_parent as email,
               GROUP_CONCAT(e.nom || ' ' || e.prenom, ', ') as enfants,
               c.nom as classe_nom, e.classe_id
        FROM eleves e
        LEFT JOIN classes c ON e.classe_id = c.id
        WHERE e.school_id = ? AND (e.tel_parent IS NOT NULL OR e.email_parent IS NOT NULL OR e.nom_parent IS NOT NULL)
        GROUP BY e.tel_parent, e.nom_parent
        ORDER BY e.nom_parent ASC
      `).all(schoolId) as any[]);

      // Count unread messages for current user
      const unreadCount = (db.prepare(`
        SELECT COUNT(*) as count 
        FROM messages_internes m
        LEFT JOIN message_lectures l ON m.id = l.message_id AND l.user_id = ?
        WHERE m.school_id = ? AND m.sender_id != ?
          AND l.id IS NULL
          AND (
            (m.recipient_type = 'user' AND m.recipient_id = ?)
            OR (m.recipient_type = 'role' AND m.recipient_role = ?)
            OR (m.recipient_type = 'all_teachers' AND ? IN ('enseignant', 'admin', 'direction'))
            OR (m.recipient_type = 'all_parents' AND ? IN ('parent', 'admin', 'direction'))
            OR (? IN ('admin', 'direction'))
          )
      `).get(
        currentUserId, schoolId, currentUserId,
        currentUserId, req.user?.role, req.user?.role, req.user?.role, req.user?.role
      ) as any)?.count || 0;

      res.json({
        users: userContacts,
        classes,
        parents,
        unreadCount
      });
    } catch (err: any) {
      console.error("Contacts error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Get messages list / conversations
  app.get("/api/messagerie/messages", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const currentUserId = req.userId;
      const userRole = req.user?.role || 'enseignant';
      const { contactId, recipientType, classeId, annee_id } = req.query;

      let messages = [];

      if (contactId && contactId !== 'undefined') {
        // Direct 1-on-1 conversation
        const targetUserId = parseInt(contactId as string);
        let query = `
          SELECT m.*, 
                 u_send.nom as sender_name, u_send.role as sender_role, u_send.email as sender_email,
                 u_rec.nom as recipient_name,
                 c.nom as classe_nom,
                 CASE WHEN l.id IS NOT NULL THEN 1 ELSE 0 END as is_read
          FROM messages_internes m
          JOIN utilisateurs u_send ON m.sender_id = u_send.id
          LEFT JOIN utilisateurs u_rec ON m.recipient_id = u_rec.id
          LEFT JOIN classes c ON m.classe_id = c.id
          LEFT JOIN message_lectures l ON m.id = l.message_id AND l.user_id = ?
          WHERE m.school_id = ? 
            AND (
              (m.sender_id = ? AND m.recipient_id = ?)
              OR (m.sender_id = ? AND m.recipient_id = ?)
            )
        `;
        const params: any[] = [currentUserId, schoolId, currentUserId, targetUserId, targetUserId, currentUserId];

        if (annee_id && annee_id !== 'all') {
          query += " AND m.annee_id = ?";
          params.push(annee_id);
        }

        query += " ORDER BY m.created_at ASC";
        messages = db.prepare(query).all(...params);

        // Mark as read
        const unreadIds = messages.filter((m: any) => !m.is_read && m.sender_id !== currentUserId).map((m: any) => m.id);
        if (unreadIds.length > 0) {
          const insertLecture = db.prepare("INSERT OR IGNORE INTO message_lectures (message_id, user_id) VALUES (?, ?)");
          db.transaction(() => {
            for (const mid of unreadIds) {
              insertLecture.run(mid, currentUserId);
            }
          })();
        }
      } else if (recipientType === 'class_parents' && classeId) {
        // Messages sent to class parents
        messages = db.prepare(`
          SELECT m.*, 
                 u_send.nom as sender_name, u_send.role as sender_role, u_send.email as sender_email,
                 c.nom as classe_nom,
                 1 as is_read
          FROM messages_internes m
          JOIN utilisateurs u_send ON m.sender_id = u_send.id
          LEFT JOIN classes c ON m.classe_id = c.id
          WHERE m.school_id = ? AND m.recipient_type = 'class_parents' AND m.classe_id = ?
          ORDER BY m.created_at ASC
        `).all(schoolId, classeId);
      } else if (recipientType) {
        // Group channel messages (all_teachers, role:direction, all_parents)
        messages = db.prepare(`
          SELECT m.*, 
                 u_send.nom as sender_name, u_send.role as sender_role, u_send.email as sender_email,
                 CASE WHEN l.id IS NOT NULL THEN 1 ELSE 0 END as is_read
          FROM messages_internes m
          JOIN utilisateurs u_send ON m.sender_id = u_send.id
          LEFT JOIN message_lectures l ON m.id = l.message_id AND l.user_id = ?
          WHERE m.school_id = ? AND m.recipient_type = ?
          ORDER BY m.created_at ASC
        `).all(currentUserId, schoolId, recipientType);
      } else {
        // Global inbox list / feed for the user
        let query = `
          SELECT m.*, 
                 u_send.nom as sender_name, u_send.role as sender_role, u_send.email as sender_email,
                 u_rec.nom as recipient_name,
                 c.nom as classe_nom,
                 CASE WHEN l.id IS NOT NULL THEN 1 ELSE 0 END as is_read
          FROM messages_internes m
          JOIN utilisateurs u_send ON m.sender_id = u_send.id
          LEFT JOIN utilisateurs u_rec ON m.recipient_id = u_rec.id
          LEFT JOIN classes c ON m.classe_id = c.id
          LEFT JOIN message_lectures l ON m.id = l.message_id AND l.user_id = ?
          WHERE m.school_id = ?
            AND (
              m.sender_id = ?
              OR (m.recipient_type = 'user' AND m.recipient_id = ?)
              OR (m.recipient_type = 'role' AND m.recipient_role = ?)
              OR (m.recipient_type = 'all_teachers' AND ? IN ('enseignant', 'admin', 'direction'))
              OR (m.recipient_type = 'all_parents' AND ? IN ('parent', 'admin', 'direction'))
              OR (? IN ('admin', 'direction'))
            )
        `;
        const params: any[] = [
          currentUserId, schoolId,
          currentUserId, currentUserId, userRole, userRole, userRole, userRole
        ];

        if (annee_id && annee_id !== 'all') {
          query += " AND m.annee_id = ?";
          params.push(annee_id);
        }

        query += " ORDER BY m.created_at DESC LIMIT 100";
        messages = db.prepare(query).all(...params);
      }

      res.json(messages);
    } catch (err: any) {
      console.error("Fetch messages error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Send an internal message (with optional SMS dispatch)
  app.post("/api/messagerie/messages", authenticateToken, async (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const senderId = req.userId;
      const { 
        recipient_type, 
        recipient_id, 
        recipient_role, 
        classe_id, 
        subject, 
        content, 
        audio_url,
        attachment_url,
        attachment_name,
        send_sms,
        parent_phones // array or specific numbers
      } = req.body;

      if ((!content || !content.trim()) && !audio_url && !attachment_url) {
        return res.status(400).json({ error: "Le contenu du message ne peut pas être vide." });
      }

      const senderRole = req.user?.role || 'enseignant';
      if (senderRole === 'enseignant') {
        if (recipient_type === 'all_parents' || recipient_type === 'class_parents') {
          return res.status(403).json({ error: "L'accès à la messagerie pour les enseignants est réservé aux échanges avec l'administration et tous les enseignants." });
        }
        if (recipient_type === 'user' && recipient_id) {
          const target = db.prepare("SELECT role FROM utilisateurs WHERE id = ? AND school_id = ?").get(recipient_id, schoolId) as any;
          if (target && !['admin', 'super_admin', 'fonde', 'direction', 'censeur', 'surveillant', 'secretariat', 'comptable', 'enseignant'].includes(target.role)) {
            return res.status(403).json({ error: "Vous pouvez uniquement échanger avec l'administration et les enseignants." });
          }
        }
      }

      const anneeId = req.anneeId || getActiveYearId(schoolId);

      // 1. Insert message into database
      const insertStmt = db.prepare(`
        INSERT INTO messages_internes (
          school_id, sender_id, recipient_type, recipient_id, recipient_role, classe_id, subject, content, audio_url, attachment_url, attachment_name, is_sms_sent, annee_id
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `);

      const result = insertStmt.run(
        schoolId, 
        senderId, 
        recipient_type || 'user', 
        recipient_id || null, 
        recipient_role || null, 
        classe_id || null, 
        subject || '', 
        (content || '').trim(), 
        audio_url || null,
        attachment_url || null,
        attachment_name || null,
        send_sms ? 1 : 0,
        anneeId
      );

      const messageId = result.lastInsertRowid;

      // Mark as read by the sender
      db.prepare("INSERT OR IGNORE INTO message_lectures (message_id, user_id) VALUES (?, ?)").run(messageId, senderId);

      // 2. Create in-app notifications
      const senderName = req.user?.nom || 'Un utilisateur';
      const notifTitle = subject ? `Nouveau message: ${subject}` : `Nouveau message de ${senderName}`;
      const safeContent = content || (audio_url ? '[Message Vocal]' : '');
      const notifSnippet = safeContent.length > 80 ? safeContent.substring(0, 80) + '...' : safeContent;

      if (recipient_type === 'user' && recipient_id) {
        createNotification(recipient_id, notifTitle, notifSnippet, 'info', '/messagerie', schoolId);
      } else if (recipient_type === 'role' && recipient_role) {
        broadcastNotification([recipient_role], notifTitle, notifSnippet, 'info', '/messagerie', schoolId);
      } else if (recipient_type === 'all_teachers') {
        broadcastNotification(['enseignant'], notifTitle, notifSnippet, 'info', '/messagerie', schoolId);
      } else if (recipient_type === 'all_parents') {
        broadcastNotification(['parent'], notifTitle, notifSnippet, 'info', '/messagerie', schoolId);
      }

      // 2b. Automatic notification for Admin/Direction if from Teacher/Parent
      if (['enseignant', 'parent'].includes(senderRole)) {
        broadcastNotification(['admin', 'direction', 'secretariat'], `Message de ${senderRole}: ${senderName}`, notifSnippet, 'info', '/messagerie', schoolId);
      }

      // 3. Handle SMS sending if enabled
      let smsResultSummary = { sent: 0, failed: 0, recipients: [] as string[] };

      if (send_sms) {
        let targetsToSend: { name: string; phone: string; type: string }[] = [];

        if (recipient_type === 'user' && recipient_id) {
          const userTarget = db.prepare("SELECT nom, telephone FROM utilisateurs WHERE id = ?").get(recipient_id) as any;
          if (userTarget?.telephone) {
            targetsToSend.push({ name: userTarget.nom, phone: userTarget.telephone, type: 'utilisateur' });
          }
        } else if (recipient_type === 'all_teachers') {
          const teachers = db.prepare("SELECT nom, telephone FROM enseignants WHERE school_id = ? AND telephone IS NOT NULL").all(schoolId) as any[];
          for (const t of teachers) {
            if (t.telephone) targetsToSend.push({ name: t.nom, phone: t.telephone, type: 'enseignant' });
          }
        } else if (recipient_type === 'class_parents' && classe_id) {
          const classParents = db.prepare("SELECT nom_parent as nom, tel_parent as phone FROM eleves WHERE classe_id = ? AND school_id = ? AND tel_parent IS NOT NULL").all(classe_id, schoolId) as any[];
          for (const p of classParents) {
            if (p.phone) targetsToSend.push({ name: p.nom || 'Parent', phone: p.phone, type: 'parent' });
          }
        } else if (recipient_type === 'all_parents') {
          const allParents = db.prepare("SELECT DISTINCT nom_parent as nom, tel_parent as phone FROM eleves WHERE school_id = ? AND tel_parent IS NOT NULL").all(schoolId) as any[];
          for (const p of allParents) {
            if (p.phone) targetsToSend.push({ name: p.nom || 'Parent', phone: p.phone, type: 'parent' });
          }
        } else if (Array.isArray(parent_phones) && parent_phones.length > 0) {
          for (const p of parent_phones) {
            if (p && p.phone) targetsToSend.push({ name: p.name || 'Destinataire', phone: p.phone, type: 'parent' });
          }
        }

        // Deduplicate phone numbers
        const uniqueMap = new Map<string, { name: string; phone: string; type: string }>();
        for (const t of targetsToSend) {
          const clean = t.phone.replace(/[^0-9]/g, '');
          if (clean.length >= 8 && !uniqueMap.has(clean)) {
            uniqueMap.set(clean, t);
          }
        }

        const smsText = subject ? `[${subject}] ${content}` : content;
        for (const [, item] of uniqueMap) {
          const sendRes = await sendSmsService(schoolId, senderId, item.phone, item.name, item.type, smsText);
          if (sendRes.success) {
            smsResultSummary.sent++;
            smsResultSummary.recipients.push(item.phone);
          } else {
            smsResultSummary.failed++;
          }
        }

        db.prepare("UPDATE messages_internes SET sms_status = ? WHERE id = ?").run(
          smsResultSummary.sent > 0 ? `sent_${smsResultSummary.sent}` : 'failed',
          messageId
        );
      }

      // 4. Handle Email dispatch if requested
      let emailResultSummary = { sent: 0, failed: 0, recipients: [] as string[] };
      if (req.body.send_email) {
        let emailTargets: { name: string; email: string }[] = [];

        if (recipient_type === 'user' && recipient_id) {
          const userTarget = db.prepare("SELECT nom, email FROM utilisateurs WHERE id = ?").get(recipient_id) as any;
          if (userTarget?.email) {
            emailTargets.push({ name: userTarget.nom, email: userTarget.email });
          }
        } else if (recipient_type === 'all_teachers') {
          const teachers = db.prepare("SELECT nom, email FROM enseignants WHERE school_id = ? AND email IS NOT NULL").all(schoolId) as any[];
          for (const t of teachers) {
            if (t.email && t.email.includes('@')) emailTargets.push({ name: t.nom, email: t.email });
          }
        } else if (recipient_type === 'class_parents' && classe_id) {
          const classParents = db.prepare("SELECT DISTINCT nom_parent as nom, email_parent as email FROM eleves WHERE classe_id = ? AND school_id = ? AND email_parent IS NOT NULL").all(classe_id, schoolId) as any[];
          for (const p of classParents) {
            if (p.email && p.email.includes('@')) emailTargets.push({ name: p.nom || 'Parent d\'élève', email: p.email });
          }
        } else if (recipient_type === 'all_parents') {
          const allParents = db.prepare("SELECT DISTINCT nom_parent as nom, email_parent as email FROM eleves WHERE school_id = ? AND email_parent IS NOT NULL").all(schoolId) as any[];
          for (const p of allParents) {
            if (p.email && p.email.includes('@')) emailTargets.push({ name: p.nom || 'Parent d\'élève', email: p.email });
          }
        } else if (recipient_type === 'role' && recipient_role) {
          const roleUsers = db.prepare("SELECT nom, email FROM utilisateurs WHERE role = ? AND school_id = ? AND email IS NOT NULL").all(recipient_role, schoolId) as any[];
          for (const u of roleUsers) {
            if (u.email && u.email.includes('@')) emailTargets.push({ name: u.nom, email: u.email });
          }
        }

        // Deduplicate destination email addresses
        const uniqueEmails = new Map<string, string>();
        for (const t of emailTargets) {
          const cleanEmail = t.email.trim().toLowerCase();
          if (cleanEmail && !uniqueEmails.has(cleanEmail)) {
            uniqueEmails.set(cleanEmail, t.name);
          }
        }

        const emailSubject = subject || `Nouveau message de ${senderName} - MégafixaEduc Pro`;
        for (const [em, destName] of uniqueEmails) {
          try {
            const mailRes = await sendMailWithFallback({
              to: em,
              subject: emailSubject,
              text: `Bonjour ${destName},\n\nVous avez reçu un nouveau message sur votre espace MégafixaEduc Pro :\n\nExpéditeur : ${senderName}\nObjet : ${emailSubject}\n\nMessage :\n${content || ''}\n\nPour consulter ce message et y répondre, connectez-vous sur votre espace sécurisé : ${APP_URL}/messagerie\n\nCordialement,\nL'équipe administrative`,
              html: `
                <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px;">
                  <div style="border-bottom: 2px solid #10b981; padding-bottom: 12px; margin-bottom: 20px;">
                    <h2 style="color: #0f172a; margin: 0; font-size: 20px;">Mégafixa<span style="color: #10b981;">Educ</span> Pro</h2>
                    <p style="color: #64748b; font-size: 12px; margin: 4px 0 0 0;">Messagerie Officielle & Notifications</p>
                  </div>
                  <p style="color: #334155; font-size: 14px; margin-bottom: 16px;">
                    Bonjour <strong>${destName}</strong>,<br/>
                    Vous avez reçu un nouveau message de <strong>${senderName}</strong> sur votre espace MégafixaEduc Pro.
                  </p>
                  <div style="background: #f8fafc; border-left: 4px solid #10b981; padding: 16px; border-radius: 8px; margin: 20px 0; font-size: 14px; color: #1e293b; line-height: 1.6;">
                    ${(content || '').replace(/\n/g, '<br/>')}
                  </div>
                  <div style="text-align: center; margin: 28px 0;">
                    <a href="${APP_URL}/messagerie" style="display: inline-block; padding: 12px 24px; background: #10b981; color: #ffffff; text-decoration: none; border-radius: 12px; font-weight: bold; font-size: 14px; box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);">
                      Accéder à la Messagerie pour Répondre
                    </a>
                  </div>
                  <div style="margin-top: 32px; padding-top: 16px; border-top: 1px solid #f1f5f9; text-align: center; color: #94a3b8; font-size: 11px;">
                    Ce message vous a été adressé via la plateforme numérique MégafixaEduc Pro.<br>
                    © ${new Date().getFullYear()} Mégafixa Technologies SARL. Tous droits réservés.
                  </div>
                </div>
              `
            });

            if (mailRes.success && !mailRes.simulated) {
              emailResultSummary.sent++;
              emailResultSummary.recipients.push(em);
            } else {
              emailResultSummary.failed++;
            }
          } catch (e) {
            emailResultSummary.failed++;
          }
        }
      }

      res.json({
        success: true,
        messageId,
        smsResult: send_sms ? smsResultSummary : null,
        emailResult: req.body.send_email ? emailResultSummary : null
      });
    } catch (err: any) {
      console.error("Send message error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Mark all conversation messages as read
  app.post("/api/messagerie/read", authenticateToken, (req: any, res) => {
    try {
      const currentUserId = req.userId;
      const { messageIds } = req.body;

      if (Array.isArray(messageIds) && messageIds.length > 0) {
        const insertStmt = db.prepare("INSERT OR IGNORE INTO message_lectures (message_id, user_id) VALUES (?, ?)");
        db.transaction(() => {
          for (const mid of messageIds) {
            insertStmt.run(mid, currentUserId);
          }
        })();
      }
      res.json({ success: true });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // Generic File Upload for Messaging
  app.post("/api/messagerie/upload-file", async (req: any, res) => {
    try {
      const { fileData, fileName } = req.body || {};
      if (!fileData || typeof fileData !== 'string') {
        return res.status(400).json({ error: "Données du fichier manquantes ou invalides." });
      }

      const uploadsDir = path.join(process.cwd(), 'public', 'uploads', 'files');
      if (!fs.existsSync(uploadsDir)) {
        fs.mkdirSync(uploadsDir, { recursive: true });
      }

      const randomSuffix = crypto.randomBytes(6).toString('hex');
      const safeExt = (fileName && fileName.includes('.')) ? fileName.split('.').pop() : 'bin';
      const originalName = fileName ? fileName.split('.')[0] : 'file';
      const name = `${originalName.replace(/[^a-zA-Z0-9_-]/g, '_')}_${randomSuffix}.${safeExt}`;
      const filePath = path.join(uploadsDir, name);
      
      const base64Data = fileData.includes(',') ? fileData.split(',')[1] : fileData;
      const cleanBase64 = (base64Data || '').replace(/\s+/g, '');
      const buffer = Buffer.from(cleanBase64, 'base64');
      
      if (buffer.length === 0) {
        return res.status(400).json({ error: "Le fichier envoyé est vide." });
      }

      fs.writeFileSync(filePath, buffer);

      // Mirror to dist if exists
      const distUploadsDir = path.join(process.cwd(), 'dist', 'uploads', 'files');
      if (fs.existsSync(path.join(process.cwd(), 'dist'))) {
        try {
          if (!fs.existsSync(distUploadsDir)) fs.mkdirSync(distUploadsDir, { recursive: true });
          fs.writeFileSync(path.join(distUploadsDir, name), buffer);
        } catch (e) {}
      }

      const fileUrl = `/uploads/files/${name}`;
      res.json({ success: true, url: fileUrl, fileName: fileName || name });
    } catch (err: any) {
      console.error("File upload error:", err);
      res.status(500).json({ error: "Erreur lors de l'enregistrement du fichier: " + err.message });
    }
  });

  // Audio Upload for Voice Messages (Legacy / Dedicated)
  app.post("/api/messagerie/upload-audio", async (req: any, res) => {
    try {
      const { audioData, fileName } = req.body || {};
      if (!audioData || typeof audioData !== 'string') {
        return res.status(400).json({ error: "Données audio manquantes ou invalides." });
      }

      const uploadsDir = path.join(process.cwd(), 'public', 'uploads', 'audio');
      if (!fs.existsSync(uploadsDir)) {
        fs.mkdirSync(uploadsDir, { recursive: true });
      }

      const randomSuffix = crypto.randomBytes(6).toString('hex');
      const safeExt = (fileName && fileName.includes('.')) ? fileName.split('.').pop() : 'webm';
      const name = fileName 
        ? `${fileName.split('.')[0].replace(/[^a-zA-Z0-9_-]/g, '_')}_${randomSuffix}.${safeExt}`
        : `voice_${randomSuffix}_${Date.now()}.${safeExt}`;
      const filePath = path.join(uploadsDir, name);
      
      // Remove data URL prefix if present (any audio MIME type or parameter)
      const base64Data = audioData.includes(',') ? audioData.split(',')[1] : audioData;
      const cleanBase64 = (base64Data || '').replace(/\s+/g, '');
      const audioBuffer = Buffer.from(cleanBase64, 'base64');
      
      if (audioBuffer.length === 0) {
        return res.status(400).json({ error: "Le fichier audio envoyé est vide." });
      }

      fs.writeFileSync(filePath, audioBuffer);

      // Mirror to dist if dist exists for static build serving
      const distUploadsDir = path.join(process.cwd(), 'dist', 'uploads', 'audio');
      if (fs.existsSync(path.join(process.cwd(), 'dist'))) {
        try {
          if (!fs.existsSync(distUploadsDir)) fs.mkdirSync(distUploadsDir, { recursive: true });
          fs.writeFileSync(path.join(distUploadsDir, name), audioBuffer);
        } catch (e) {}
      }

      const fileUrl = `/uploads/audio/${name}`;
      res.json({ success: true, url: fileUrl });
    } catch (err: any) {
      console.error("Audio upload error:", err);
      res.status(500).json({ error: "Erreur lors de l'enregistrement de l'audio: " + err.message });
    }
  });

  // Send direct quick SMS (for alerts, reminders, absences, fees)
  app.post("/api/sms/send", authenticateToken, async (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const senderId = req.userId;
      const { recipients, message, category } = req.body;

      if (!message || !message.trim()) {
        return res.status(400).json({ error: "Le message SMS ne peut pas être vide." });
      }

      if (!Array.isArray(recipients) || recipients.length === 0) {
        return res.status(400).json({ error: "Veuillez spécifier au moins un destinataire." });
      }

      let sentCount = 0;
      let failedCount = 0;

      for (const rec of recipients) {
        const phone = typeof rec === 'string' ? rec : rec.phone || rec.telephone;
        const name = typeof rec === 'string' ? 'Destinataire' : rec.name || rec.nom || 'Destinataire';
        const type = typeof rec === 'string' ? (category || 'parent') : rec.type || category || 'parent';

        if (phone && phone.replace(/[^0-9]/g, '').length >= 8) {
          const sendRes = await sendSmsService(schoolId, senderId, phone, name, type, message.trim());
          if (sendRes.success) {
            sentCount++;
          } else {
            failedCount++;
          }
        }
      }

      res.json({
        success: true,
        sent: sentCount,
        failed: failedCount
      });
    } catch (err: any) {
      console.error("Direct SMS error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // Get SMS logs & statistics
  app.get("/api/sms/logs", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      const { annee_id } = req.query;

      let logsQuery = `
        SELECT l.*, u.nom as sender_name
        FROM sms_logs l
        LEFT JOIN utilisateurs u ON l.sender_id = u.id
        WHERE l.school_id = ?
      `;
      const logsParams: any[] = [schoolId];

      let statsQuery = `
        SELECT 
          COUNT(*) as total_sms,
          SUM(CASE WHEN status IN ('sent', 'delivered', 'simulated') THEN 1 ELSE 0 END) as total_success,
          SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END) as total_failed,
          SUM(cost_estimate) as total_cost
        FROM sms_logs
        WHERE school_id = ?
      `;
      const statsParams: any[] = [schoolId];

      if (annee_id && annee_id !== 'all') {
        logsQuery += " AND l.annee_id = ?";
        logsParams.push(annee_id);
        statsQuery += " AND annee_id = ?";
        statsParams.push(annee_id);
      }

      logsQuery += " ORDER BY l.created_at DESC LIMIT 200";

      const logs = db.prepare(logsQuery).all(...logsParams);
      const stats = db.prepare(statsQuery).get(...statsParams);

      res.json({ logs, stats });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // Get and Update SMS configuration
  app.get("/api/sms/config", authenticateToken, (req: any, res) => {
    try {
      const schoolId = req.schoolId || 1;
      let config = db.prepare("SELECT * FROM sms_configs WHERE school_id = ?").get(schoolId) as any;
      if (!config) {
        db.prepare("INSERT INTO sms_configs (school_id, provider, is_active, credit_balance) VALUES (?, 'simulation', 1, 1000)").run(schoolId);
        config = db.prepare("SELECT * FROM sms_configs WHERE school_id = ?").get(schoolId);
      }
      res.json(config);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  app.put("/api/sms/config", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }

      const schoolId = req.schoolId || 1;
      const {
        provider,
        is_active,
        account_sid,
        auth_token,
        sender_number_or_name,
        api_url,
        api_key,
        custom_headers,
        credit_balance
      } = req.body;

      const existing = db.prepare("SELECT id FROM sms_configs WHERE school_id = ?").get(schoolId);
      if (existing) {
        db.prepare(`
          UPDATE sms_configs SET
            provider = ?,
            is_active = ?,
            account_sid = ?,
            auth_token = ?,
            sender_number_or_name = ?,
            api_url = ?,
            api_key = ?,
            custom_headers = ?,
            credit_balance = ?,
            updated_at = CURRENT_TIMESTAMP
          WHERE school_id = ?
        `).run(
          provider || 'simulation',
          is_active !== undefined ? (is_active ? 1 : 0) : 1,
          account_sid || '',
          auth_token || '',
          sender_number_or_name || 'MEGAFIXA',
          api_url || '',
          api_key || '',
          custom_headers || '',
          credit_balance !== undefined ? credit_balance : 1000,
          schoolId
        );
      } else {
        db.prepare(`
          INSERT INTO sms_configs (
            school_id, provider, is_active, account_sid, auth_token,
            sender_number_or_name, api_url, api_key, custom_headers, credit_balance
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).run(
          schoolId,
          provider || 'simulation',
          is_active !== undefined ? (is_active ? 1 : 0) : 1,
          account_sid || '',
          auth_token || '',
          sender_number_or_name || 'MEGAFIXA',
          api_url || '',
          api_key || '',
          custom_headers || '',
          credit_balance !== undefined ? credit_balance : 1000
        );
      }

      res.json({ success: true, message: "Configuration SMS enregistrée avec succès." });
    } catch (err: any) {
      console.error("Update SMS config error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // ==========================================
  // SAUVEGARDE ET RESTAURATION DES DONNÉES
  // ==========================================
  const BACKUPS_DIR = path.join(process.cwd(), 'backups');
  if (!fs.existsSync(BACKUPS_DIR)) {
    try {
      fs.mkdirSync(BACKUPS_DIR, { recursive: true });
    } catch (e) {
      console.error("Failed to create backups directory:", e);
    }
  }

  function ensureSchoolBackupConfig(schoolId: number) {
    let conf = db.prepare("SELECT * FROM backup_configurations WHERE school_id = ?").get(schoolId) as any;
    if (!conf) {
      db.prepare(`
        INSERT INTO backup_configurations (
          school_id, auto_backup_enabled, frequency, backup_time, retention_count,
          include_users, include_students, include_grades, include_financials,
          include_documents, include_audit_logs, encryption_enabled, storage_location,
          cloud_provider, notification_email, notify_on_success, notify_on_failure
        ) VALUES (?, 1, 'daily', '02:00', 14, 1, 1, 1, 1, 1, 1, 0, 'local_and_cloud', 'firestore_snapshot', '', 0, 1)
      `).run(schoolId);
      conf = db.prepare("SELECT * FROM backup_configurations WHERE school_id = ?").get(schoolId) as any;
    }
    return conf;
  }

  async function performBackupSnapshot({
    schoolId,
    backupType = 'full',
    format = 'sql',
    label,
    createdBy,
    notes
  }: {
    schoolId: number;
    backupType?: string;
    format?: string;
    label?: string;
    createdBy?: number | null;
    notes?: string;
  }) {
    const school = db.prepare("SELECT * FROM school_info WHERE id = ?").get(schoolId) as any;
    const schoolName = school?.nom || `Ecole_${schoolId}`;
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const safeSchoolName = schoolName.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 20);
    const filename = `backup_${safeSchoolName}_${backupType}_${timestamp}.${format}`;
    const filePath = path.join(BACKUPS_DIR, filename);

    // Determine tables according to backupType
    let tablesToExport: string[] = [];
    const allTables = (db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").all() as any[]).map(t => t.name);

    if (backupType === 'users_only') {
      tablesToExport = allTables.filter(t => ['utilisateurs', 'role_permissions', 'audit_logs'].includes(t));
    } else if (backupType === 'pedagogical') {
      tablesToExport = allTables.filter(t => ['annees_scolaires', 'classes', 'eleves', 'enseignants', 'matieres', 'notes', 'evaluation_configs', 'suivi_eleves', 'bulletin_headers'].includes(t));
    } else if (backupType === 'financial') {
      tablesToExport = allTables.filter(t => ['paiements', 'salaires_enseignants', 'frais_scolaires_config', 'school_payment_methods'].includes(t));
    } else {
      // Full backup (all application tables)
      tablesToExport = allTables.filter(t => t !== 'backup_snapshots');
    }

    const counts: Record<string, number> = {};
    let totalRecords = 0;

    if (format === 'json') {
      const exportData: Record<string, any> = {
        meta: {
          app: "MégafixaEduc Pro",
          version: "2.5.0",
          export_date: new Date().toISOString(),
          school_id: schoolId,
          school_name: schoolName,
          backup_type: backupType,
          format: 'json'
        },
        entities: {}
      };

      for (const table of tablesToExport) {
        const columnsInfo = db.prepare(`PRAGMA table_info(${table})`).all() as any[];
        const hasSchoolId = columnsInfo.some(col => col.name === 'school_id');

        let rows: any[] = [];
        if (hasSchoolId) {
          rows = db.prepare(`SELECT * FROM ${table} WHERE school_id = ?`).all(schoolId);
        } else if (table === 'school_info') {
          rows = db.prepare(`SELECT * FROM ${table} WHERE id = ?`).all(schoolId);
        } else if (['utilisateurs', 'role_permissions'].includes(table)) {
          rows = db.prepare(`SELECT * FROM ${table} WHERE school_id = ? OR school_id IS NULL`).all(schoolId);
        }

        exportData.entities[table] = rows;
        counts[table] = rows.length;
        totalRecords += rows.length;
      }

      const content = JSON.stringify(exportData, null, 2);
      fs.writeFileSync(filePath, content, 'utf-8');
    } else {
      // SQL dump format
      let sqlDump = `-- MégafixaEduc Pro Database Backup\n`;
      sqlDump += `-- School: ${schoolName} (ID: ${schoolId})\n`;
      sqlDump += `-- Date: ${new Date().toISOString()}\n`;
      sqlDump += `-- Backup Type: ${backupType}\n\n`;
      sqlDump += "PRAGMA foreign_keys=OFF;\n";
      sqlDump += "BEGIN TRANSACTION;\n\n";

      for (const table of tablesToExport) {
        const columnsInfo = db.prepare(`PRAGMA table_info(${table})`).all() as any[];
        const hasSchoolId = columnsInfo.some(col => col.name === 'school_id');

        let rows: any[] = [];
        if (hasSchoolId) {
          rows = db.prepare(`SELECT * FROM ${table} WHERE school_id = ?`).all(schoolId);
        } else if (table === 'school_info') {
          rows = db.prepare(`SELECT * FROM ${table} WHERE id = ?`).all(schoolId);
        } else if (['utilisateurs', 'role_permissions'].includes(table)) {
          rows = db.prepare(`SELECT * FROM ${table} WHERE school_id = ? OR school_id IS NULL`).all(schoolId);
        }

        counts[table] = rows.length;
        totalRecords += rows.length;

        if (rows.length > 0) {
          sqlDump += `-- Table: ${table} (${rows.length} rows)\n`;
          for (const row of rows) {
            const cols = Object.keys(row);
            const vals = cols.map(c => {
              const v = row[c];
              if (v === null || v === undefined) return "NULL";
              if (typeof v === 'string') return `'${v.replace(/'/g, "''")}'`;
              return v;
            });
            sqlDump += `INSERT OR REPLACE INTO ${table} (${cols.join(", ")}) VALUES (${vals.join(", ")});\n`;
          }
          sqlDump += "\n";
        }
      }

      sqlDump += "COMMIT;\n";
      sqlDump += "PRAGMA foreign_keys=ON;\n";

      fs.writeFileSync(filePath, sqlDump, 'utf-8');
    }

    const stats = fs.statSync(filePath);
    const fileBuffer = fs.readFileSync(filePath);
    const checksum = crypto.createHash('sha256').update(fileBuffer).digest('hex');

    const result = db.prepare(`
      INSERT INTO backup_snapshots (
        school_id, filename, label, backup_type, format, size_bytes,
        entities_count, status, storage_path, checksum_sha256, created_by, notes
      ) VALUES (?, ?, ?, ?, ?, ?, ?, 'completed', ?, ?, ?, ?)
    `).run(
      schoolId,
      filename,
      label || `Sauvegarde ${backupType === 'users_only' ? 'Utilisateurs' : backupType === 'full' ? 'Complète' : backupType} (${new Date().toLocaleDateString('fr-FR')})`,
      backupType,
      format,
      stats.size,
      JSON.stringify(counts),
      filePath,
      checksum,
      createdBy || null,
      notes || `Sauvegarde générée avec ${totalRecords} enregistrements`
    );

    const snapshotId = Number(result.lastInsertRowid);

    // Reinforce: Sync metadata to Firebase if available
    if (adminDb) {
      try {
        await adminDb.collection('backups').doc(`school_${schoolId}_${snapshotId}`).set({
          school_id: schoolId,
          snapshot_id: snapshotId,
          filename,
          label: label || `Sauvegarde`,
          backup_type: backupType,
          format,
          size_bytes: stats.size,
          checksum_sha256: checksum,
          created_at: new Date().toISOString(),
          status: 'completed',
          storage_location: 'local_server'
        });
        console.log(`[Backup] Snapshot ${snapshotId} synced to Cloud Firestore.`);
      } catch (cloudErr) {
        console.warn("[Backup] Cloud sync notice:", cloudErr);
      }
    }

    // Update config stats
    const sizeDisplay = stats.size > 1024 * 1024 
      ? `${(stats.size / (1024 * 1024)).toFixed(2)} Mo`
      : `${(stats.size / 1024).toFixed(1)} Ko`;

    db.prepare(`
      UPDATE backup_configurations SET
        last_backup_at = CURRENT_TIMESTAMP,
        last_backup_status = 'success',
        last_backup_size = ?,
        updated_at = CURRENT_TIMESTAMP
      WHERE school_id = ?
    `).run(sizeDisplay, schoolId);

    // Cleanup older snapshots if retention exceeded
    const config = ensureSchoolBackupConfig(schoolId);
    const retention = config.retention_count || 14;
    const snapshots = db.prepare(`
      SELECT id, storage_path FROM backup_snapshots 
      WHERE school_id = ? AND backup_type = 'automated'
      ORDER BY created_at DESC
    `).all(schoolId) as any[];

    if (snapshots.length > retention) {
      const toDelete = snapshots.slice(retention);
      for (const s of toDelete) {
        try {
          if (s.storage_path && fs.existsSync(s.storage_path)) {
            fs.unlinkSync(s.storage_path);
          }
        } catch (delErr) {
          console.error("Failed to delete expired backup file:", delErr);
        }
        db.prepare("DELETE FROM backup_snapshots WHERE id = ?").run(s.id);
      }
    }

    logActivity(createdBy || 1, 'CREATE_BACKUP', 'backup_snapshots', snapshotId, { filename, backupType, format, size: stats.size }, schoolId);

    return db.prepare("SELECT * FROM backup_snapshots WHERE id = ?").get(snapshotId);
  }

  // GET backup config
  app.get("/api/backups/config", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }
      const schoolId = req.schoolId || 1;
      const config = ensureSchoolBackupConfig(schoolId);
      res.json(config);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // PUT backup config
  app.put("/api/backups/config", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }
      const schoolId = req.schoolId || 1;
      const {
        auto_backup_enabled,
        frequency,
        backup_time,
        retention_count,
        include_users,
        include_students,
        include_grades,
        include_financials,
        include_documents,
        include_audit_logs,
        encryption_enabled,
        storage_location,
        cloud_provider,
        cloud_endpoint,
        cloud_api_key,
        notification_email,
        notify_on_success,
        notify_on_failure
      } = req.body;

      ensureSchoolBackupConfig(schoolId);

      db.prepare(`
        UPDATE backup_configurations SET
          auto_backup_enabled = ?,
          frequency = ?,
          backup_time = ?,
          retention_count = ?,
          include_users = ?,
          include_students = ?,
          include_grades = ?,
          include_financials = ?,
          include_documents = ?,
          include_audit_logs = ?,
          encryption_enabled = ?,
          storage_location = ?,
          cloud_provider = ?,
          cloud_endpoint = ?,
          cloud_api_key = ?,
          notification_email = ?,
          notify_on_success = ?,
          notify_on_failure = ?,
          updated_at = CURRENT_TIMESTAMP
        WHERE school_id = ?
      `).run(
        auto_backup_enabled !== undefined ? (auto_backup_enabled ? 1 : 0) : 1,
        frequency || 'daily',
        backup_time || '02:00',
        retention_count !== undefined ? Number(retention_count) : 14,
        include_users !== undefined ? (include_users ? 1 : 0) : 1,
        include_students !== undefined ? (include_students ? 1 : 0) : 1,
        include_grades !== undefined ? (include_grades ? 1 : 0) : 1,
        include_financials !== undefined ? (include_financials ? 1 : 0) : 1,
        include_documents !== undefined ? (include_documents ? 1 : 0) : 1,
        include_audit_logs !== undefined ? (include_audit_logs ? 1 : 0) : 1,
        encryption_enabled !== undefined ? (encryption_enabled ? 1 : 0) : 0,
        storage_location || 'local_and_cloud',
        cloud_provider || 'firestore_snapshot',
        cloud_endpoint || '',
        cloud_api_key || '',
        notification_email || '',
        notify_on_success !== undefined ? (notify_on_success ? 1 : 0) : 0,
        notify_on_failure !== undefined ? (notify_on_failure ? 1 : 0) : 1,
        schoolId
      );

      logActivity(req.userId, 'UPDATE_BACKUP_CONFIG', 'backup_configurations', null, { frequency, auto_backup_enabled }, schoolId);
      res.json({ success: true, message: "Configuration des sauvegardes mise à jour avec succès." });
    } catch (err: any) {
      console.error("Update backup config error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // GET snapshots list
  app.get("/api/backups/snapshots", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }
      const schoolId = req.schoolId || 1;
      const snapshots = db.prepare(`
        SELECT s.*, u.nom as created_by_name
        FROM backup_snapshots s
        LEFT JOIN utilisateurs u ON u.id = s.created_by
        WHERE s.school_id = ?
        ORDER BY s.created_at DESC
      `).all(schoolId);

      const totalSize = (snapshots as any[]).reduce((sum, s) => sum + (s.size_bytes || 0), 0);
      const totalSizeDisplay = totalSize > 1024 * 1024 
        ? `${(totalSize / (1024 * 1024)).toFixed(2)} Mo`
        : `${(totalSize / 1024).toFixed(1)} Ko`;

      res.json({
        snapshots,
        summary: {
          count: snapshots.length,
          total_size_bytes: totalSize,
          total_size_display: totalSizeDisplay,
          last_backup: snapshots.length > 0 ? snapshots[0] : null
        }
      });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // POST create manual backup
  app.post("/api/backups/create", authenticateToken, async (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }
      const schoolId = req.schoolId || 1;
      const { backup_type, format, label, notes } = req.body;

      const snapshot = await performBackupSnapshot({
        schoolId,
        backupType: backup_type || 'full',
        format: format || 'sql',
        label: label || undefined,
        createdBy: req.userId,
        notes: notes || undefined
      });

      res.json({ success: true, message: "Sauvegarde créée avec succès.", snapshot });
    } catch (err: any) {
      console.error("Create backup snapshot error:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // GET download backup file
  app.get("/api/backups/download/:id", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }
      const schoolId = req.schoolId || 1;
      const snapshot = db.prepare("SELECT * FROM backup_snapshots WHERE id = ? AND school_id = ?").get(req.params.id, schoolId) as any;
      if (!snapshot) {
        return res.status(404).json({ error: "Fichier de sauvegarde introuvable." });
      }

      const filePath = snapshot.storage_path || path.join(BACKUPS_DIR, snapshot.filename);
      if (!fs.existsSync(filePath)) {
        return res.status(404).json({ error: "Le fichier physique est manquant sur le serveur." });
      }

      res.setHeader('Content-Disposition', `attachment; filename="${snapshot.filename}"`);
      res.setHeader('Content-Type', snapshot.format === 'json' ? 'application/json' : 'text/plain');
      fs.createReadStream(filePath).pipe(res);
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  // GET download compressed code ZIP (< 25MB)
  app.get("/api/code/download-zip", (req: any, res) => {
    try {
      const zipPath = path.join(process.cwd(), "megafixaeduc-code.zip");
      const scriptPath = path.join(process.cwd(), "scripts", "create-zip.py");

      const sendZip = () => {
        if (!fs.existsSync(zipPath)) {
          return res.status(404).json({ error: "Fichier ZIP introuvable." });
        }
        const stat = fs.statSync(zipPath);
        res.setHeader('Content-Disposition', 'attachment; filename="megafixaeduc-code.zip"');
        res.setHeader('Content-Type', 'application/zip');
        res.setHeader('Content-Length', stat.size);
        fs.createReadStream(zipPath).pipe(res);
      };

      if (!fs.existsSync(zipPath)) {
        const { execSync } = require('child_process');
        execSync(`python3 "${scriptPath}"`, { stdio: 'inherit' });
      }
      sendZip();
    } catch (err: any) {
      console.error("Error sending zip:", err);
      res.status(500).json({ error: err.message });
    }
  });

  // POST direct 1-click push to GitHub with auto-creation of repo
  app.post("/api/github/push-direct", async (req: any, res) => {
    try {
      const { token, repoName = "megafixaeduc-pro", isPrivate = false } = req.body;
      const cleanToken = (token || "").trim();
      const cleanRepo = (repoName || "megafixaeduc-pro").trim().toLowerCase().replace(/[^a-z0-9_-]/g, '-');

      if (!cleanToken) {
        return res.status(400).json({ success: false, error: "Le jeton d'accès GitHub (Token) est obligatoire." });
      }

      // 1. Verify user with GitHub API
      const userRes = await fetch("https://api.github.com/user", {
        headers: {
          "Authorization": `Bearer ${cleanToken}`,
          "Accept": "application/vnd.github.v3+json",
          "User-Agent": "MegaFixaEduc-App"
        }
      });

      if (!userRes.ok) {
        return res.status(401).json({ 
          success: false, 
          error: "Jeton GitHub invalide ou expiré. Vérifiez que votre token a bien les autorisations 'repo'." 
        });
      }

      const userData: any = await userRes.json();
      const owner = userData.login;

      // 2. Try to create the repository if it doesn't already exist
      const createRepoRes = await fetch("https://api.github.com/user/repos", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${cleanToken}`,
          "Accept": "application/vnd.github.v3+json",
          "User-Agent": "MegaFixaEduc-App",
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          name: cleanRepo,
          description: "MégafixaEduc Pro - Système de Gestion Scolaire",
          private: !!isPrivate,
          auto_init: false
        })
      });

      if (!createRepoRes.ok && createRepoRes.status !== 422) {
        const errJson: any = await createRepoRes.json().catch(() => ({}));
        console.warn("GitHub repo creation notice:", errJson);
      }

      // 3. Prepare git commit and push
      const { execSync } = require('child_process');
      const rootDir = process.cwd();

      execSync(`git config --global --add safe.directory /app/applet 2>/dev/null || true`, { cwd: rootDir });
      execSync(`git config --global --add safe.directory "*" 2>/dev/null || true`, { cwd: rootDir });
      execSync(`git config user.name "${owner}"`, { cwd: rootDir });
      execSync(`git config user.email "${owner}@users.noreply.github.com"`, { cwd: rootDir });
      
      try {
        execSync(`git rev-parse --is-inside-work-tree`, { cwd: rootDir });
      } catch (e) {
        execSync(`git init -b main`, { cwd: rootDir });
      }

      execSync(`git add .`, { cwd: rootDir });
      try {
        execSync(`git commit -m "feat: release MégafixaEduc Pro ready for Render & GitHub"`, { cwd: rootDir });
      } catch (e) {
        // Already committed
      }

      execSync(`git branch -M main`, { cwd: rootDir });
      execSync(`git remote remove origin 2>/dev/null || true`, { cwd: rootDir });
      
      const remoteUrl = `https://${cleanToken}@github.com/${owner}/${cleanRepo}.git`;
      execSync(`git remote add origin "${remoteUrl}"`, { cwd: rootDir });
      execSync(`git push -u origin main --force`, { cwd: rootDir });

      const publicRepoUrl = `https://github.com/${owner}/${cleanRepo}`;
      return res.json({
        success: true,
        message: "Projet publié avec succès sur GitHub !",
        repoUrl: publicRepoUrl,
        owner,
        repoName: cleanRepo
      });
    } catch (err: any) {
      console.error("Error pushing to GitHub:", err);
      return res.status(500).json({ 
        success: false, 
        error: `Erreur lors de la publication vers GitHub: ${err.message}` 
      });
    }
  });

  // POST restore backup snapshot
  app.post("/api/backups/restore/:id", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }
      const schoolId = req.schoolId || 1;
      const snapshot = db.prepare("SELECT * FROM backup_snapshots WHERE id = ? AND school_id = ?").get(req.params.id, schoolId) as any;
      if (!snapshot) {
        return res.status(404).json({ error: "Sauvegarde introuvable." });
      }

      const filePath = snapshot.storage_path || path.join(BACKUPS_DIR, snapshot.filename);
      if (!fs.existsSync(filePath)) {
        return res.status(404).json({ error: "Fichier physique de sauvegarde introuvable sur le disque." });
      }

      const fileContent = fs.readFileSync(filePath, 'utf-8');

      if (snapshot.format === 'json') {
        const parsed = JSON.parse(fileContent);
        if (!parsed.entities) {
          return res.status(400).json({ error: "Format JSON de sauvegarde invalide (clé 'entities' manquante)." });
        }

        const restoreTransaction = db.transaction(() => {
          for (const [table, rows] of Object.entries(parsed.entities) as [string, any[]][]) {
            if (!Array.isArray(rows) || rows.length === 0) continue;
            for (const row of rows) {
              const cols = Object.keys(row);
              const placeholders = cols.map(() => '?').join(', ');
              const values = cols.map(c => row[c]);
              db.prepare(`INSERT OR REPLACE INTO ${table} (${cols.join(', ')}) VALUES (${placeholders})`).run(...values);
            }
          }
        });
        restoreTransaction();
      } else {
        // SQL restore
        const statements = fileContent
          .split(';\n')
          .map(s => s.trim())
          .filter(s => s.length > 0 && !s.startsWith('--') && !s.startsWith('PRAGMA') && !s.startsWith('BEGIN') && !s.startsWith('COMMIT'));

        const restoreTransaction = db.transaction(() => {
          for (const stmt of statements) {
            try {
              db.exec(stmt);
            } catch (stmtErr: any) {
              console.warn(`[Restore Warning] Skipped or failed statement: ${stmt.substring(0, 50)}...`, stmtErr.message);
            }
          }
        });
        restoreTransaction();
      }

      db.prepare("UPDATE backup_snapshots SET restored_at = CURRENT_TIMESTAMP WHERE id = ?").run(snapshot.id);
      logActivity(req.userId, 'RESTORE_BACKUP', 'backup_snapshots', snapshot.id, { filename: snapshot.filename }, schoolId);

      res.json({ success: true, message: "Données restaurées avec succès depuis l'archive de sauvegarde." });
    } catch (err: any) {
      console.error("Restore backup error:", err);
      res.status(500).json({ error: "Erreur lors de la restauration: " + err.message });
    }
  });

  // POST upload & restore backup file
  app.post("/api/backups/upload-restore", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }
      const schoolId = req.schoolId || 1;
      const { file_content, file_name, file_format } = req.body;

      if (!file_content) {
        return res.status(400).json({ error: "Contenu du fichier de sauvegarde manquant." });
      }

      const format = file_format || (file_name?.endsWith('.json') ? 'json' : 'sql');

      if (format === 'json') {
        const parsed = typeof file_content === 'string' ? JSON.parse(file_content) : file_content;
        if (!parsed.entities) {
          return res.status(400).json({ error: "Format JSON non reconnu pour une sauvegarde MégafixaEduc." });
        }

        const restoreTransaction = db.transaction(() => {
          for (const [table, rows] of Object.entries(parsed.entities) as [string, any[]][]) {
            if (!Array.isArray(rows) || rows.length === 0) continue;
            for (const row of rows) {
              const cols = Object.keys(row);
              const placeholders = cols.map(() => '?').join(', ');
              const values = cols.map(c => row[c]);
              db.prepare(`INSERT OR REPLACE INTO ${table} (${cols.join(', ')}) VALUES (${placeholders})`).run(...values);
            }
          }
        });
        restoreTransaction();
      } else {
        const statements = file_content
          .split(';\n')
          .map((s: string) => s.trim())
          .filter((s: string) => s.length > 0 && !s.startsWith('--') && !s.startsWith('PRAGMA') && !s.startsWith('BEGIN') && !s.startsWith('COMMIT'));

        const restoreTransaction = db.transaction(() => {
          for (const stmt of statements) {
            try {
              db.exec(stmt);
            } catch (stmtErr: any) {
              console.warn(`[Upload-Restore Warning]:`, stmtErr.message);
            }
          }
        });
        restoreTransaction();
      }

      logActivity(req.userId, 'UPLOAD_RESTORE_BACKUP', 'backup_snapshots', null, { file_name, format }, schoolId);
      res.json({ success: true, message: "Fichier de sauvegarde importé et restauré avec succès." });
    } catch (err: any) {
      console.error("Upload restore error:", err);
      res.status(500).json({ error: "Échec de la restauration du fichier: " + err.message });
    }
  });

  // DELETE snapshot
  app.delete("/api/backups/:id", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }
      const schoolId = req.schoolId || 1;
      const snapshot = db.prepare("SELECT * FROM backup_snapshots WHERE id = ? AND school_id = ?").get(req.params.id, schoolId) as any;
      if (!snapshot) {
        return res.status(404).json({ error: "Sauvegarde introuvable." });
      }

      const filePath = snapshot.storage_path || path.join(BACKUPS_DIR, snapshot.filename);
      if (fs.existsSync(filePath)) {
        try {
          fs.unlinkSync(filePath);
        } catch (delErr) {
          console.warn("Could not delete physical file:", delErr);
        }
      }

      db.prepare("DELETE FROM backup_snapshots WHERE id = ?").run(snapshot.id);
      logActivity(req.userId, 'DELETE_BACKUP', 'backup_snapshots', snapshot.id, { filename: snapshot.filename }, schoolId);
      res.json({ success: true, message: "Sauvegarde supprimée avec succès." });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

