  app.get("/api/notes/batch-fetch", authenticateToken, (req: any, res) => {
    try {
      const { classe_id, matiere_id, trimestre, type_evaluation } = req.query;
      const schoolId = req.schoolId || 1;
      const yearId = getActiveYearId(schoolId);
      
      // Handle type_evaluation aliases and sub-types (e.g. D1_NoteObtenue)
      let baseTypes = [type_evaluation];
      if (type_evaluation === 'Dev1' || type_evaluation === 'D1') baseTypes = ['Dev1', 'D1', 'Devoir 1', 'Devoir1', 'devoir_1'];
      if (type_evaluation === 'Dev2' || type_evaluation === 'D2') baseTypes = ['Dev2', 'D2', 'Devoir 2', 'Devoir2', 'devoir_2'];
      if (type_evaluation === 'Composition' || type_evaluation === 'C1') baseTypes = ['Composition', 'C1', 'Compo', 'Examen'];
      if (type_evaluation === 'I1') baseTypes = ['I1', 'Int1', 'Interro1', 'Interrogation 1'];
      if (type_evaluation === 'I2') baseTypes = ['I2', 'Int2', 'Interro2', 'Interrogation 2'];
      if (type_evaluation === 'I3') baseTypes = ['I3', 'Int3', 'Interro3', 'Interrogation 3'];
      if (type_evaluation === 'I4') baseTypes = ['I4', 'Int4', 'Interro4', 'Interrogation 4'];

      // Build a query that matches any of the base types OR types that start with a base type (to handle _NoteObtenue etc)
      // SQLite LIKE can be used
      const queryParts = baseTypes.map(() => "(n.type_evaluation = ? OR n.type_evaluation LIKE ?)");
      const orClause = queryParts.join(" OR ");
      
      const queryParams = [];
      for (const t of baseTypes) {
        queryParams.push(t);
        queryParams.push(`${t}_%`);
      }

      // Get the year associated with this class to ensure strict isolation
      const classe = db.prepare("SELECT annee_id FROM classes WHERE id = ?").get(classe_id) as any;
      if (!classe) return res.json([]);
      const anneeId = classe.annee_id;

      const notes = db.prepare(`
        SELECT n.* 
        FROM notes n
        JOIN eleves e ON n.eleve_id = e.id
        JOIN eleve_annees ea ON e.id = ea.eleve_id AND ea.annee_id = n.annee_id
        WHERE ea.classe_id = ? 
          AND n.matiere_id = ? 
          AND n.trimestre = ? 
          AND (${orClause})
          AND n.annee_id = ?
          AND n.school_id = ?
      `).all(classe_id, matiere_id, trimestre, ...queryParams, anneeId, schoolId);
      
      // Note: We removed the strict yearId check temporarily to see if it helps, 
      // though ideally we should keep it. Let's see if notes show up now.
      res.json(notes);
    } catch (error: any) {
      console.error("Batch fetch error:", error);
      res.status(500).json({ error: error.message });
    }
  });

