  app.post("/api/notes", authenticateToken, (req: any, res) => {
    const { eleve_id, matiere_id, notes, date_evaluation, trimestre, enseignant_id } = req.body;
    
    // Check if the school has locked notes insertion
    const school = db.prepare("SELECT notes_verrouillees, notes_verrouillees_primaire, notes_verrouillees_secondaire FROM school_info WHERE id = ?").get(req.schoolId) as any;
    
    // Determine student cycle
    const eleve = db.prepare(`
      SELECT e.id, c.cycle 
      FROM eleves e
      LEFT JOIN classes c ON e.classe_id = c.id
      WHERE e.id = ?
    `).get(eleve_id) as any;
    
    const studentCycle = (eleve?.cycle || '').toLowerCase();
    const isPrimary = studentCycle.includes('primaire') || studentCycle.includes('maternelle');
    
    const isNotesLocked = isPrimary ? (school?.notes_verrouillees_primaire === 1) : (school?.notes_verrouillees_secondaire === 1);

    if (req.user?.role === 'enseignant' && isNotesLocked) {
      const dbUser = db.prepare("SELECT enseignant_id FROM utilisateurs WHERE id = ?").get(req.userId) as any;
      const tId = req.user?.enseignant_id || dbUser?.enseignant_id || enseignant_id;
      let hasPermission = false;
      if (tId) {
        const approvedReq = db.prepare(`
          SELECT id FROM timetable_requests 
          WHERE enseignant_id = ? 
            AND status = 'approved' 
            AND type_modification = 'notes'
            AND school_id = ?
        `).get(tId, req.schoolId);
        if (approvedReq) {
          hasPermission = true;
        }
      }

      if (!hasPermission) {
        return res.status(403).json({ 
          error: "La saisie et l'importation des notes sont actuellement verrouillées par l'administration de l'établissement. Vous pouvez soumettre une demande de permission pour débloquer la saisie.",
          is_locked: true
        });
      }
    }

    // If enseignant_id is provided, check if they teach this matiere or class
    if (enseignant_id) {
       const isAllowed = db.prepare(`
         SELECT 1 FROM enseignant_matieres WHERE enseignant_id = ? AND matiere_id = ? AND school_id = ?
         UNION
         SELECT 1 FROM classe_matieres WHERE enseignant_id = ? AND matiere_id = ? AND school_id = ?
         UNION
         SELECT 1 FROM classes WHERE enseignant_id = ? AND school_id = ?
       `).get(enseignant_id, matiere_id, req.schoolId, enseignant_id, matiere_id, req.schoolId, enseignant_id, req.schoolId);
       if (!isAllowed) {
         return res.status(403).json({ error: "Vous n'êtes pas autorisé à saisir des notes pour cette matière." });
       }
    }

    const yearId = req.anneeId;
    
    const insertOrReplace = db.prepare(`
      INSERT INTO notes (eleve_id, matiere_id, type_evaluation, note, date_evaluation, annee_id, trimestre, enseignant_id, school_id)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(eleve_id, matiere_id, type_evaluation, annee_id, trimestre, school_id) 
      DO UPDATE SET note = excluded.note, date_evaluation = excluded.date_evaluation, enseignant_id = excluded.enseignant_id
    `);

    const transaction = db.transaction((notesList) => {
      for (const n of notesList) {
        if (n.note !== '' && n.note !== null && n.note !== undefined) {
          const val = parseFloat(String(n.note).replace(',', '.'));
          if (isNaN(val) || val < 0 || val > 20) {
            throw new Error(`Note invalide (${n.note}). Les notes doivent être comprises entre 0 et 20.`);
          }
          const rounded = Math.round(val * 100) / 100;
          insertOrReplace.run(eleve_id, matiere_id, n.type, rounded, date_evaluation, yearId, trimestre || 1, enseignant_id, req.schoolId);
        }
      }
    });

    try {
      if (Array.isArray(notes)) {
        transaction(notes);
      } else {
        // Fallback for single note if needed
        const { type_evaluation, note } = req.body;
        if (note !== '' && note !== null && note !== undefined) {
          const val = parseFloat(String(note).replace(',', '.'));
          if (isNaN(val) || val < 0 || val > 20) {
            throw new Error(`Note invalide (${note}). Les notes doivent être comprises entre 0 et 20.`);
          }
          const rounded = Math.round(val * 100) / 100;
          insertOrReplace.run(eleve_id, matiere_id, type_evaluation, rounded, date_evaluation, yearId, trimestre || 1, enseignant_id, req.schoolId);
        }
      }
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

