  // Statistiques consolidées des restes & arriérés des années antérieures
  app.get("/api/stats/arrieres-anterieurs", authenticateToken, (req: any, res) => {
    const schoolId = req.schoolId || 1;
    const yearId = req.anneeId || getActiveYearId(schoolId);
    const { cycle } = req.query;
    const cycleFilter = getCycleClassSqlFilter(cycle as string | undefined, 'c');

    try {
      const rows = db.prepare(`
        SELECT 
          e.id as eleve_id,
          e.matricule,
          e.nom,
          e.prenom,
          e.photo,
          e.tel_parent,
          c.id as classe_id,
          c.nom as classe_nom,
          c.niveau as classe_niveau,
          COALESCE(ea.arrieres_scolarite, e.arrieres_scolarite, 0) as arrieres_scolarite,
          c.frais_scolarite,
          IFNULL((SELECT SUM(montant) FROM paiements p WHERE p.eleve_id = e.id AND p.annee_id = ? AND p.type_paiement = 'Frais de scolarité' AND (p.status = 'Terminé' OR p.status = 'completed')), 0) as total_paye_scolarite,
          (
            SELECT ea_old.annee_id 
            FROM eleve_annees ea_old 
            WHERE ea_old.eleve_id = e.id AND ea_old.annee_id != ? 
            ORDER BY ea_old.id DESC LIMIT 1
          ) as annee_precedente_id,
          (
            SELECT c_old.nom 
            FROM eleve_annees ea_old 
            JOIN classes c_old ON ea_old.classe_id = c_old.id 
            WHERE ea_old.eleve_id = e.id AND ea_old.annee_id != ? 
            ORDER BY ea_old.id DESC LIMIT 1
          ) as classe_precedente_nom,
          (
            SELECT a_old.libelle 
            FROM eleve_annees ea_old 
            JOIN annees_scolaires a_old ON ea_old.annee_id = a_old.id 
            WHERE ea_old.eleve_id = e.id AND ea_old.annee_id != ? 
            ORDER BY ea_old.id DESC LIMIT 1
          ) as annee_precedente_libelle
        FROM eleves e
        JOIN eleve_annees ea ON e.id = ea.eleve_id
        JOIN classes c ON ea.classe_id = c.id
        WHERE ea.annee_id = ? AND e.school_id = ? ${cycleFilter}
        ORDER BY arrieres_scolarite DESC, c.nom, e.nom
      `).all(yearId, yearId, yearId, yearId, yearId, schoolId) as any[];

      const elevesAvecArrieres = rows.filter(r => Number(r.arrieres_scolarite) > 0);
      const totalArrieres = elevesAvecArrieres.reduce((acc, r) => acc + Number(r.arrieres_scolarite || 0), 0);
      
      const parClasseMap = new Map<string, { classe_id: number, classe_nom: string, total_arrieres: number, nb_eleves: number }>();
      for (const r of elevesAvecArrieres) {
        const cur = parClasseMap.get(r.classe_nom) || { classe_id: r.classe_id, classe_nom: r.classe_nom, total_arrieres: 0, nb_eleves: 0 };
        cur.total_arrieres += Number(r.arrieres_scolarite || 0);
        cur.nb_eleves += 1;
        parClasseMap.set(r.classe_nom, cur);
      }

      res.json({
        success: true,
        total_arrieres: totalArrieres,
        nb_eleves_avec_arrieres: elevesAvecArrieres.length,
        total_eleves: rows.length,
        taux_eleves_endettes: rows.length > 0 ? Math.round((elevesAvecArrieres.length / rows.length) * 100) : 0,
        repartition_par_classe: Array.from(parClasseMap.values()).sort((a, b) => b.total_arrieres - a.total_arrieres),
        eleves_avec_arrieres: elevesAvecArrieres
      });
    } catch (error: any) {
      console.error("Stats arriérés error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Récupérer l'historique et le détail des arriérés d'un élève par année scolaire
  app.get("/api/eleves/:id/arrieres-par-annee", authenticateToken, (req: any, res) => {
    const eleveId = parseInt(req.params.id);
    const schoolId = req.schoolId || 1;
    const currentYearId = req.anneeId || getActiveYearId(schoolId);

    try {
      const eleve = db.prepare("SELECT * FROM eleves WHERE id = ? AND (school_id = ? OR school_id IS NULL)").get(eleveId, schoolId) as any;
      if (!eleve) return res.status(404).json({ error: "Élève non trouvé" });

      // Toutes les années scolaires enregistrées de l'école
      const allYears = db.prepare("SELECT * FROM annees_scolaires WHERE (school_id = ? OR school_id IS NULL) ORDER BY date_debut DESC, id DESC").all(schoolId) as any[];

      // Années antérieures (non actives ou différentes de l'année courante)
      const pastYears = allYears.filter(y => y.id !== currentYearId);

      // Historique par année dans eleve_annees
      const historyRows = db.prepare(`
        SELECT 
          ea.annee_id,
          ea.classe_id,
          COALESCE(ea.arrieres_scolarite, 0) as arrieres_scolarite,
          a.libelle as annee_libelle,
          a.est_active,
          c.nom as classe_nom,
          COALESCE(c.frais_scolarite, 0) as frais_scolarite
        FROM eleve_annees ea
        JOIN annees_scolaires a ON ea.annee_id = a.id
        LEFT JOIN classes c ON ea.classe_id = c.id
        WHERE ea.eleve_id = ? AND (ea.school_id = ? OR ea.school_id IS NULL)
        ORDER BY a.date_debut DESC, a.id DESC
      `).all(eleveId, schoolId) as any[];

      // Pour chaque année antérieure, calculer les paiements et le solde restant
      const arrieresDetail = pastYears.map((year, idx) => {
        const hist = historyRows.find(h => h.annee_id === year.id);
        
        // Somme des paiements faits directement sous cette année OU ciblant spécifiquement cette année comme annee_concernee_id
        const paymentsRow = db.prepare(`
          SELECT COALESCE(SUM(montant), 0) as total_paye
          FROM paiements
          WHERE eleve_id = ? 
            AND (annee_id = ? OR annee_concernee_id = ?)
            AND (type_paiement = 'Frais de scolarité' OR type_paiement = 'Arriérés de scolarité' OR type_paiement LIKE '%scolarité%' OR type_paiement LIKE '%Arriéré%')
            AND (status = 'Terminé' OR status = 'completed')
        `).get(eleveId, year.id, year.id) as any;

        const totalPaye = Number(paymentsRow?.total_paye || 0);
        const fraisScolarite = Number(hist?.frais_scolarite || 0);
        const arrieresEnregistres = Number(hist?.arrieres_scolarite || 0);

        let resteEstime = 0;
        if (hist) {
          resteEstime = Math.max(0, (fraisScolarite + arrieresEnregistres) - totalPaye);
        } else if (idx === 0) {
          // Si l'élève a un arriéré global et qu'il s'agit de la dernière année antérieure
          resteEstime = Number(eleve.arrieres_scolarite || 0);
        }

        return {
          annee_id: year.id,
          libelle: year.libelle,
          est_active: year.est_active === 1 || year.id === currentYearId,
          classe_nom: hist?.classe_nom || null,
          frais_scolarite: fraisScolarite,
          total_paye: totalPaye,
          reste_a_payer: resteEstime,
          a_frequente: !!hist
        };
      });

      res.json({
        success: true,
        eleve_id: eleveId,
        nom: eleve.nom,
        prenom: eleve.prenom,
        matricule: eleve.matricule,
        arrieres_global: Number(eleve.arrieres_scolarite || 0),
        annees_anterieures: pastYears.map(y => ({ id: y.id, libelle: y.libelle })),
        arrieres_detail: arrieresDetail
      });
    } catch (err: any) {
      console.error("Erreur arrieres par annee:", err);
      res.status(500).json({ error: err.message });
    }
  });

  app.post("/api/paiements", authenticateToken, (req: any, res) => {
    try {
      const { 
        eleve_id, 
        nom_complet, 
        classe_nom, 
        telephone, 
        email, 
        photo, 
        type_paiement, 
        tranche,
        montant, 
        date_paiement, 
        annee_id, 
        annee_concernee_id,
        annee_concernee_libelle,
        methode, 
        reference_transaction,
        note,
        contact_urgence_nom,
        contact_urgence_telephone,
        contact_urgence_adresse,
        date_naissance,
        lieu_naissance,
        adresse,
        ecole_provenance,
        parents_tuteurs
      } = req.body;
      const schoolId = req.schoolId || 1;
      const yearId = annee_id || getActiveYearId(schoolId);

      // Résoudre le libellé de l'année concernée si nécessaire
      let finalAnneeConcerneeId = annee_concernee_id ? parseInt(annee_concernee_id) : null;
      let finalAnneeConcerneeLibelle = annee_concernee_libelle || null;
      if (finalAnneeConcerneeId && !finalAnneeConcerneeLibelle) {
        const yearRow = db.prepare("SELECT libelle FROM annees_scolaires WHERE id = ?").get(finalAnneeConcerneeId) as any;
        finalAnneeConcerneeLibelle = yearRow?.libelle || null;
      }
      
      const info = db.prepare(`
        INSERT INTO paiements (
          eleve_id, type_paiement, tranche, montant, date_paiement, 
          annee_id, annee_concernee_id, annee_concernee_libelle,
          methode, status, reference_transaction, note, school_id
        ) 
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'Terminé', ?, ?, ?)
      `).run(
        eleve_id || null, 
        type_paiement || 'Frais de scolarité', 
        tranche || null, 
        montant, 
        date_paiement || new Date().toISOString().split('T')[0], 
        yearId, 
        finalAnneeConcerneeId,
        finalAnneeConcerneeLibelle,
        methode || 'Espèces', 
        reference_transaction || null, 
        note || null, 
        schoolId
      );

      const paymentId = info.lastInsertRowid;
      let numero_adherent = null;

      // Déduction automatique si le paiement règle des arriérés d'années antérieures
      const isArrieresPayment = 
        type_paiement === 'Arriérés de scolarité' || 
        tranche === 'Arriérés' || 
        tranche === 'Arriérés antérieurs' || 
        (tranche && tranche.toLowerCase().includes('arriéré')) ||
        !!finalAnneeConcerneeId;

      if (eleve_id && isArrieresPayment) {
        // 1. Déduction sur la fiche générale de l'élève
        const curEl = db.prepare("SELECT arrieres_scolarite FROM eleves WHERE id = ?").get(eleve_id) as any;
        const currentStudentArr = Number(curEl?.arrieres_scolarite || 0);
        const newStudentArr = Math.max(0, currentStudentArr - Number(montant || 0));
        db.prepare("UPDATE eleves SET arrieres_scolarite = ? WHERE id = ?").run(newStudentArr, eleve_id);

        // 2. Déduction dans eleve_annees pour l'année courante active
        const curEa = db.prepare("SELECT arrieres_scolarite FROM eleve_annees WHERE eleve_id = ? AND annee_id = ?").get(eleve_id, yearId) as any;
        if (curEa) {
          const currentArr = Number(curEa?.arrieres_scolarite || 0);
          const newArr = Math.max(0, currentArr - Number(montant || 0));
          db.prepare("UPDATE eleve_annees SET arrieres_scolarite = ? WHERE eleve_id = ? AND annee_id = ?").run(newArr, eleve_id, yearId);
        }

        // 3. Déduction sur l'année antérieure concernée si spécifiée
        if (finalAnneeConcerneeId && finalAnneeConcerneeId !== yearId) {
          const pastEa = db.prepare("SELECT arrieres_scolarite FROM eleve_annees WHERE eleve_id = ? AND annee_id = ?").get(eleve_id, finalAnneeConcerneeId) as any;
          if (pastEa) {
            const currentPastArr = Number(pastEa?.arrieres_scolarite || 0);
            const newPastArr = Math.max(0, currentPastArr - Number(montant || 0));
            db.prepare("UPDATE eleve_annees SET arrieres_scolarite = ? WHERE eleve_id = ? AND annee_id = ?").run(newPastArr, eleve_id, finalAnneeConcerneeId);
          }
        }
      }

      // Automatically register or settle library debt if payment type is "Adhésion Bibliothèque"
      if (type_paiement === "Adhésion Bibliothèque") {
        let student: any = null;
        let studentName = nom_complet;
        let studentClass = classe_nom;
        let memberPhoto = photo;

        if (eleve_id) {
          student = db.prepare("SELECT nom, prenom, photo, classe_id FROM eleves WHERE id = ?").get(eleve_id) as any;
          if (student) {
            studentName = `${student.nom || ''} ${student.prenom || ''}`.trim();
            if (!memberPhoto && student.photo) {
              memberPhoto = student.photo;
            }
            if (student.classe_id && !studentClass) {
              const c = db.prepare("SELECT nom FROM classes WHERE id = ?").get(student.classe_id) as any;
              studentClass = c?.nom || null;
            }
            if (photo && !student.photo) {
              try {
                db.prepare("UPDATE eleves SET photo = ? WHERE id = ?").run(photo, eleve_id);
              } catch (e) {}
            }
          }
        }

        // Check if already registered
        const existing = eleve_id 
          ? (db.prepare("SELECT * FROM adherents_bibliotheque WHERE eleve_id = ? AND school_id = ?").get(eleve_id, schoolId) as any)
          : (nom_complet ? (db.prepare("SELECT * FROM adherents_bibliotheque WHERE school_id = ? AND type = 'externe' AND LOWER(TRIM(nom_complet)) = ?").get(schoolId, nom_complet.trim().toLowerCase()) as any) : null);
        
        const nextYear = new Date();
        nextYear.setFullYear(nextYear.getFullYear() + 1);
        const expDateStr = nextYear.toISOString().split('T')[0];
        const payAmount = Number(montant) || 1000;

        if (!existing) {
          const lastId = ((db.prepare("SELECT MAX(id) as maxId FROM adherents_bibliotheque WHERE school_id = ?").get(schoolId) as any)?.maxId || 0) + 1;
          numero_adherent = `ADH-${new Date().getFullYear()}-${String(lastId).padStart(3, '0')}`;
          
          db.prepare(`
            INSERT INTO adherents_bibliotheque (
              numero_adherent, eleve_id, nom_complet, classe_nom, telephone, email, photo,
              date_adhesion, date_expiration, statut, type,
              contact_urgence_nom, contact_urgence_telephone, contact_urgence_adresse,
              date_naissance, lieu_naissance, adresse, ecole_provenance, parents_tuteurs,
              montant_cotisation_du, montant_cotisation_paye, statut_paiement, school_id
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'actif', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'paye', ?)
          `).run(
            numero_adherent,
            eleve_id || null,
            studentName || 'Adhérent',
            studentClass || null,
            telephone || null,
            email || null,
            memberPhoto || null,
            date_paiement || new Date().toISOString().split('T')[0],
            expDateStr,
            eleve_id ? 'eleve' : 'externe',
            contact_urgence_nom || null,
            contact_urgence_telephone || null,
            contact_urgence_adresse || null,
            date_naissance || null,
            lieu_naissance || null,
            adresse || null,
            ecole_provenance || null,
            parents_tuteurs || null,
            payAmount,
            payAmount,
            schoolId
          );
        } else {
          numero_adherent = existing.numero_adherent;
          const newPaidTotal = (existing.montant_cotisation_paye || 0) + payAmount;
          const newDueTotal = Math.max(existing.montant_cotisation_du || 1000, payAmount);
          const newStatutPaye = newPaidTotal >= newDueTotal ? 'paye' : 'partiel';

          db.prepare(`
            UPDATE adherents_bibliotheque SET 
              photo = COALESCE(?, photo),
              statut = 'actif',
              date_expiration = ?,
              montant_cotisation_paye = ?,
              montant_cotisation_du = ?,
              statut_paiement = ?
            WHERE id = ?
          `).run(
            memberPhoto || null,
            expDateStr,
            newPaidTotal,
            newDueTotal,
            newStatutPaye,
            existing.id
          );
        }
      }

      const updatedEleve = eleve_id ? (db.prepare("SELECT arrieres_scolarite FROM eleves WHERE id = ?").get(eleve_id) as any) : null;
      res.json({ 
        success: true, 
        id: Number(paymentId), 
        numero_adherent,
        annee_concernee_id: finalAnneeConcerneeId,
        annee_concernee_libelle: finalAnneeConcerneeLibelle,
        nouveau_solde_arrieres: updatedEleve ? Number(updatedEleve.arrieres_scolarite || 0) : 0
      });
    } catch (error: any) {
      console.error("Payment error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/paiements/fedapay", authenticateToken, async (req: any, res) => {
    try {
      const { eleve_id, type_paiement, montant, date_paiement, student_name } = req.body;
      const yearId = req.anneeId;
      
      // Check if school has custom FedaPay configuration
      const schoolFeda = db.prepare("SELECT * FROM school_payment_methods WHERE school_id = ? AND provider = 'fedapay' AND is_active = 1").get(req.schoolId) as any;
      
      const apiKey = schoolFeda?.secret_key || FEDAPAY_SK;
      const apiMode = schoolFeda?.mode || FEDAPAY_MODE || 'sandbox';

      if (!apiKey) {
          throw new Error('FedaPay n\'est pas configuré pour cet établissement (clé secrète manquante). Veuillez le configurer dans les paramètres.');
      }

      FedaPay.setApiKey(apiKey);
      FedaPay.setEnvironment(apiMode === 'live' ? 'live' : 'sandbox');

      const safeStudentName = student_name || "Élève";
      const studentData = db.prepare("SELECT email_parent, telephone_parent FROM eleves WHERE id = ?").get(eleve_id) as any;

      const transaction = await Transaction.create({
        description: `${type_paiement} pour ${safeStudentName}`,
        amount: Number(montant),
        currency: { iso: 'XOF' },
        callback_url: `${APP_URL}/mon-enfant?payment_status=success`,
        customer: {
          firstname: safeStudentName.split(' ')[0],
          lastname: safeStudentName.split(' ').slice(1).join(' ') || 'Élève',
          email: studentData?.email_parent || 'parent@ecole.com',
          phone_number: {
            number: studentData?.telephone_parent || '00000000',
            country: 'BJ'
          }
        }
      });

      const token = await transaction.generateToken();

      db.prepare(`
        INSERT INTO paiements (eleve_id, type_paiement, montant, date_paiement, annee_id, methode, status, reference_transaction, school_id) 
        VALUES (?, ?, ?, ?, ?, 'FedaPay (En ligne)', 'En cours', ?, ?)
      `).run(eleve_id, type_paiement, montant, date_paiement, yearId, transaction.id, req.schoolId);
      
      res.json({ url: token.url });
    } catch (error: any) {
      console.error("FedaPay error:", error);
      res.status(500).json({ error: error.message });
    }
  });

