  function ensureSchoolPaymentMethods(schoolId: number) {
    const existing = db.prepare("SELECT provider FROM school_payment_methods WHERE school_id = ?").all(schoolId) as { provider: string }[];
    const existingProviders = new Set(existing.map(e => e.provider));

    const insert = db.prepare(`
      INSERT INTO school_payment_methods (
        school_id, provider, label, description, is_active, mode, instructions
      ) VALUES (?, ?, ?, ?, ?, ?, ?)
    `);

    for (const def of DEFAULT_PAYMENT_PROVIDERS) {
      if (!existingProviders.has(def.provider)) {
        insert.run(schoolId, def.provider, def.label, def.description, def.is_active, def.mode, def.instructions);
      }
    }
  }

  // Check if role is admin or fonde
  function isUserAdminOrFonde(userRole: string | undefined): boolean {
    if (!userRole) return false;
    const r = userRole.toLowerCase().trim();
    return r === 'admin' || r === 'super_admin' || r === 'fonde' || r === 'fondé' || r === 'fondateur';
  }

  // GET payment methods (Admin / Fondé only)
  app.get("/api/payment-settings", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }

      const schoolId = req.schoolId || 1;
      ensureSchoolPaymentMethods(schoolId);

      const methods = db.prepare(`
        SELECT * FROM school_payment_methods 
        WHERE school_id = ? 
        ORDER BY id ASC
      `).all(schoolId);

      res.json(methods);
    } catch (error: any) {
      console.error("Error fetching payment settings:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Save / Update payment method (Admin / Fondé only)
  app.post("/api/payment-settings", authenticateToken, (req: any, res) => {
    try {
      if (!isUserAdminOrFonde(req.user?.role)) {
        return res.status(403).json({ error: "Accès réservé exclusivement à l'administrateur (Fondé)" });
      }

      const schoolId = req.schoolId || 1;
      const {
        id,
        provider,
        label,
        description,
        is_active,
        mode,
        public_key,
        secret_key,
        merchant_id,
        merchant_phone,
        account_name,
        bank_rib,
        instructions
      } = req.body;

      if (id) {
        db.prepare(`
          UPDATE school_payment_methods 
          SET label = ?, description = ?, is_active = ?, mode = ?, 
              public_key = ?, secret_key = ?, merchant_id = ?, 
              merchant_phone = ?, account_name = ?, bank_rib = ?, instructions = ?
          WHERE id = ? AND school_id = ?
        `).run(label, description, is_active, mode, public_key, secret_key, merchant_id, merchant_phone, account_name, bank_rib, instructions, id, schoolId);
      } else {
        db.prepare(`
          INSERT INTO school_payment_methods (
            school_id, provider, label, description, is_active, mode, 
            public_key, secret_key, merchant_id, merchant_phone, account_name, bank_rib, instructions
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        `).run(schoolId, provider, label, description, is_active, mode, public_key, secret_key, merchant_id, merchant_phone, account_name, bank_rib, instructions);
      }
      res.json({ success: true });
    } catch (error: any) {
      console.error("Error saving payment settings:", error);
      res.status(500).json({ error: error.message });
    }
  });

  
    // --- EXAM MANAGEMENT SPACE ---

    // GET /api/examen/sessions
    app.get("/api/examen/sessions", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { cycle } = req.query;
        let query = "SELECT * FROM examen_sessions WHERE school_id = ?";
        const params = [schoolId];
        if (cycle) {
          query += " AND cycle = ?";
          params.push(cycle);
        }
        query += " ORDER BY created_at DESC";
        const sessions = db.prepare(query).all(...params);
        res.json(sessions);
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions
    app.post("/api/examen/sessions", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { nom, cycle, type_examen, trimestre, annee_id, date_debut, date_fin } = req.body;
        const result = db.prepare(`
          INSERT INTO examen_sessions (nom, cycle, type_examen, trimestre, annee_id, date_debut, date_fin, school_id)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `).run(nom, cycle, type_examen || 'blanc', trimestre, annee_id, date_debut, date_fin, schoolId);
        res.status(201).json({ id: result.lastInsertRowid });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // GET /api/examen/sessions/:id/epreuves
    app.get("/api/examen/sessions/:id/epreuves", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const epreuves = db.prepare(`
          SELECT e.* 
          FROM epreuves e
          JOIN examen_epreuves ee ON e.id = ee.epreuve_id
          WHERE ee.session_id = ? AND ee.school_id = ?
        `).all(req.params.id, schoolId);
        res.json(epreuves);
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/epreuves
    app.post("/api/examen/sessions/:id/epreuves", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { epreuveIds } = req.body;
        const sessionId = req.params.id;

        const deleteStmt = db.prepare("DELETE FROM examen_epreuves WHERE session_id = ? AND school_id = ?");
        const insertStmt = db.prepare("INSERT INTO examen_epreuves (session_id, epreuve_id, school_id) VALUES (?, ?, ?)");

        const transaction = db.transaction((ids) => {
          deleteStmt.run(sessionId, schoolId);
          for (const eid of ids) {
            insertStmt.run(sessionId, eid, schoolId);
          }
        });

        transaction(epreuveIds);
        res.json({ message: "Épreuves mises à jour." });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/publish
    app.post("/api/examen/sessions/:id/publish", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const sessionId = req.params.id;
        const { bulletin_telechargeable = 1 } = req.body || {};
        
        db.prepare("UPDATE examen_sessions SET est_publie = 1, statut = 'termine', bulletin_telechargeable = ? WHERE id = ? AND school_id = ?")
          .run(bulletin_telechargeable ? 1 : 0, sessionId, schoolId);
        
        const session = db.prepare("SELECT * FROM examen_sessions WHERE id = ?").get(sessionId) as any;
        
        // Send notifications to parents and students
        const candidates = db.prepare(`
          SELECT ec.eleve_id, e.nom, e.prenom, e.email_parent, ec.numero_table
          FROM examen_candidats ec
          JOIN eleves e ON ec.eleve_id = e.id
          WHERE ec.session_id = ? AND ec.school_id = ?
        `).all(sessionId, schoolId) as any[];

        const notifyStmt = db.prepare(`
          INSERT INTO notifications (utilisateur_id, titre, message, type, school_id)
          VALUES (?, ?, ?, ?, ?)
        `);

        for (const cand of candidates) {
          // Find student user account
          const studentUser = db.prepare("SELECT id FROM utilisateurs WHERE eleve_id = ?").get(cand.eleve_id) as any;
          if (studentUser) {
            notifyStmt.run(studentUser.id, `Résultat Examen: ${session.nom}`, `Votre résultat pour l'examen ${session.nom} est disponible.`, 'info', schoolId);
          }
          // Find parent user account
          const parentUser = db.prepare("SELECT u.id FROM utilisateurs u JOIN eleves e ON e.id = u.eleve_id WHERE e.id = ? AND u.role = 'parent'").get(cand.eleve_id) as any;
          if (parentUser) {
            const dlText = bulletin_telechargeable ? "Le relevé de notes est téléchargeable dans votre espace parent." : "La consultation est ouverte (téléchargement du relevé verrouillé).";
            notifyStmt.run(parentUser.id, `Résultat Examen: ${cand.prenom} ${cand.nom}`, `Le résultat de ${cand.prenom} pour l'examen ${session.nom} est publié. ${dlText}`, 'info', schoolId);
          }
        }

        res.json({ message: "Résultats d'examen publiés et notifications envoyées.", est_publie: 1, bulletin_telechargeable: bulletin_telechargeable ? 1 : 0 });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/unpublish
    app.post("/api/examen/sessions/:id/unpublish", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const sessionId = req.params.id;
        db.prepare("UPDATE examen_sessions SET est_publie = 0, statut = 'ouvert' WHERE id = ? AND school_id = ?").run(sessionId, schoolId);
        res.json({ message: "Session d'examen dépubliée avec succès.", est_publie: 0 });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/toggle-bulletin-lock
    app.post("/api/examen/sessions/:id/toggle-bulletin-lock", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const sessionId = req.params.id;
        const { bulletin_telechargeable } = req.body;
        db.prepare("UPDATE examen_sessions SET bulletin_telechargeable = ? WHERE id = ? AND school_id = ?").run(bulletin_telechargeable ? 1 : 0, sessionId, schoolId);
        res.json({ success: true, bulletin_telechargeable: bulletin_telechargeable ? 1 : 0 });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/import-notes
    app.post("/api/examen/sessions/:id/import-notes", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const sessionId = req.params.id;
        const { rows } = req.body;

        if (!Array.isArray(rows)) {
          return res.status(400).json({ error: "Format invalide: 'rows' doit être un tableau" });
        }

        const candidates = db.prepare(`
          SELECT ec.id, ec.eleve_id, ec.numero_table, e.matricule, e.nom, e.prenom
          FROM examen_candidats ec
          JOIN eleves e ON ec.eleve_id = e.id
          WHERE ec.session_id = ? AND ec.school_id = ?
        `).all(sessionId, schoolId) as any[];

        const epreuves = db.prepare(`
          SELECT ee.id as epreuve_session_id, ee.epreuve_id, e.matiere_id, m.nom as matiere_nom
          FROM examen_epreuves ee
          JOIN epreuves e ON ee.epreuve_id = e.id
          JOIN matieres m ON e.matiere_id = m.id
          WHERE ee.session_id = ? AND ee.school_id = ?
        `).all(sessionId, schoolId) as any[];

        const upsertNoteStmt = db.prepare(`
          INSERT INTO examen_notes (session_id, candidat_id, eleve_id, epreuve_id, matiere_id, note, school_id)
          VALUES (?, ?, ?, ?, ?, ?, ?)
          ON CONFLICT(session_id, eleve_id, matiere_id) DO UPDATE SET
            note = excluded.note,
            epreuve_id = excluded.epreuve_id,
            updated_at = CURRENT_TIMESTAMP
        `);

        let importedCount = 0;
        const transaction = db.transaction(() => {
          for (const row of rows) {
            const cand = candidates.find(c => 
              (row.eleve_id && c.eleve_id === Number(row.eleve_id)) ||
              (row.numero_table && c.numero_table && c.numero_table.toString().trim() === row.numero_table.toString().trim()) ||
              (row.matricule && c.matricule && c.matricule.toString().trim().toLowerCase() === row.matricule.toString().trim().toLowerCase())
            );
            if (!cand) continue;

            const epr = epreuves.find(ep => 
              (row.matiere_id && ep.matiere_id === Number(row.matiere_id)) ||
              (row.epreuve_id && (ep.epreuve_id === Number(row.epreuve_id) || ep.epreuve_session_id === Number(row.epreuve_id))) ||
              (row.matiere_nom && ep.matiere_nom.toLowerCase().trim() === row.matiere_nom.toLowerCase().trim())
            );
            if (!epr) continue;

            const val = parseFloat(row.note);
            if (isNaN(val) || val < 0 || val > 20) continue;

            upsertNoteStmt.run(sessionId, cand.id, cand.eleve_id, epr.epreuve_session_id || epr.epreuve_id, epr.matiere_id, val, schoolId);
            importedCount++;
          }
        });

        transaction();
        res.json({ message: `${importedCount} notes d'examen importées avec succès.`, count: importedCount });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // DELETE /api/examen/sessions/:id
    app.delete("/api/examen/sessions/:id", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        db.prepare("DELETE FROM examen_sessions WHERE id = ? AND school_id = ?").run(req.params.id, schoolId);
        res.json({ message: "Session supprimée." });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // GET /api/examen/sessions/:id/candidats
    app.get("/api/examen/sessions/:id/candidats", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const candidates = db.prepare(`
          SELECT ec.*, e.nom, e.prenom, e.matricule, c.nom as classe_nom, c.niveau
          FROM examen_candidats ec
          JOIN eleves e ON ec.eleve_id = e.id
          JOIN classes c ON e.classe_id = c.id
          WHERE ec.session_id = ? AND ec.school_id = ?
          ORDER BY c.nom, e.nom, e.prenom
        `).all(req.params.id, schoolId);
        res.json(candidates);
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/candidats/batch-select
    app.post("/api/examen/sessions/:id/candidats/batch-select", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { id } = req.params;
        const { eleveIds } = req.body;

        if (!eleveIds || !Array.isArray(eleveIds)) {
          return res.status(400).json({ error: "eleveIds est requis" });
        }

        const insertStmt = db.prepare(`
          INSERT OR IGNORE INTO examen_candidats (session_id, eleve_id, school_id)
          VALUES (?, ?, ?)
        `);

        const transaction = db.transaction((ids) => {
          for (const eleveId of ids) {
            insertStmt.run(id, eleveId, schoolId);
          }
        });

        transaction(eleveIds);
        res.json({ message: "Candidats sélectionnés ajoutés avec succès." });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // DELETE /api/examen/sessions/:sessionId/candidats/:candidateId
    app.delete("/api/examen/sessions/:sessionId/candidats/:candidateId", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        db.prepare("DELETE FROM examen_candidats WHERE id = ? AND session_id = ? AND school_id = ?")
          .run(req.params.candidateId, req.params.sessionId, schoolId);
        res.json({ message: "Candidat retiré." });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/candidats/batch
    app.post("/api/examen/sessions/:id/candidats/batch", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { session_id } = req.params;
        const { classIds } = req.body;

        if (!classIds || !Array.isArray(classIds)) {
          return res.status(400).json({ error: "classIds est requis" });
        }

        const insertStmt = db.prepare(`
          INSERT OR IGNORE INTO examen_candidats (session_id, eleve_id, school_id)
          SELECT ?, id, ? FROM eleves WHERE classe_id = ? AND (school_id = ? OR school_id IS NULL)
        `);

        const transaction = db.transaction((ids) => {
          for (const classId of ids) {
            insertStmt.run(session_id, schoolId, classId, schoolId);
          }
        });

        transaction(classIds);
        res.json({ message: "Candidats ajoutés avec succès." });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/generate-numbers
    app.post("/api/examen/sessions/:id/generate-numbers", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { id } = req.params;
        const { prefix = "T", startAt = 1 } = req.body;

        const candidates = db.prepare(`
          SELECT ec.id
          FROM examen_candidats ec
          JOIN eleves e ON ec.eleve_id = e.id
          JOIN classes c ON e.classe_id = c.id
          WHERE ec.session_id = ? AND ec.school_id = ?
          ORDER BY c.nom, e.nom, e.prenom
        `).all(id, schoolId) as any[];

        const updateStmt = db.prepare("UPDATE examen_candidats SET numero_table = ? WHERE id = ?");
        
        const transaction = db.transaction((list) => {
          let currentNum = startAt;
          for (const cand of list) {
            const numStr = `${prefix}${String(currentNum).padStart(4, '0')}`;
            updateStmt.run(numStr, cand.id);
            currentNum++;
          }
        });

        transaction(candidates);
        res.json({ message: "Numéros de table générés avec succès.", count: candidates.length });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // GET /api/examen/sessions/:id/notes
    app.get("/api/examen/sessions/:id/notes", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { id } = req.params;
        const notes = db.prepare(`
          SELECT * FROM examen_notes WHERE session_id = ? AND school_id = ?
        `).all(id, schoolId);
        res.json(notes);
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // POST /api/examen/sessions/:id/notes/batch
    app.post("/api/examen/sessions/:id/notes/batch", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { id } = req.params;
        const { notes } = req.body;

        const upsertStmt = db.prepare(`
          INSERT INTO examen_notes (session_id, eleve_id, matiere_id, note, school_id)
          VALUES (?, ?, ?, ?, ?)
          ON CONFLICT(session_id, eleve_id, matiere_id) DO UPDATE SET note = excluded.note
        `);

        const transaction = db.transaction((notesList) => {
          for (const n of notesList) {
            upsertStmt.run(id, n.eleve_id, n.matiere_id, n.note, schoolId);
          }
        });

        transaction(notes);
        res.json({ message: "Notes enregistrées avec succès." });
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

    // GET /api/examen/sessions/:id/results
    app.get("/api/examen/sessions/:id/results", authenticateToken, (req: any, res) => {
      try {
        const schoolId = req.schoolId || 1;
        const { id } = req.params;

        const results = db.prepare(`
          SELECT 
            e.id as eleve_id,
            e.nom,
            e.prenom,
            ec.numero_table,
            c.nom as classe_nom,
            SUM(en.note * m.coefficient) / SUM(m.coefficient) as moyenne,
            SUM(en.note * m.coefficient) as total_points,
            SUM(m.coefficient) as total_coeffs,
            json_group_array(
              json_object(
                'matiere_id', m.id,
                'matiere_nom', m.nom,
                'coefficient', m.coefficient,
                'note', en.note
              )
            ) as notes
          FROM examen_candidats ec
          JOIN eleves e ON ec.eleve_id = e.id
          JOIN classes c ON e.classe_id = c.id
          LEFT JOIN examen_notes en ON en.eleve_id = e.id AND en.session_id = ec.session_id
          LEFT JOIN matieres m ON en.matiere_id = m.id
          WHERE ec.session_id = ? AND ec.school_id = ?
          GROUP BY e.id
          ORDER BY moyenne DESC
        `).all(id, schoolId);

        // Parse JSON notes for each result
        const resultsWithNotes = results.map((r: any) => ({
          ...r,
          notes: JSON.parse(r.notes).filter((n: any) => n.matiere_id !== null)
        }));

        res.json(resultsWithNotes);
      } catch (error: any) {
        res.status(500).json({ error: error.message });
      }
    });

